INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('101ceb21-6e66-457b-91b4-7d5ce891c4a0', '送僧遊龍門香山寺', '送僧游龙门香山寺', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["君到香山寺，探幽莫損神。","且尋風雅主，細看樂天真。"]', '["君到香山寺，探幽莫損神。","且尋风雅主，細看乐天真。"]', '诗', 'shi', '', NULL, '送僧遊龍門香山寺 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('be0d5be9-5b04-4d28-8556-1f039ca31a99', '江上值春雨', '江上值春雨', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["江臯正月雨，平陸亦波瀾。","半是峨嵋雪，重爲澤國寒。","農田淹寖盡，客櫂往來難。","愁殺騷人路，滄浪正渺漫。"]', '["江臯正月雨，平陸亦波瀾。","半是峨嵋雪，重爲澤国寒。","農田淹寖尽，客櫂往来难。","愁殺騷人路，滄浪正渺漫。"]', '诗', 'shi', '', NULL, '江上值春雨 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f300006-2568-4c7e-a6d8-45d674dc30ab', '七十作', '七十作', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["七十去百歲，都來三十春。","縱饒生得到，終免死無因。","密理方通理，栖真始見真。","沃洲匡阜客，幾劫不迷人。"]', '["七十去百歲，都来三十春。","縱饒生得到，終免死無因。","密理方通理，栖真始见真。","沃洲匡阜客，幾劫不迷人。"]', '诗', 'shi', '', NULL, '七十作 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aac88dd4-40e4-48e0-b613-e22b305ef1e6', '謝虛中寄新詩', '謝虛中寄新诗', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["舊友一千里，新詩五十篇。","此文經大匠，不見已多年。","趣極同無迹，精深合自然。","相思把行坐，南望隔塵煙。"]', '["旧友一千里，新诗五十篇。","此文經大匠，不见已多年。","趣極同無迹，精深合自然。","相思把行坐，南望隔塵煙。"]', '诗', 'shi', '', NULL, '謝虛中寄新詩 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f2f9f1d7-4122-41b2-ac92-357d0fe05e00', '送彬座主赴龍安請講', '送彬座主赴龙安請講', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["兩論久研精，龍安受請行。","春城雨雪霽，古寺殿堂明。","白髮老僧聽，金毛師子聲。","同流有誰共，別著國風清。"]', '["兩論久研精，龙安受請行。","春城雨雪霽，古寺殿堂明。","白髮老僧听，金毛師子声。","同流有誰共，別著国风清。"]', '诗', 'shi', '', NULL, '送彬座主赴龍安請講 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a4c5f940-e701-45ec-ae27-7b63cae6ae7d', '夏日荆渚書懷', '夏日荆渚书懷', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["嵩岳去值亂，匡廬迴阻兵。","中途息瓶錫，十載依公卿。","不那猨鳥性，但懷林泉聲。","何時遂情興，吟遶杉松行。"]', '["嵩岳去值亂，匡廬迴阻兵。","中途息瓶錫，十載依公卿。","不那猨鸟性，但懷林泉声。","何时遂情兴，吟遶杉松行。"]', '诗', 'shi', '', NULL, '夏日荆渚書懷 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('25eab67e-065e-4ca3-9464-9b55a950813c', '春日西湖作', '春日西湖作', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["一水遶孤島，閑門掩春草。","曾無長者轍，枉此問衰老。"]', '["一水遶孤島，闲门掩春草。","曾無长者轍，枉此问衰老。"]', '诗', 'shi', '', NULL, '春日西湖作 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('32796434-5818-4ebb-ab20-16e6d6951086', '謝中上人寄茶', '謝中上人寄茶', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["春山穀雨前，併手摘芳煙。","綠嫩難盈籠，清和易晚天。","且招鄰院客，試煮落花泉。","地遠勞相寄，無來又隔年。"]', '["春山穀雨前，併手摘芳煙。","綠嫩难盈籠，清和易晚天。","且招鄰院客，試煮落花泉。","地远勞相寄，無来又隔年。"]', '诗', 'shi', '', NULL, '謝中上人寄茶 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dd83d4bd-984a-4b86-9b25-abea03996ac4', '送節大德歸闕', '送節大德归闕', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["西京曾入內，東洛又朝天。","聖上方虛席，僧中正乏賢。","晨光金殿裏，紫氣玉簾前。","知祝唐堯化，新恩異往年。"]', '["西京曾入內，东洛又朝天。","聖上方虛席，僧中正乏賢。","晨光金殿裏，紫氣玉簾前。","知祝唐堯化，新恩異往年。"]', '诗', 'shi', '', NULL, '送節大德歸闕 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dab0b054-181b-4058-aca9-7fdd9f1fe00d', '覽清尚卷', '覽清尚卷', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["李洞僻相似，得詩先示師。","鬼神迷去處，風日背吟時。","格已搜清竭，名還着紫卑。","從容味高作，翻爲古人疑。"]', '["李洞僻相似，得诗先示師。","鬼神迷去处，风日背吟时。","格已搜清竭，名還着紫卑。","從容味高作，翻爲古人疑。"]', '诗', 'shi', '', NULL, '覽清尚卷 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('adee4133-be4b-4325-8c55-752c589be191', '荆門送晝公歸彭澤舊居', '荆门送晝公归彭澤旧居', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["彭澤舊居在，匡廬翠疊前。","因思從楚寺，便附入吳船。","岸遶春殘樹，江浮曉霽天。","應過虎溪社，佇立想諸賢。"]', '["彭澤旧居在，匡廬翠叠前。","因思從楚寺，便附入吳船。","岸遶春殘樹，江浮晓霽天。","應過虎溪社，佇立想諸賢。"]', '诗', 'shi', '', NULL, '荆門送晝公歸彭澤舊居 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a0ef495-fc54-48d2-ae3e-e9bd88ab8523', '登祝融峯', '登祝融峯', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["猨鳥共不到，我來身欲浮。","四邊空碧落，絕頂正清秋。","宇宙知何極，華夷見細流。","壇西獨立久，白日轉神州。"]', '["猨鸟共不到，我来身欲浮。","四邊空碧落，絕頂正清秋。","宇宙知何極，华夷见細流。","壇西独立久，白日轉神州。"]', '诗', 'shi', '', NULL, '登祝融峯 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('65e9f151-6e57-4d6e-bb55-fa20321f0992', '寄貫休', '寄貫休', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["子美曾吟處，吾師復去吟。","是何多勝地，銷得二公心。","錦水流春闊，峨嵋疊雪深。","時逢蜀僧說，或道近遊黔。"]', '["子美曾吟处，吾師复去吟。","是何多勝地，銷得二公心。","錦水流春闊，峨嵋叠雪深。","时逢蜀僧说，或道近游黔。"]', '诗', 'shi', '', NULL, '寄貫休 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('012628f0-7000-4266-9d08-9f17234f9c35', '送唐稟正字歸萍川', '送唐稟正字归萍川', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["霜鬚芸閣吏，久掩白雲扉。","來謁元戎後，還騎病馬歸。","煙村蔬飲淡，江驛雪泥肥。","知到中林日，春風長澗薇。"]', '["霜鬚芸閣吏，久掩白云扉。","来謁元戎後，還騎病马归。","煙村蔬饮淡，江驛雪泥肥。","知到中林日，春风长澗薇。"]', '诗', 'shi', '', NULL, '送唐稟正字歸萍川 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2bc4e451-749c-4b0e-a0e1-91eaf750b679', '寄懷江西栖公', '寄懷江西栖公', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["龍沙爲別日，廬阜得書年。","不見來香社，相思遶白蓮。","江僧歸海寺，楚路接吳煙。","老病何堪說，扶羸寄此篇。"]', '["龙沙爲別日，廬阜得书年。","不见来香社，相思遶白蓮。","江僧归海寺，楚路接吳煙。","老病何堪说，扶羸寄此篇。"]', '诗', 'shi', '', NULL, '寄懷江西栖公 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d9f31c2-c991-4291-9e0e-a77b877719a2', '山中喜得友生書', '山中喜得友生书', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["柴門關樹石，未省夢塵埃。","落日啼猨裏，同人有信來。","自成爲拙隱，難以謝多才。","見說相思處，前峯對古臺。"]', '["柴门关樹石，未省梦塵埃。","落日啼猨裏，同人有信来。","自成爲拙隐，难以謝多才。","见说相思处，前峯对古台。"]', '诗', 'shi', '', NULL, '山中喜得友生書 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('36f396a8-4e27-466a-89ea-77a57dc8a632', '謝人惠扇子及茶', '謝人惠扇子及茶', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["鎗旗封蜀茗，圓潔製鮫綃。","好客分烹煮，青蠅避動搖。","陸生誇妙法，班女恨涼飆。","多謝崔居士，相思寄寂寥。"]', '["鎗旗封蜀茗，圓潔製鮫綃。","好客分烹煮，青蠅避动搖。","陸生誇妙法，班女恨涼飆。","多謝崔居士，相思寄寂寥。"]', '诗', 'shi', '', NULL, '謝人惠扇子及茶 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9cc69a02-6180-4801-8378-d9f7f2e4b6d9', '寄監利司空學士', '寄監利司空学士', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["詩家爲政別，清苦日聞新。","亂後無荒地，歸來盡遠人。","寬容民賦稅，憔悴吏精神。","何必河陽縣，空傳桃李春。"]', '["诗家爲政別，清苦日闻新。","亂後無荒地，归来尽远人。","寬容民賦稅，憔悴吏精神。","何必河陽縣，空傳桃李春。"]', '诗', 'shi', '', NULL, '寄監利司空學士 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba9d2070-76f4-4239-984d-a8999ed41639', '荅陳秀才', '荅陳秀才', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["萬事皆可了，有詩門最深。","古人難得志，吾子苦留心。","野疊涼雲朵，苔重怪木陰。","他年立名字，笑我老雙林。"]', '["万事皆可了，有诗门最深。","古人难得志，吾子苦留心。","野叠涼云朵，苔重怪木陰。","他年立名字，笑我老雙林。"]', '诗', 'shi', '', NULL, '荅陳秀才 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b720442-c06f-4d1c-9bd6-b77fe6b8f866', '遊橘洲', '游橘洲', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["春日上芳洲，經春蘭杜幽。","此時尋橘岸，昨日在城樓。","鷺立青楓杪，沙沈白浪頭。","漁家好生計，簷底繫扁舟。"]', '["春日上芳洲，經春蘭杜幽。","此时尋橘岸，昨日在城楼。","鷺立青楓杪，沙沈白浪头。","漁家好生計，簷底繫扁舟。"]', '诗', 'shi', '', NULL, '遊橘洲 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80fbef34-d9af-46b6-a956-eae7d192aa37', '寄武陵道友', '寄武陵道友', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["阮肇迷仙處，禪門接紫霞。","不知尋鶴路，幾里入桃花。","晚樹陰搖蘚，春潭影弄砂。","何當見招我，乞與片生涯。"]', '["阮肇迷仙处，禪门接紫霞。","不知尋鹤路，幾里入桃花。","晚樹陰搖蘚，春潭影弄砂。","何當见招我，乞與片生涯。"]', '诗', 'shi', '', NULL, '寄武陵道友 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a150b95-ea6a-4072-9e97-7a5df29a24e9', '謝人惠藥', '謝人惠藥', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["五金元造化，九鍊更精新。","敢謂長生客，將遺必死人。","久餐應換骨，一服已通神。","終逐淮王去，永拋浮世塵。"]', '["五金元造化，九鍊更精新。","敢謂长生客，將遺必死人。","久餐應換骨，一服已通神。","終逐淮王去，永拋浮世塵。"]', '诗', 'shi', '', NULL, '謝人惠藥 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c50308e-e896-4d0b-94eb-20eaf22548f8', '還族弟卷', '還族弟卷', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["豈要私相許，君詩自入神。","風騷何句出，瀑布一聯新。","□若長如此，名須遠逐身。","閑齋舒復卷，留滯忽經旬。"]', '["豈要私相許，君诗自入神。","风騷何句出，瀑布一聯新。","□若长如此，名須远逐身。","闲斋舒复卷，留滯忽經旬。"]', '诗', 'shi', '', NULL, '還族弟卷 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9b02980-23c1-4110-a92c-1f079197b3a9', '送周秀遊峽', '送周秀游峽', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["又向夔城去，知難動旅魂。","自非亡國客，何慮斷腸猨。","灩澦分高仞，瞿塘露淺痕。","明年期此約，平穩到荆門。"]', '["又向夔城去，知难动旅魂。","自非亡国客，何慮斷腸猨。","灩澦分高仞，瞿塘露淺痕。","明年期此約，平穩到荆门。"]', '诗', 'shi', '', NULL, '送周秀遊峽 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('130b988b-2ffd-46bc-8118-410a3dd0fdb6', '荆門夏日寄洞山節公', '荆门夏日寄洞山節公', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["湖光搖翠木，靈洞疊雲深。","五月經行處，千秋檜栢陰。","山形臨北渚，僧格繼東林。","莫惜相招信，余心是此心。"]', '["湖光搖翠木，靈洞叠云深。","五月經行处，千秋檜栢陰。","山形臨北渚，僧格繼东林。","莫惜相招信，余心是此心。"]', '诗', 'shi', '', NULL, '荆門夏日寄洞山節公 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('27250571-0a5b-4ec5-8f65-ed85059d204d', '再經蔣山與諸長老夜話', '再經蔣山與諸长老夜話', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["遠迹都如雁，南行又北迴。","老僧猶記得，往歲已曾來。","話遍名山境，燒殘黑櫟灰。","無因伴師往，歸思在天台。"]', '["远迹都如雁，南行又北迴。","老僧猶記得，往歲已曾来。","話遍名山境，燒殘黑櫟灰。","無因伴師往，归思在天台。"]', '诗', 'shi', '', NULL, '再經蔣山與諸長老夜話 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('48312d91-56b2-4efc-af18-64b74d089427', '寄當陽張明府', '寄當陽張明府', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["玉泉神運寺，寒磬徹琴堂。","有境靈如此，爲官興亦長。","吏愁清白甚，民樂賦輸忘。","聞說巴山縣，今來尚憶張。"]', '["玉泉神運寺，寒磬徹琴堂。","有境靈如此，爲官兴亦长。","吏愁清白甚，民乐賦輸忘。","闻说巴山縣，今来尚憶張。"]', '诗', 'shi', '', NULL, '寄當陽張明府 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('653dc6c0-5bd2-4925-9463-9f981126e6b2', '遊三覺山', '游三覺山', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["白石路重重，縈紆勢忽窮。","孤峯擎像閣，萬木蔽星空。","世論隨時變，禪懷歷劫同。","良宵正冥目，海日上窗紅。"]', '["白石路重重，縈紆勢忽窮。","孤峯擎像閣，万木蔽星空。","世論隨时变，禪懷歷劫同。","良宵正冥目，海日上窗紅。"]', '诗', 'shi', '', NULL, '遊三覺山 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('41f6bd08-177e-484c-9bd5-60fd076528ed', '庭際晚菊上主人', '庭際晚菊上主人', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["九月將欲盡，幽叢始綻芳。","都緣含正氣，不是背重陽。","採去蜂聲遠，尋來蝶路長。","王孫歸未晚，猶得泛金觴。"]', '["九月將欲尽，幽叢始綻芳。","都緣含正氣，不是背重陽。","採去蜂声远，尋来蝶路长。","王孫归未晚，猶得泛金觴。"]', '诗', 'shi', '', NULL, '庭際晚菊上主人 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7b7ebab-e5f7-48c9-8eef-0cfc1b6a6a88', '送趙長史歸閩川', '送趙长史归閩川', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["荆門與閩越，關戍隔三千。","風雪揚帆去，臺隍指海邊。","客情消旅火，王化似堯年。","莫失春迴約，江城穀雨前。"]', '["荆门與閩越，关戍隔三千。","风雪揚帆去，台隍指海邊。","客情消旅火，王化似堯年。","莫失春迴約，江城穀雨前。"]', '诗', 'shi', '', NULL, '送趙長史歸閩川 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae2faebf-6c7b-483e-b114-e21a162bf02f', '擬嵇康絕交寄湘中貫微', '擬嵇康絕交寄湘中貫微', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["何處同嵇懶，吾徒道異諸。","本無文字學，何有往來書。","嶽寺逍遙夢，侯門勉強居。","相知在玄契，莫訝八行疎。"]', '["何处同嵇懶，吾徒道異諸。","本無文字学，何有往来书。","嶽寺逍遙梦，侯门勉強居。","相知在玄契，莫訝八行疎。"]', '诗', 'shi', '', NULL, '擬嵇康絕交寄湘中貫微 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('377f8157-763c-4911-9620-67afa7ac5ae8', '寄許州清古', '寄許州清古', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["北來儒士說，許下有吟僧。","白日身長倚，清秋塔上層。","言雖依景得，理要入無徵。","敢望多相示，孱微老不勝。"]', '["北来儒士说，許下有吟僧。","白日身长倚，清秋塔上層。","言雖依景得，理要入無徵。","敢望多相示，孱微老不勝。"]', '诗', 'shi', '', NULL, '寄許州清古 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a5c0ef43-fd52-4e7a-b7c7-6af4f527c806', '謝丁秀才見示賦卷', '謝丁秀才见示賦卷', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["五首新裁翦，搜羅盡指歸。","誰曾師古律，君自負天機。","聖后求賢久，明公得雋稀。","乘秋好攜去，直望九霄飛。"]', '["五首新裁翦，搜羅尽指归。","誰曾師古律，君自負天機。","聖后求賢久，明公得雋稀。","乘秋好携去，直望九霄飞。"]', '诗', 'shi', '', NULL, '謝丁秀才見示賦卷 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c74f141-7829-4aa1-8531-733b28cccef8', '驚秋', '驚秋', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["褰簾聽秋信，晚傍竹聲歸。","多故堪傷骨，孤峯好拂衣。","梧桐凋綠盡，菡萏墮紅稀。","却恐吾形影，嫌心與口違。"]', '["褰簾听秋信，晚傍竹声归。","多故堪傷骨，孤峯好拂衣。","梧桐凋綠尽，菡萏墮紅稀。","却恐吾形影，嫌心與口違。"]', '诗', 'shi', '', NULL, '驚秋 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ddb23fd-e5bf-4b01-bd37-cc986da31a75', '夏日雨中寄幕中知己', '夏日雨中寄幕中知己', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["北風吹夏雨，和竹亞南軒。","豆枕欹涼冷，蓮峯入夢魂。","窗多斜迸濕，庭徧瀑流痕。","清興知無限，晴來示一言。"]', '["北风吹夏雨，和竹亞南軒。","豆枕欹涼冷，蓮峯入梦魂。","窗多斜迸濕，庭徧瀑流痕。","清兴知無限，晴来示一言。"]', '诗', 'shi', '', NULL, '夏日雨中寄幕中知己 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b90db8fa-9e35-4fa5-90b4-5a2848728e66', '夜次湘陰', '夜次湘陰', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["風濤出洞庭，帆影入澄清。","何處驚鴻起，孤舟趂月行。","時難多戰地，野闊絕春耕。","骨肉知存否，林園近郡城。"]', '["风濤出洞庭，帆影入澄清。","何处驚鴻起，孤舟趂月行。","时难多戰地，野闊絕春耕。","骨肉知存否，林园近郡城。"]', '诗', 'shi', '', NULL, '夜次湘陰 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e1757c5c-b293-4c17-8e4b-3c431000c59c', '寄唐稟正字', '寄唐稟正字', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["疎野還如舊，何曾稱在城。","水邊無伴立，天際有山橫。","落日雲霞赤，高窗筆硯明。","鮑昭多所得，時憶寄湯生。"]', '["疎野還如旧，何曾稱在城。","水邊無伴立，天際有山橫。","落日云霞赤，高窗笔硯明。","鲍昭多所得，时憶寄湯生。"]', '诗', 'shi', '', NULL, '寄唐稟正字 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b6048fa-3de7-4fa4-a705-554f25cc8d68', '宿舒湖希上人房', '宿舒湖希上人房', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["入寺先來此，經窗半在湖。","秋風新菡萏，暮雨老菰蒲。","任聽浮生速，能消默坐無。","語來燈焰短，嘒唳發高梧。"]', '["入寺先来此，經窗半在湖。","秋风新菡萏，暮雨老菰蒲。","任听浮生速，能消默坐無。","語来灯焰短，嘒唳發高梧。"]', '诗', 'shi', '', NULL, '宿舒湖希上人房 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb8708d4-9150-4e59-95ae-0cea61f098dc', '戊辰歲江南感懷', '戊辰歲江南感懷', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["忽忽動中私，人間何所之。","老過離亂世，生在太平時。","桃李春無主，杉松寺有期。","曾吟子山賦，何啻舊凌遲。"]', '["忽忽动中私，人间何所之。","老過離亂世，生在太平时。","桃李春無主，杉松寺有期。","曾吟子山賦，何啻旧凌遲。"]', '诗', 'shi', '', NULL, '戊辰歲江南感懷 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b99dc438-cfdf-4e8a-b890-7fd9311608a4', '送林上人歸永嘉舊居', '送林上人归永嘉旧居', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["東越常懸思，山門在永嘉。","秋光浮楚水，帆影背長沙。","城黑天台雨，村明海嶠霞。","時尋謝公跡，春草有瑤花。"]', '["东越常懸思，山门在永嘉。","秋光浮楚水，帆影背长沙。","城黑天台雨，村明海嶠霞。","时尋謝公跡，春草有瑤花。"]', '诗', 'shi', '', NULL, '送林上人歸永嘉舊居 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('db3f5064-de5e-462c-81f2-d4cef62027a9', '荅友生山居寄示', '荅友生山居寄示', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["嘉遁有新吟，因僧寄竹林。","靜思來鳥外，閑味遶松陰。","兵寇憑凌甚，溪山幾許深。","休爲反招隱，攜取一相尋。"]', '["嘉遁有新吟，因僧寄竹林。","静思来鸟外，闲味遶松陰。","兵寇憑凌甚，溪山幾許深。","休爲反招隐，携取一相尋。"]', '诗', 'shi', '', NULL, '荅友生山居寄示 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('868d338b-f7f2-42b8-a5ba-3e1ccbf159d8', '新秋霽後晚眺懷先公', '新秋霽後晚眺懷先公', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["雨霽湘楚晚，水涼天亦澄。","山中應解夏，渡口有行僧。","鳥列滄洲隊，雲排碧落層。","孤峯磬聲絕，一點石龕燈。"]', '["雨霽湘楚晚，水涼天亦澄。","山中應解夏，渡口有行僧。","鸟列滄洲隊，云排碧落層。","孤峯磬声絕，一点石龕灯。"]', '诗', 'shi', '', NULL, '新秋霽後晚眺懷先公 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('948ca68b-3617-4024-ae29-dbc18fe6c9b7', '池上感興', '池上感兴', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["所向似無端，風前吟凭欄。","旁人應悶見，片水自閑看。","碧底紅鱗鬣，澄邊白羽翰。","南山衆木葉，飄著竹聲乾。"]', '["所向似無端，风前吟凭欄。","旁人應悶见，片水自闲看。","碧底紅鱗鬣，澄邊白羽翰。","南山衆木葉，飄著竹声乾。"]', '诗', 'shi', '', NULL, '池上感興 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('44e94f48-009f-4fb2-adc0-b1d00643e339', '和曇域上人寄贈之什', '和曇域上人寄贈之什', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["百病煎衰朽，栖遲戰國中。","思量青壁寺，行坐赤松風。","道寄虛無合，書傳往復空。","可憐禪月子，香火國門東。"]', '["百病煎衰朽，栖遲戰国中。","思量青壁寺，行坐赤松风。","道寄虛無合，书傳往复空。","可怜禪月子，香火国门东。"]', '诗', 'shi', '', NULL, '和曇域上人寄贈之什 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6e1d9deb-7fc0-48cc-a171-49c863272e7f', '弔雙泉大師真塔', '弔雙泉大師真塔', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["塔聳層峯後，碑鐫巨石新。","不知將一句，分付與何人。","靜坐雲生衲，空山月照真。","後徒遊禮者，猶認指迷津。"]', '["塔聳層峯後，碑鐫巨石新。","不知將一句，分付與何人。","静坐云生衲，空山月照真。","後徒游禮者，猶認指迷津。"]', '诗', 'shi', '', NULL, '弔雙泉大師真塔 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1794b283-41e7-4702-88e1-5c860a22a789', '暮冬送璘上人歸華容', '暮冬送璘上人归华容', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["故園雖不遠，那免愴行思。","莽蒼平湖路，霏微過雪時。","全無山阻隔，或有客相隨。","得見交親後，春風動柳絲。"]', '["故园雖不远，那免愴行思。","莽蒼平湖路，霏微過雪时。","全無山阻隔，或有客相隨。","得见交親後，春风动柳絲。"]', '诗', 'shi', '', NULL, '暮冬送璘上人歸華容 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('152831ca-dab0-4b8a-b7ed-8d20355baf49', '秋夜聽業上人彈琴', '秋夜听業上人彈琴', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["萬物都寂寂，堪聞彈正聲。","人心盡如此，天下自和平。","湘水瀉秋碧，古風吹太清。","往年廬岳奏，今夕更分明。"]', '["万物都寂寂，堪闻彈正声。","人心尽如此，天下自和平。","湘水瀉秋碧，古风吹太清。","往年廬岳奏，今夕更分明。"]', '诗', 'shi', '', NULL, '秋夜聽業上人彈琴 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2fb49f22-8daa-4b6e-8cd8-23d72739097d', '謝人惠丹藥', '謝人惠丹藥', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["別後聞餐餌，相逢訝道情。","肌膚紅色透，髭髮黑光生。","仙洞誰傳與，松房自鍊成。","常蒙遠分惠，亦覺骨毛輕。"]', '["別後闻餐餌，相逢訝道情。","肌膚紅色透，髭髮黑光生。","仙洞誰傳與，松房自鍊成。","常蒙远分惠，亦覺骨毛轻。"]', '诗', 'shi', '', NULL, '謝人惠丹藥 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('392d77ac-1557-47b7-805a-dc99da4709c4', '荆門病中寄懷貫微上人', '荆门病中寄懷貫微上人', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["我衰君亦老，相憶更何言。","除泥安禪力，難醫必死根。","梅寒爭雪彩，日冷讓冰痕。","早晚東歸去，同尋入石門。"]', '["我衰君亦老，相憶更何言。","除泥安禪力，难醫必死根。","梅寒爭雪彩，日冷讓冰痕。","早晚东归去，同尋入石门。"]', '诗', 'shi', '', NULL, '荆門病中寄懷貫微上人 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('74c0a9a1-1ba2-4818-94da-b5ec78b987d2', '荅孔秀才', '荅孔秀才', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["早向文章裏，能降少壯心。","不愁人不愛，閑處自閑吟。","水國雲雷闊，僧園竹樹深。","無嫌我衰颯，時此一相尋。"]', '["早向文章裏，能降少壯心。","不愁人不愛，闲处自闲吟。","水国云雷闊，僧园竹樹深。","無嫌我衰颯，时此一相尋。"]', '诗', 'shi', '', NULL, '荅孔秀才 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa544607-7279-4af0-9c66-d2e6fea02338', '秋江', '秋江', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["兩岸山青映，中流一櫂聲。","遠無風浪動，正向夕陽橫。","島嶼蟬分宿，沙洲客獨行。","浩然心自合，何必濯吾纓。"]', '["兩岸山青映，中流一櫂声。","远無风浪动，正向夕陽橫。","島嶼蟬分宿，沙洲客独行。","浩然心自合，何必濯吾纓。"]', '诗', 'shi', '', NULL, '秋江 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cce648a4-bcec-4232-a9bf-75e9634228ed', '船窗', '船窗', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["孤舸凭幽窗，清波逼面涼。","舉頭還有礙，低眼即無妨。","瞥過沙禽翠，斜分夕照光。","何時到山寺，上閣看江鄉。"]', '["孤舸凭幽窗，清波逼面涼。","舉头還有礙，低眼即無妨。","瞥過沙禽翠，斜分夕照光。","何时到山寺，上閣看江乡。"]', '诗', 'shi', '', NULL, '船窗 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('22ebe39f-2753-4b30-a85e-e56ca9811756', '永夜', '永夜', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["永日還欹枕，良宵亦曲肱。","神閑無萬慮，壁冷有殘燈。","香影浮龕象，瓶聲著井冰。","尋思到何處，海上斷崖僧。"]', '["永日還欹枕，良宵亦曲肱。","神闲無万慮，壁冷有殘灯。","香影浮龕象，瓶声著井冰。","尋思到何处，海上斷崖僧。"]', '诗', 'shi', '', NULL, '永夜 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b7b91fd7-4e72-4b2b-ab60-6be500d1d4eb', '中春愴懷寄二三知己', '中春愴懷寄二三知己', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["眼暗心還白，逢春強凭欄。","因聞積雨夜，却憶舊山寒。","竹撼煙叢滑，花燒露朵乾。","故人相會處，應話此衰殘。"]', '["眼暗心還白，逢春強凭欄。","因闻積雨夜，却憶旧山寒。","竹撼煙叢滑，花燒露朵乾。","故人相會处，應話此衰殘。"]', '诗', 'shi', '', NULL, '中春愴懷寄二三知己 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e92c4c40-9641-43d1-b9cc-11fc47b7b6ad', '自遣', '自遣', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["了然知是夢，既覺更何求。","死入孤峯去，灰飛一燼休。","雲無空碧在，天靜月華流。","免有諸徒弟，時來弔石頭。"]', '["了然知是梦，既覺更何求。","死入孤峯去，灰飞一燼休。","云無空碧在，天静月华流。","免有諸徒弟，时来弔石头。"]', '诗', 'shi', '', NULL, '自遣 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bff83ec9-9cc9-44a9-bba2-8259bb620777', '送陳霸歸閩', '送陳霸归閩', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["涼風動行興，含笑話臨途。","已得身名了，全忘客道孤。","鄉程過百越，帆影遶重湖。","家在飛鴻外，音書可寄無。"]', '["涼风动行兴，含笑話臨途。","已得身名了，全忘客道孤。","乡程過百越，帆影遶重湖。","家在飞鴻外，音书可寄無。"]', '诗', 'shi', '', NULL, '送陳霸歸閩 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4fd69186-f20c-4167-a41b-664f52ccf641', '寄孫闢呈鄭谷郎中', '寄孫闢呈鄭谷郎中', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["衡岳去都忘，清吟戀省郎。","淹留才半月，詶唱頗盈箱。","雪長松檉格，茶添語話香。","因論樂安子，年少老篇章。"]', '["衡岳去都忘，清吟戀省郎。","淹留才半月，詶唱頗盈箱。","雪长松檉格，茶添語話香。","因論乐安子，年少老篇章。"]', '诗', 'shi', '', NULL, '寄孫闢呈鄭谷郎中 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('96f14a05-6a78-4201-b3d9-87338e18f5fc', '荆門送人自峨嵋游南岳', '荆门送人自峨嵋游南岳', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["峨嵋來已遠，衡岳去猶賒。","南浦懸帆影，西風亂荻花。","天涯遙夢澤，山衆近長沙。","有興多新作，攜將大府誇。"]', '["峨嵋来已远，衡岳去猶賒。","南浦懸帆影，西风亂荻花。","天涯遙梦澤，山衆近长沙。","有兴多新作，携將大府誇。"]', '诗', 'shi', '', NULL, '荆門送人自峨嵋游南岳 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('82ff5bbe-c3a1-4023-81df-a370a1af1d02', '謝主人石筍', '謝主人石筍', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["西園罷宴遊，東閣念林丘。","特減花邊峭，來添竹裏幽。","憶過陽朔見，曾記大湖求。","從此頻吟遶，歸山意亦休。"]', '["西园罷宴游，东閣念林丘。","特減花邊峭，来添竹裏幽。","憶過陽朔见，曾記大湖求。","從此頻吟遶，归山意亦休。"]', '诗', 'shi', '', NULL, '謝主人石筍 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('669c9314-fa46-408b-96f8-2317c6f9c236', '經安公寺', '經安公寺', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["大聖威靈地，安公宴坐蹤。","未知長寂默，不見久從容。","塔影高羣木，江聲壓暮鐘。","此遊幽勝後，來夢亦應重。"]', '["大聖威靈地，安公宴坐蹤。","未知长寂默，不见久從容。","塔影高羣木，江声壓暮鐘。","此游幽勝後，来梦亦應重。"]', '诗', 'shi', '', NULL, '經安公寺 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('67cd8fb5-67b3-41b4-b574-3f75822417e2', '秋夕寄諸姪', '秋夕寄諸姪', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["每到秋殘夜，燈前憶故鄉。","園林紅橘柚，窗戶碧瀟湘。","離別身垂老，艱難路去長。","弟兄應健在，兵火裏耕桑。"]', '["每到秋殘夜，灯前憶故乡。","园林紅橘柚，窗戶碧瀟湘。","離別身垂老，艱难路去长。","弟兄應健在，兵火裏耕桑。"]', '诗', 'shi', '', NULL, '秋夕寄諸姪 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bbdaba64-df70-46b8-8d8b-182386c9bb5e', '謝炭', '謝炭', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["正擁寒灰次，何當惠寂寥。","且留連夜向，未敢滿爐燒。","必恐吞難盡，唯愁撥易消。","豪家揑爲獸，紅迸錦茵焦。"]', '["正擁寒灰次，何當惠寂寥。","且留連夜向，未敢满爐燒。","必恐吞难尽，唯愁撥易消。","豪家揑爲獸，紅迸錦茵焦。"]', '诗', 'shi', '', NULL, '謝炭 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('648c2705-316b-470c-b16b-6ddb45d96b05', '夏滿日偶作寄孫支使', '夏满日偶作寄孫支使', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["一百二十日，煎熬幾不勝。","憶歸滄海寺，冷倚翠崖稜。","舊扇猶操執，新秋更鬱蒸。","何當見涼月，擁衲訪詩朋。"]', '["一百二十日，煎熬幾不勝。","憶归滄海寺，冷倚翠崖稜。","旧扇猶操執，新秋更鬱蒸。","何當见涼月，擁衲訪诗朋。"]', '诗', 'shi', '', NULL, '夏滿日偶作寄孫支使 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('23c54279-e6c7-4ada-a770-a98fc35fcef9', '寄清溪道友', '寄清溪道友', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["山門搖落空，霜霰滿杉松。","明月行禪處，青苔遶石重。","泉聲喧萬壑，鐘韻遍千峯。","終去焚香老，同師大士蹤。"]', '["山门搖落空，霜霰满杉松。","明月行禪处，青苔遶石重。","泉声喧万壑，鐘韻遍千峯。","終去焚香老，同師大士蹤。"]', '诗', 'shi', '', NULL, '寄清溪道友 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba2501bc-0f53-4b64-abae-ab3a569981f9', '謝重緣舊山水障子', '謝重緣旧山水障子', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["敢望重緣飾，微茫洞壑春。","坐看終未是，歸臥始應真。","已覺心中朽，猶憐四面新。","不因公子鑒，零落幾成塵。"]', '["敢望重緣飾，微茫洞壑春。","坐看終未是，归臥始應真。","已覺心中朽，猶怜四面新。","不因公子鑒，零落幾成塵。"]', '诗', 'shi', '', NULL, '謝重緣舊山水障子 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6701e0f4-a46d-4db4-91d0-e76d7d653eaf', '寺居', '寺居', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["鄰井雙梧上，一蟬鳴隔牆。","依稀舊林日，撩亂遶山堂。","難嘿吟風口，終清飲露腸。","老僧加護物，應任噪殘陽。"]', '["鄰井雙梧上，一蟬鳴隔牆。","依稀旧林日，撩亂遶山堂。","难嘿吟风口，終清饮露腸。","老僧加護物，應任噪殘陽。"]', '诗', 'shi', '', NULL, '寺居 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d324f8f0-34f3-4a6f-994c-f53f79ccec07', '剃髮', '剃髮', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["金刀閃冷光，一剃一清涼。","未免隨朝夕，依前長雪霜。","夏林欹石膩，春澗水泉香。","向老凋疎盡，寒天不出房。"]', '["金刀閃冷光，一剃一清涼。","未免隨朝夕，依前长雪霜。","夏林欹石膩，春澗水泉香。","向老凋疎尽，寒天不出房。"]', '诗', 'shi', '', NULL, '剃髮 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e723e3e-07c8-425e-b28f-2d12a7276728', '謝高輦先輩寄新唱和集', '謝高輦先輩寄新唱和集', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["敢謂神仙手，多懷老比丘。","編聯來鹿野，酬唱在龍樓。","洛浦精靈懾，邙山鬼魅愁。","二南風雅道，從此化東周。"]', '["敢謂神仙手，多懷老比丘。","編聯来鹿野，酬唱在龙楼。","洛浦精靈懾，邙山鬼魅愁。","二南风雅道，從此化东周。"]', '诗', 'shi', '', NULL, '謝高輦先輩寄新唱和集 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8abd48a4-f65e-4fbe-a8fa-28e44ed11f51', '送徐秀才遊吳國', '送徐秀才游吳国', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["西江東注急，孤櫂若流星。","風浪相隨白，雲中獨過青。","他時誰共說，此路我曾經。","好向吳朝看，衣冠盡漢庭。"]', '["西江东注急，孤櫂若流星。","风浪相隨白，云中独過青。","他时誰共说，此路我曾經。","好向吳朝看，衣冠尽漢庭。"]', '诗', 'shi', '', NULL, '送徐秀才遊吳國 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('45361806-b765-4352-b4dc-1ed6c8270756', '憶在匡廬日', '憶在匡廬日', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["憶在匡廬日，秋風八月時。","松聲虎溪寺，塔影雁門師。","步碧葳蕤徑，吟香菡萏池。","何當舊泉石，歸去洗心脾。"]', '["憶在匡廬日，秋风八月时。","松声虎溪寺，塔影雁门師。","步碧葳蕤徑，吟香菡萏池。","何當旧泉石，归去洗心脾。"]', '诗', 'shi', '', NULL, '憶在匡廬日 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c30560bc-7750-4783-9978-e8e89f1c27e2', '寄三覺山從益上人', '寄三覺山從益上人', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["山下人來說，多時不下山。","是應終未是，閑得且須閑。","海面雲歸竇，猿邊月上關。","尋思亂峯頂，空送衲僧還。"]', '["山下人来说，多时不下山。","是應終未是，闲得且須闲。","海面云归竇，猿邊月上关。","尋思亂峯頂，空送衲僧還。"]', '诗', 'shi', '', NULL, '寄三覺山從益上人 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('01d5570f-d796-4845-a25d-d730a11edd8c', '殘秋感愴', '殘秋感愴', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["日日加衰病，心心趣寂寥。","殘陽起閑望，萬木聳寒條。","楚寺新爲客，吳江舊看潮。","此懷何以寄，風雨暮蕭蕭。"]', '["日日加衰病，心心趣寂寥。","殘陽起闲望，万木聳寒條。","楚寺新爲客，吳江旧看潮。","此懷何以寄，风雨暮蕭蕭。"]', '诗', 'shi', '', NULL, '殘秋感愴 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1581cbba-e5bf-442a-99c0-6b32b460d156', '寄南徐劉員外二首 一', '寄南徐劉員外二首 一', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["竟陵兵革際，歸復舊園林。","早歲爲官苦，常聞說此心。","海邊山夜上，城外寺秋尋。","應訝嵩峯約，蹉跎直到今。"]', '["竟陵兵革際，归复旧园林。","早歲爲官苦，常闻说此心。","海邊山夜上，城外寺秋尋。","應訝嵩峯約，蹉跎直到今。"]', '诗', 'shi', '', NULL, '寄南徐劉員外二首 一 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f502be35-ca22-462c-964c-886f013e83a6', '寄南徐劉員外二首 二', '寄南徐劉員外二首 二', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["晝公評衆製，姚監選諸文。","風雅誰收我，編聯獨有君。","餘生終此道，萬事盡浮雲。","爭得重攜手，探幽楚水濆。"]', '["晝公評衆製，姚監選諸文。","风雅誰收我，編聯独有君。","餘生終此道，万事尽浮云。","爭得重携手，探幽楚水濆。"]', '诗', 'shi', '', NULL, '寄南徐劉員外二首 二 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03ef0aad-9a57-4c64-8df5-fdf43435f902', '貽王秀才', '貽王秀才', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["功到難搜處，知難始是詩。","自能探虎子，何慮屈男兒。","此道真清氣，前賢早白髭。","須教至公手，不惜付丹枝。"]', '["功到难搜处，知难始是诗。","自能探虎子，何慮屈男兒。","此道真清氣，前賢早白髭。","須教至公手，不惜付丹枝。"]', '诗', 'shi', '', NULL, '貽王秀才 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('599a982e-ea9a-48fb-8746-f377418bb0bd', '贈孫生', '贈孫生', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["見君詩自別，君是繼詩人。","道出千途外，功爭一字新。","寂寥中影跡，霜雪裏精神。","待折東堂桂，歸來更苦辛。"]', '["见君诗自別，君是繼诗人。","道出千途外，功爭一字新。","寂寥中影跡，霜雪裏精神。","待折东堂桂，归来更苦辛。"]', '诗', 'shi', '', NULL, '贈孫生 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b05d5f8-7ee4-4a3b-a078-dbad34de57c9', '酬元員外', '酬元員外', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["清洛碧嵩根，寒流白照門。","園林經難別，桃李幾株存。","衰老江南日，淒涼海上村。","閑來曬朱紱，淚滴舊朝恩。"]', '["清洛碧嵩根，寒流白照门。","园林經难別，桃李幾株存。","衰老江南日，淒涼海上村。","闲来曬朱紱，泪滴旧朝恩。"]', '诗', 'shi', '', NULL, '酬元員外 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7273a215-4def-4ca0-8c64-8ccc88f8c9d9', '與楊秀才話別', '與楊秀才話別', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["庾信哀何極，仲宣悲苦多。","因思學文賦，不勝弄干戈。","自古有如此，於今終若何。","到頭重策蹇，歸去舊煙蘿。"]', '["庾信哀何極，仲宣悲苦多。","因思学文賦，不勝弄干戈。","自古有如此，於今終若何。","到头重策蹇，归去旧煙蘿。"]', '诗', 'shi', '', NULL, '與楊秀才話別 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dd9dbb48-520e-4ca8-9862-61096cac69ab', '寄何崇丘員外', '寄何崇丘員外', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["門底桃源水，涵空復映山。","高吟煙雨霽，殘日郡樓間。","變俗真無事，分題是不閑。","尋思章岸見，全未有年顏。"]', '["门底桃源水，涵空复映山。","高吟煙雨霽，殘日郡楼间。","变俗真無事，分題是不闲。","尋思章岸见，全未有年顏。"]', '诗', 'shi', '', NULL, '寄何崇丘員外 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e0a29abb-56b7-4f93-b3d5-4c9f3ca1099f', '贈劉五經', '贈劉五經', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["往年長白山，發憤忍飢寒。","埽葉雪霜濕，讀書脣齒乾。","羣經通講解，八十尚輕安。","今日江南寺，相逢話世難。"]', '["往年长白山，發憤忍飢寒。","埽葉雪霜濕，读书脣齒乾。","羣經通講解，八十尚轻安。","今日江南寺，相逢話世难。"]', '诗', 'shi', '', NULL, '贈劉五經 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce8b068d-a17f-426f-9378-d2e18c286121', '送游山道者', '送游山道者', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["我亦遊山者，常經舊所經。","雪消天外碧，春曉海中青。","可見亂離世，況臨衰病形。","憐君此行興，獨入白雲屏。"]', '["我亦游山者，常經旧所經。","雪消天外碧，春晓海中青。","可见亂離世，況臨衰病形。","怜君此行兴，独入白云屏。"]', '诗', 'shi', '', NULL, '送游山道者 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd55629a-3965-48d8-a6be-0cc313488900', '舟中江上望玉梁山懷李尊師', '舟中江上望玉梁山懷李尊師', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["殘照玉梁巔，峨峨遠櫂前。","古來傳勝異，人去學神仙。","白鹿老碧壑，黃猨啼紫煙。","誰心共無事，局上度流年。"]', '["殘照玉梁巔，峨峨远櫂前。","古来傳勝異，人去学神仙。","白鹿老碧壑，黄猨啼紫煙。","誰心共無事，局上度流年。"]', '诗', 'shi', '', NULL, '舟中江上望玉梁山懷李尊師 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('36f66970-f369-4a07-bbe4-aabe9be62d75', '角', '角', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["聞說征人說，嗚嗚何處邊。","孤城沙塞地，殘月雪霜天。","會轉胡風急，吹長磧雁連。","應傷漢車騎，名未勒燕然。"]', '["闻说征人说，嗚嗚何处邊。","孤城沙塞地，殘月雪霜天。","會轉胡风急，吹长磧雁連。","應傷漢车騎，名未勒燕然。"]', '诗', 'shi', '', NULL, '角 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('82e63e98-5564-4742-8810-f902ad1555ff', '言詩', '言诗', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["畢竟將何狀，根元在正思。","達人皆一貫，迷者自多岐。","觸類風騷遠，懷賢肺腑衰。","河橋送別者，二子好相知。"]', '["畢竟將何狀，根元在正思。","達人皆一貫，迷者自多岐。","觸類风騷远，懷賢肺腑衰。","河橋送別者，二子好相知。"]', '诗', 'shi', '', NULL, '言詩 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('055c6836-9f71-479c-a5c3-a6135bc0b616', '詶王秀才', '詶王秀才', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["離亂幾時休，儒生厄遠遊。","亡家非漢代，何處覓荆州？","旅夢寒燈屋，鄉懷晝雨樓。","相逢話相殺，誰復念風流。"]', '["離亂幾时休，儒生厄远游。","亡家非漢代，何处覓荆州？","旅梦寒灯屋，乡懷晝雨楼。","相逢話相殺，誰复念风流。"]', '诗', 'shi', '', NULL, '詶王秀才 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8812736e-d0b8-4afb-abff-bc004ae316b5', '春居寄友生', '春居寄友生', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["莎徑荒蕪甚，君應共此情。","江村雷雨發，竹屋夢魂驚。","社過多來燕，花繁漸老鶯。","相思意何切，新作未曾評。"]', '["莎徑荒蕪甚，君應共此情。","江村雷雨發，竹屋梦魂驚。","社過多来燕，花繁漸老鶯。","相思意何切，新作未曾評。"]', '诗', 'shi', '', NULL, '春居寄友生 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7ddb088-42f3-4eb4-ab5a-598a104bafd0', '寄荅武陵幕中何支使二首 一', '寄荅武陵幕中何支使二首 一', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["十萬雄軍幕，三千上客才。","何當談笑外，遠慰寂寥來。","騷雅鏘金擲，風流醉玉頹。","爭知江雪寺，老病向寒灰。"]', '["十万雄軍幕，三千上客才。","何當談笑外，远慰寂寥来。","騷雅鏘金擲，风流醉玉頹。","爭知江雪寺，老病向寒灰。"]', '诗', 'shi', '', NULL, '寄荅武陵幕中何支使二首 一 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fec96228-ff9b-4e87-81d9-28f379ca5ae4', '寄荅武陵幕中何支使二首 二', '寄荅武陵幕中何支使二首 二', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["南州無百戰，北地有長征。","閑殺何從事，傷哉蘇子卿。","江樓聯雪句，野寺看春耕。","門外滄浪水，風波雜雨聲。"]', '["南州無百戰，北地有长征。","闲殺何從事，傷哉蘇子卿。","江楼聯雪句，野寺看春耕。","门外滄浪水，风波杂雨声。"]', '诗', 'shi', '', NULL, '寄荅武陵幕中何支使二首 二 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d51da6c9-30dc-4a0d-82e1-9a6aac04d656', '浙江晚渡', '浙江晚渡', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["去年曾到此，久立滯前程。","岐路時難處，風濤晚未平。","汀蟬含老韻，岸荻簇枯聲。","莫泥關河險，多遊自遠行。"]', '["去年曾到此，久立滯前程。","岐路时难处，风濤晚未平。","汀蟬含老韻，岸荻簇枯声。","莫泥关河險，多游自远行。"]', '诗', 'shi', '', NULL, '浙江晚渡 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f1a6e436-4bcc-44f5-9319-98896320e8f4', '送人下第東歸再謁舊主人', '送人下第东归再謁旧主人', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["一戰偶不捷，東歸計未空。","還攜故書劒，去謁舊英雄。","楚雪連吳樹，西江正北風。","男兒藝若是，會合值明公。"]', '["一戰偶不捷，东归計未空。","還携故书劒，去謁旧英雄。","楚雪連吳樹，西江正北风。","男兒藝若是，會合值明公。"]', '诗', 'shi', '', NULL, '送人下第東歸再謁舊主人 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c0b7acb-8cbb-403d-8771-2514a59e6a8e', '寄謝高先輩見寄二首 一', '寄謝高先輩见寄二首 一', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["穿鑿堪傷骨，風騷久痛心。","永言無絕唱，忽此惠希音。","楊柳江湖晚，芙蓉島嶼深。","何因會仙手，臨水一披襟。"]', '["穿鑿堪傷骨，风騷久痛心。","永言無絕唱，忽此惠希音。","楊柳江湖晚，芙蓉島嶼深。","何因會仙手，臨水一披襟。"]', '诗', 'shi', '', NULL, '寄謝高先輩見寄二首 一 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f2dffbed-74b9-43b3-95d1-2ac08382a0bf', '寄謝高先輩見寄二首 二', '寄謝高先輩见寄二首 二', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["詩在混茫前，難搜到極玄。","有時還積思，度歲未終篇。","片月雙松際，高樓闊水邊。","前賢多此得，風味若爲傳。"]', '["诗在混茫前，难搜到極玄。","有时還積思，度歲未終篇。","片月雙松際，高楼闊水邊。","前賢多此得，风味若爲傳。"]', '诗', 'shi', '', NULL, '寄謝高先輩見寄二首 二 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0899174e-5bcd-4da2-b165-61f707eaaa2d', '寄仰山光味長者', '寄仰山光味长者', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["大仰禪棲處，杉松到頂陰。","下來雖有路，歸去每無心。","鳥道峯形直，龍湫石影深。","徑行誰得見，半夜老猨吟。"]', '["大仰禪棲处，杉松到頂陰。","下来雖有路，归去每無心。","鸟道峯形直，龙湫石影深。","徑行誰得见，半夜老猨吟。"]', '诗', 'shi', '', NULL, '寄仰山光味長者 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee460ced-cba8-476e-aaa1-59cd7c7cc6cf', '貽廬岳陳沆秀才', '貽廬岳陳沆秀才', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["爲儒老雙鬢，勤苦竟何如。","四海方磨劒，空山自讀書。","石圍泉眼碧，秋落洞門虛。","莫慮搜賢僻，徵君舊此居。"]', '["爲儒老雙鬢，勤苦竟何如。","四海方磨劒，空山自读书。","石圍泉眼碧，秋落洞门虛。","莫慮搜賢僻，徵君旧此居。"]', '诗', 'shi', '', NULL, '貽廬岳陳沆秀才 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('926183c4-574b-44ff-9670-7c1c25309e5a', '邊上', '邊上', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["漢地從休馬，胡家自牧羊。","都來銷帝道，渾不用兵防。","草上孤城白，沙翻大漠黃。","秋風起邊雁，一一向瀟湘。"]', '["漢地從休马，胡家自牧羊。","都来銷帝道，渾不用兵防。","草上孤城白，沙翻大漠黄。","秋风起邊雁，一一向瀟湘。"]', '诗', 'shi', '', NULL, '邊上 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e0079db9-14ed-40cf-8baf-8f51a34942b2', '蟋蟀', '蟋蟀', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["聲異蟪蛄聲，聽須是正聽。","無風來竹院，有月在莎庭。","雖不妨調瑟，多堪伴誦經。","誰人向秋夕，爲爾欲忘形。"]', '["声異蟪蛄声，听須是正听。","無风来竹院，有月在莎庭。","雖不妨調瑟，多堪伴誦經。","誰人向秋夕，爲爾欲忘形。"]', '诗', 'shi', '', NULL, '蟋蟀 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('281ac260-3a09-4e4f-8b31-3b33d1e2c824', '寄西山鄭谷神', '寄西山鄭谷神', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["西望鄭先生，焚修在杳冥。","幾番松骨朽，未換鬢根青。","石闕涼調瑟，秋壇夜拜星。","俗人應撫掌，閑處誦黃庭。"]', '["西望鄭先生，焚修在杳冥。","幾番松骨朽，未換鬢根青。","石闕涼調瑟，秋壇夜拜星。","俗人應撫掌，闲处誦黄庭。"]', '诗', 'shi', '', NULL, '寄西山鄭谷神 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8b8a440-0ea9-48e7-a815-55f9e3d7c601', '讀參同契', '读參同契', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["堪笑修仙侶，燒金覓大還。","不知消息火，只在寂寥關。","鬢白爐中術，魂飛海上山。","悲哉五千字，無用在人間。"]', '["堪笑修仙侶，燒金覓大還。","不知消息火，只在寂寥关。","鬢白爐中術，魂飞海上山。","悲哉五千字，無用在人间。"]', '诗', 'shi', '', NULL, '讀參同契 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e371c3f-ccb6-46df-8612-3db2b1c33649', '聞落葉', '闻落葉', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["楚樹雪晴後，蕭蕭落晚風。","因思故國夜，臨水幾株空。","煮茗燒乾脆，行苔踏爛紅。","來年未離此，還見碧叢叢。"]', '["楚樹雪晴後，蕭蕭落晚风。","因思故国夜，臨水幾株空。","煮茗燒乾脆，行苔踏爛紅。","来年未離此，還见碧叢叢。"]', '诗', 'shi', '', NULL, '聞落葉 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c90bf8d3-9cf6-4526-a406-8f76cc3afb11', '謝王先輩昆弟遊湘中迴各見示新詩', '謝王先輩昆弟游湘中迴各见示新诗', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["瀟湘多勝異，宗社久裴回。","兄弟同遊去，幽奇盡采來。","只應求妙唱，何以示寒灰。","上國攜歸後，唯呈不世才。"]', '["瀟湘多勝異，宗社久裴回。","兄弟同游去，幽奇尽采来。","只應求妙唱，何以示寒灰。","上国携归後，唯呈不世才。"]', '诗', 'shi', '', NULL, '謝王先輩昆弟遊湘中迴各見示新詩 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de260931-f7aa-4f9d-adb8-78cfef3061a5', '寄酬高輦推官', '寄酬高輦推官', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["道自閑機長，詩從靜境生。","不知春豔盡，但覺雅風清。","竹膩題幽碧，蕉乾裂脆聲。","何當九霄客，重疊記無名。"]', '["道自闲機长，诗從静境生。","不知春豔尽，但覺雅风清。","竹膩題幽碧，蕉乾裂脆声。","何當九霄客，重叠記無名。"]', '诗', 'shi', '', NULL, '寄酬高輦推官 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f2866b5a-4e07-44e2-87b7-bf9b78cbbd03', '逢詩僧', '逢诗僧', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["禪玄無可並，詩妙有何評。","五七字中苦，百千年後清。","難求方至理，不朽始爲名。","珍重重相見，忘機話此情。"]', '["禪玄無可並，诗妙有何評。","五七字中苦，百千年後清。","难求方至理，不朽始爲名。","珍重重相见，忘機話此情。"]', '诗', 'shi', '', NULL, '逢詩僧 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('161240b4-f608-4f6f-8815-a25ccfc5d8d3', '話道', '話道', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["大道多大笑，寂寥何以論。","霜楓翻落葉，水鳥啄閑門。","服藥還傷性，求珠亦損魂。","無端鑿混沌，一死不還源。"]', '["大道多大笑，寂寥何以論。","霜楓翻落葉，水鸟啄闲门。","服藥還傷性，求珠亦損魂。","無端鑿混沌，一死不還源。"]', '诗', 'shi', '', NULL, '話道 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('270578b5-9787-4551-acd8-48459a209b6e', '謝歐陽侍郎寄示新集', '謝歐陽侍郎寄示新集', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["宮錦三十段，金梭新織來。","殷勤謝君子，迢遞寄寒灰。","鸑鷟對鼓舞，神仙雙裴回。","誰當巧裁製，披去升瑤臺。"]', '["宮錦三十段，金梭新织来。","殷勤謝君子，迢遞寄寒灰。","鸑鷟对鼓舞，神仙雙裴回。","誰當巧裁製，披去升瑤台。"]', '诗', 'shi', '', NULL, '謝歐陽侍郎寄示新集 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b23c08ea-3ba7-41b7-95a5-bd2e4af5a6da', '西墅新居', '西墅新居', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["漸漸見苔青，疎疎遍地生。","閑穿藤屐起，亂踏石階行。","野鳥啼幽樹，名僧笑此情。","殘陽竹陰裏，老圃打門聲。"]', '["漸漸见苔青，疎疎遍地生。","闲穿藤屐起，亂踏石階行。","野鸟啼幽樹，名僧笑此情。","殘陽竹陰裏，老圃打门声。"]', '诗', 'shi', '', NULL, '西墅新居 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c0c7c036-8922-4dc0-8fdb-2aa6126dd21f', '酬孫魴', '酬孫魴', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["幽人還愛雲，才子已從軍。","可信鴛鴻侶，更思麋鹿羣。","新題雖有寄，舊論竟難聞。","知己今如此，編聯悉欲焚。"]', '["幽人還愛云，才子已從軍。","可信鴛鴻侶，更思麋鹿羣。","新題雖有寄，旧論竟难闻。","知己今如此，編聯悉欲焚。"]', '诗', 'shi', '', NULL, '酬孫魴 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d265deac-e6b3-4a30-b737-ab7baf51545a', '掃地', '掃地', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["日日掃復灑，不容纖物侵。","敢望來客口，道似主人心。","蟻過光中少，苔依潤處深。","門前亦如此，一徑入疎林。"]', '["日日掃复灑，不容纖物侵。","敢望来客口，道似主人心。","蟻過光中少，苔依潤处深。","门前亦如此，一徑入疎林。"]', '诗', 'shi', '', NULL, '掃地 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('530d9f84-6b32-4f15-a952-f91aa57a051f', '書匡山隱者壁', '书匡山隐者壁', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["紅霞青壁底，石室薜蘿垂。","應有迷仙者，曾逢採藥時。","桃花饒兩頰，松葉淺長髭。","直是來城市，何人識得伊。"]', '["紅霞青壁底，石室薜蘿垂。","應有迷仙者，曾逢採藥时。","桃花饒兩頰，松葉淺长髭。","直是来城市，何人識得伊。"]', '诗', 'shi', '', NULL, '書匡山隱者壁 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b749368c-dab2-4163-9542-93673456a69d', '送乾康禪師入山過夏', '送乾康禪師入山過夏', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["由來喧滑境，難駐寂寥蹤。","逼夏搖孤錫，離城入亂峯。","雲門應近寺，石路或穿松。","知在棲禪外，題詩寄北宗。"]', '["由来喧滑境，难駐寂寥蹤。","逼夏搖孤錫，離城入亂峯。","云门應近寺，石路或穿松。","知在棲禪外，題诗寄北宗。"]', '诗', 'shi', '', NULL, '送乾康禪師入山過夏 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9326b06d-a918-491e-8b3a-e7080b3a5e10', '野鴨', '野鴨', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["野鴨殊家鴨，離羣忽遠飛。","長生緣甚瘦，近死爲傷肥。","江海游空闊，池塘啄細微。","紅蘭白蘋渚，春暖刷毛衣。"]', '["野鴨殊家鴨，離羣忽远飞。","长生緣甚瘦，近死爲傷肥。","江海游空闊，池塘啄細微。","紅蘭白蘋渚，春暖刷毛衣。"]', '诗', 'shi', '', NULL, '野鴨 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('153b30b7-5328-4623-b529-aaa8b7ab3cfa', '傷秋', '傷秋', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["旦暮餘生在，肌膚十分無。","眠寒半榻朽，立月一株枯。","夢已隨雙樹，詩猶却萬夫。","名山未歸得，可惜死江湖。"]', '["旦暮餘生在，肌膚十分無。","眠寒半榻朽，立月一株枯。","梦已隨雙樹，诗猶却万夫。","名山未归得，可惜死江湖。"]', '诗', 'shi', '', NULL, '傷秋 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e5208479-98cb-42b1-b828-a4d6db85c333', '懷東湖寺', '懷东湖寺', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["鐵柱東湖岸，寺高人亦閑。","往年曾每日，來此看西山。","竹徑青苔合，茶軒白鳥還。","而今在天末，欲去已衰顏。"]', '["鐵柱东湖岸，寺高人亦闲。","往年曾每日，来此看西山。","竹徑青苔合，茶軒白鸟還。","而今在天末，欲去已衰顏。"]', '诗', 'shi', '', NULL, '懷東湖寺 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('724b3749-b445-4990-a5da-8adc515beee5', '寄峴山願公三首 一', '寄峴山願公三首 一', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["形影更誰親，應懷漆道人。","片言酬鑿齒，半偈伏姚秦。","榛莽池經燒，蒿萊寺過春。","心期重西去，一共弔遺塵。"]', '["形影更誰親，應懷漆道人。","片言酬鑿齒，半偈伏姚秦。","榛莽池經燒，蒿萊寺過春。","心期重西去，一共弔遺塵。"]', '诗', 'shi', '', NULL, '寄峴山願公三首 一 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('77ac0ebf-37b4-4625-a2d1-8cbba8bc5dff', '寄峴山願公三首 二', '寄峴山願公三首 二', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["相思恨相遠，至理那時何。","道笑忘言甚，詩嫌背俗多。","青苔閑閣閉，白日斷人過。","獨上西樓望，荆門千萬坡。"]', '["相思恨相远，至理那时何。","道笑忘言甚，诗嫌背俗多。","青苔闲閣閉，白日斷人過。","独上西楼望，荆门千万坡。"]', '诗', 'shi', '', NULL, '寄峴山願公三首 二 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d0e3f32-de7a-4ae3-a0e9-5023dde274d0', '寄峴山願公三首 三', '寄峴山願公三首 三', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["彼此無消息，所思江漢遙。","轉聞多患難，甚說遠相招。","老至何悲歎，生知便寂寥。","終期踏松影，攜手虎溪橋。"]', '["彼此無消息，所思江漢遙。","轉闻多患难，甚说远相招。","老至何悲歎，生知便寂寥。","終期踏松影，携手虎溪橋。"]', '诗', 'shi', '', NULL, '寄峴山願公三首 三 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('82a41183-1339-4859-809f-27f71b1dac50', '清夜作', '清夜作', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["不惜白日短，乍容清夜長。","坐聞風露滴，吟覺骨毛涼。","興寢無諸病，空閑有一牀。","天明振衣起，苔砌落花香。"]', '["不惜白日短，乍容清夜长。","坐闻风露滴，吟覺骨毛涼。","兴寢無諸病，空闲有一牀。","天明振衣起，苔砌落花香。"]', '诗', 'shi', '', NULL, '清夜作 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bbb45e7c-cac2-49ae-b076-613ea662d1e1', '贈白處士', '贈白处士', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["莘野居何定，浮生知是誰。","衣衫同[野]叟，指趣似禪師。","白髮應無也，丹砂久服之。","仍聞創行計，春暖向峨嵋。"]', '["莘野居何定，浮生知是誰。","衣衫同[野]叟，指趣似禪師。","白髮應無也，丹砂久服之。","仍闻創行計，春暖向峨嵋。"]', '诗', 'shi', '', NULL, '贈白處士 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1716432f-5f0f-44f6-a78a-f1de0cfede4a', '崔秀才宿話', '崔秀才宿話', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["事轉聞多事，心休話苦心。","相留明月寺，共憶白雲岑。","蘚壁殘蟲韻，霜軒倒竹陰。","開門又言別，誰竟慰塵襟。"]', '["事轉闻多事，心休話苦心。","相留明月寺，共憶白云岑。","蘚壁殘蟲韻，霜軒倒竹陰。","开门又言別，誰竟慰塵襟。"]', '诗', 'shi', '', NULL, '崔秀才宿話 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('98268253-d4c4-486a-84fa-901435b22d92', '懷天台華頂僧', '懷天台华頂僧', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["華頂危臨海，丹霞裏石橋。","曾從國清寺，上看月明潮。","好鳥親香火，狂泉噴泬寥。","欲歸師智者，頭白路迢迢。"]', '["华頂危臨海，丹霞裏石橋。","曾從国清寺，上看月明潮。","好鸟親香火，狂泉噴泬寥。","欲归師智者，头白路迢迢。"]', '诗', 'shi', '', NULL, '懷天台華頂僧 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d6b176d-c181-4c0d-aa6f-78bf7c4ac843', '送人赴官', '送人赴官', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["年少作初官，還如行路難。","兵荒經邑里，風俗久凋殘。","照硯花光淡，漂書柳絮乾。","聊應充侍膳，薄俸繼朝餐。"]', '["年少作初官，還如行路难。","兵荒經邑里，风俗久凋殘。","照硯花光淡，漂书柳絮乾。","聊應充侍膳，薄俸繼朝餐。"]', '诗', 'shi', '', NULL, '送人赴官 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('70a7ea31-5ea5-4161-92b0-ab92e4856371', '水鶴', '水鹤', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["鴛鴦與鸂鶒，相狎豈慙君。","比雪還勝雪，同羣亦出羣。","靜巢孤島月，寒夢九臯雲。","歸路分明[過]，飛鳴即可聞。"]', '["鴛鴦與鸂鶒，相狎豈慙君。","比雪還勝雪，同羣亦出羣。","静巢孤島月，寒梦九臯云。","归路分明[過]，飞鳴即可闻。"]', '诗', 'shi', '', NULL, '水鶴 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d1b1d440-8312-40c3-9a01-4d2bcf619b62', '湘中感懷', '湘中感懷', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["漁翁那會我，傲兀葦邊行。","亂世難逸跡，乘流擬濯纓。","江花紅細碎，沙鳥白分明。","向夕題詩處，春風斑竹聲。"]', '["漁翁那會我，傲兀葦邊行。","亂世难逸跡，乘流擬濯纓。","江花紅細碎，沙鸟白分明。","向夕題诗处，春风斑竹声。"]', '诗', 'shi', '', NULL, '湘中感懷 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d02f226-cb75-46f4-be46-77408672fb22', '九日逢虛中虛受', '九日逢虛中虛受', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["楚后萍臺下，相逢九日時。","干戈人事地，荒廢菊花籬。","我已多衰病，君猶盡黑髭。","皇天安罪得，解語便吟詩。"]', '["楚后萍台下，相逢九日时。","干戈人事地，荒廢菊花籬。","我已多衰病，君猶尽黑髭。","皇天安罪得，解語便吟诗。"]', '诗', 'shi', '', NULL, '九日逢虛中虛受 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('02cf9a3d-544c-4d1e-b135-e2e9fa42046d', '贈李明府', '贈李明府', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["名家宰名邑，將謂屈鋒鋩。","直是難蘇俗，能消不下堂。","冰痕生硯水，柳影透琴牀。","何必稱瀟灑，獨爲詩酒狂。"]', '["名家宰名邑，將謂屈鋒鋩。","直是难蘇俗，能消不下堂。","冰痕生硯水，柳影透琴牀。","何必稱瀟灑，独爲诗酒狂。"]', '诗', 'shi', '', NULL, '贈李明府 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a2fae7d-feaa-4012-a1a7-02be3ce443b7', '暮春久雨作', '暮春久雨作', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["積雨向春陰，冥冥獨院深。","已無花落地，空有竹藏禽。","簷溜聲何暴，隣僧影亦沈。","誰知力耕者，桑麥最關心。"]', '["積雨向春陰，冥冥独院深。","已無花落地，空有竹藏禽。","簷溜声何暴，隣僧影亦沈。","誰知力耕者，桑麦最关心。"]', '诗', 'shi', '', NULL, '暮春久雨作 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cbd575ef-45c1-48a8-8a50-0b1c7f3b3fad', '渚宮莫問詩一十五首 一', '渚宮莫问诗一十五首 一', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["莫問疎人事，王侯已任伊。","不妨隨野性，還似在山時。","靜入無聲樂，狂拋正律詩。","自爲仍自愛，清淨裏尋思。"]', '["莫问疎人事，王侯已任伊。","不妨隨野性，還似在山时。","静入無声乐，狂拋正律诗。","自爲仍自愛，清淨裏尋思。"]', '诗', 'shi', '', NULL, '渚宮莫問詩一十五首 一 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('79369fb4-5b90-487b-9201-560489445857', '渚宮莫問詩一十五首 二', '渚宮莫问诗一十五首 二', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["莫問伊嵇嬾，流年已付他。","話通時事少，詩着野題多。","夢外春桃李，心中舊薜蘿。","浮生此不悟，剃髮竟如何。"]', '["莫问伊嵇嬾，流年已付他。","話通时事少，诗着野題多。","梦外春桃李，心中旧薜蘿。","浮生此不悟，剃髮竟如何。"]', '诗', 'shi', '', NULL, '渚宮莫問詩一十五首 二 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f07f4d36-2258-491d-a742-5a10e39b60fa', '渚宮莫問詩一十五首 三', '渚宮莫问诗一十五首 三', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["莫問休行脚，南方已徧尋。","了應須自了，心不是他心。","赤水珠何覓，寒山偈莫吟。","誰同論此理，杜口少知音。"]', '["莫问休行脚，南方已徧尋。","了應須自了，心不是他心。","赤水珠何覓，寒山偈莫吟。","誰同論此理，杜口少知音。"]', '诗', 'shi', '', NULL, '渚宮莫問詩一十五首 三 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('351a7ea7-a637-4ab1-9fde-5a0357637284', '渚宮莫問詩一十五首 四', '渚宮莫问诗一十五首 四', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["莫問孱愚格，天應只與閑。","合居長樹下，那稱衆人間。","跡絕爲真隱，機忘是大還。","終當學支遁，買取箇青山。"]', '["莫问孱愚格，天應只與闲。","合居长樹下，那稱衆人间。","跡絕爲真隐，機忘是大還。","終當学支遁，買取箇青山。"]', '诗', 'shi', '', NULL, '渚宮莫問詩一十五首 四 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('884486ca-3578-4989-a855-15db06a7d1af', '渚宮莫問詩一十五首 五', '渚宮莫问诗一十五首 五', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["莫問無求意，浮雲喻可知。","滿盈如不戒，倚伏更何疑。","樂矣賢顏子，窮乎聖仲尼。","已過知命歲，休把運行推。"]', '["莫问無求意，浮云喻可知。","满盈如不戒，倚伏更何疑。","乐矣賢顏子，窮乎聖仲尼。","已過知命歲，休把運行推。"]', '诗', 'shi', '', NULL, '渚宮莫問詩一十五首 五 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad8ebf52-1763-4a4a-80f7-387ba6e880c6', '渚宮莫問詩一十五首 六', '渚宮莫问诗一十五首 六', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["莫問閑行趣，春風野水涯。","千門無謝女，兩岸有楊花。","好鶴曾爲客，真龍或作蛇。","躊躕自迴首，日脚背樓斜。"]', '["莫问闲行趣，春风野水涯。","千门無謝女，兩岸有楊花。","好鹤曾爲客，真龙或作蛇。","躊躕自迴首，日脚背楼斜。"]', '诗', 'shi', '', NULL, '渚宮莫問詩一十五首 六 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('defe26ac-1f0e-4f1f-9d19-dd159551c565', '渚宮莫問詩一十五首 七', '渚宮莫问诗一十五首 七', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["莫問真消息，中心只自知。","清風含笑詠，明月混希夷。","壞衲涼天擁，玄文靜夜披。","善哉溫伯子，言望至公知。"]', '["莫问真消息，中心只自知。","清风含笑詠，明月混希夷。","壞衲涼天擁，玄文静夜披。","善哉溫伯子，言望至公知。"]', '诗', 'shi', '', NULL, '渚宮莫問詩一十五首 七 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('364eedb9-6400-48c8-9fb2-d790c0c5dd5e', '渚宮莫問詩一十五首 八', '渚宮莫问诗一十五首 八', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["莫問休持鉢，從貧乞已疎。","侯門叨月俸，齋食剩年儲。","簪履三千外，形骸六十餘。","舊峯呵練若，松徑接匡廬。"]', '["莫问休持鉢，從貧乞已疎。","侯门叨月俸，斋食剩年儲。","簪履三千外，形骸六十餘。","旧峯呵練若，松徑接匡廬。"]', '诗', 'shi', '', NULL, '渚宮莫問詩一十五首 八 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d216a40c-8f66-42a2-acae-365af2704cbd', '渚宮莫問詩一十五首 九', '渚宮莫问诗一十五首 九', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["莫問依劉跡，金臺又度秋。","威儀非上客，譚笑愧諸侯。","禮許無拘檢，詩推異輩流。","東林未歸得，搖落楚江頭。"]', '["莫问依劉跡，金台又度秋。","威儀非上客，譚笑愧諸侯。","禮許無拘檢，诗推異輩流。","东林未归得，搖落楚江头。"]', '诗', 'shi', '', NULL, '渚宮莫問詩一十五首 九 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a5f3bc27-1526-4a1e-9cf4-5639794f0f11', '渚宮莫問詩一十五首 十', '渚宮莫问诗一十五首 十', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["莫問無機性，甘名百鈍人。","一牀鋪冷落，長日臥精神。","分已疎知舊，詩還得意新。","多才碧雲客，時或此相親。"]', '["莫问無機性，甘名百鈍人。","一牀鋪冷落，长日臥精神。","分已疎知旧，诗還得意新。","多才碧云客，时或此相親。"]', '诗', 'shi', '', NULL, '渚宮莫問詩一十五首 十 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dbb7b498-06c0-479b-9377-917d8aacb206', '渚宮莫問詩一十五首 十一', '渚宮莫问诗一十五首 十一', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["莫問關門意，從來寡往還。","道應歸淡泊，身合在空閑。","四面苔圍綠，孤窗雨灑斑。","夢尋何處去，秋色水邊山。"]', '["莫问关门意，從来寡往還。","道應归淡泊，身合在空闲。","四面苔圍綠，孤窗雨灑斑。","梦尋何处去，秋色水邊山。"]', '诗', 'shi', '', NULL, '渚宮莫問詩一十五首 十一 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bcc31b61-df29-4361-98cc-5471b70a4df8', '渚宮莫問詩一十五首 十二', '渚宮莫问诗一十五首 十二', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["莫問□□□，□□逐性情。","人間高此道，禪外剩他名。","夏□松邊坐，秋光水畔行。","更無時忌諱，容易得題成。"]', '["莫问□□□，□□逐性情。","人间高此道，禪外剩他名。","夏□松邊坐，秋光水畔行。","更無时忌諱，容易得題成。"]', '诗', 'shi', '', NULL, '渚宮莫問詩一十五首 十二 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('513215d9-080a-4f3a-bf74-d58c7638f252', '渚宮莫問詩一十五首 十三', '渚宮莫问诗一十五首 十三', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["莫問多山興，晴樓獨凭時。","六年滄海寺，一別白蓮池。","句早逢名匠，禪曾見祖師。","冥搜與真性，清外認揚眉。"]', '["莫问多山兴，晴楼独凭时。","六年滄海寺，一別白蓮池。","句早逢名匠，禪曾见祖師。","冥搜與真性，清外認揚眉。"]', '诗', 'shi', '', NULL, '渚宮莫問詩一十五首 十三 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97044e4a-594d-4075-85f3-d40daaa8dd97', '渚宮莫問詩一十五首 十四', '渚宮莫问诗一十五首 十四', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["莫問衰殘質，流光速可悲。","寸心修未了，長命欲何爲。","坐臥身多倦，經行骨漸疲。","分明說此苦，珍重竺乾師。"]', '["莫问衰殘質，流光速可悲。","寸心修未了，长命欲何爲。","坐臥身多倦，經行骨漸疲。","分明说此苦，珍重竺乾師。"]', '诗', 'shi', '', NULL, '渚宮莫問詩一十五首 十四 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('478fe904-bb32-4cba-b050-aa6bbf9f5169', '渚宮莫問詩一十五首 十五', '渚宮莫问诗一十五首 十五', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["莫問野騰騰，勞形已不能。","慇懃無上士，珍重有名僧。","坐覺心心默，行思步步冰。","終歸石房裏，一點夜深燈。"]', '["莫问野腾腾，勞形已不能。","慇懃無上士，珍重有名僧。","坐覺心心默，行思步步冰。","終归石房裏，一点夜深灯。"]', '诗', 'shi', '', NULL, '渚宮莫問詩一十五首 十五 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('34810d96-2252-4ef6-908b-f70f3bd61fd0', '荆州新秋病起雜題一十五首 病起見王化', '荆州新秋病起杂題一十五首 病起见王化', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["病起見王化，融融古帝鄉。","曉煙凝氣紫，晚色作雲黃。","四野歌豐稔，千門唱樂康。","老身仍未死，猶詠好風光。"]', '["病起见王化，融融古帝乡。","晓煙凝氣紫，晚色作云黄。","四野歌豐稔，千门唱乐康。","老身仍未死，猶詠好风光。"]', '诗', 'shi', '', NULL, '荆州新秋病起雜題一十五首 病起見王化 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('12b31106-ef69-45b3-a015-a3035723bba5', '荆州新秋病起雜題一十五首 病起見圖畫', '荆州新秋病起杂題一十五首 病起见圖畫', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["病起見圖畫，雲門興似饒。","衲衣椶笠重，嵩岳華山遙。","命在齋猶赴，刀閒髮盡凋。","秋光漸輕健，欲去倚江橋。"]', '["病起见圖畫，云门兴似饒。","衲衣椶笠重，嵩岳华山遙。","命在斋猶赴，刀閒髮尽凋。","秋光漸轻健，欲去倚江橋。"]', '诗', 'shi', '', NULL, '荆州新秋病起雜題一十五首 病起見圖畫 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eaf5c02b-4774-4671-aa6c-1f074d236802', '荆州新秋病起雜題一十五首 病起見苔錢', '荆州新秋病起杂題一十五首 病起见苔錢', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["病起見苔錢，規模遍地圓。","兒童掃不破，子母自相連。","潤屋何曾有，緣牆謾可憐。","虛教作銅臭，空使外人傳。"]', '["病起见苔錢，規模遍地圓。","兒童掃不破，子母自相連。","潤屋何曾有，緣牆謾可怜。","虛教作銅臭，空使外人傳。"]', '诗', 'shi', '', NULL, '荆州新秋病起雜題一十五首 病起見苔錢 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d2593a48-ace3-4479-801e-764674a85a49', '荆州新秋病起雜題一十五首 病起見庭竹', '荆州新秋病起杂題一十五首 病起见庭竹', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["病起見庭竹，君應悲我情。","何妨甚消瘦，却稱苦修行。","每謝侵牀影，時迴傍枕聲。","秋來漸平復，吟遶骨毛輕。"]', '["病起见庭竹，君應悲我情。","何妨甚消瘦，却稱苦修行。","每謝侵牀影，时迴傍枕声。","秋来漸平复，吟遶骨毛轻。"]', '诗', 'shi', '', NULL, '荆州新秋病起雜題一十五首 病起見庭竹 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f7035b2-3976-4cfc-ad82-007a27a2d2c1', '荆州新秋病起雜題一十五首 病起見生涯', '荆州新秋病起杂題一十五首 病起见生涯', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["病起見生涯，資緣覺甚奢。","方袍嫌垢弊，律服變光華。","頗愧同諸俗，何嘗異出家。","三衣如兩翼，珍重汝寒鴉。"]', '["病起见生涯，資緣覺甚奢。","方袍嫌垢弊，律服变光华。","頗愧同諸俗，何嘗異出家。","三衣如兩翼，珍重汝寒鴉。"]', '诗', 'shi', '', NULL, '荆州新秋病起雜題一十五首 病起見生涯 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee69bded-a1e8-4cbf-8e90-1d6b386359af', '荆州新秋病起雜題一十五首 病起見秋扇', '荆州新秋病起杂題一十五首 病起见秋扇', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["病起見秋扇，風前悟感傷。","念予當咽絕，得爾致清涼。","沙鷺如搖影，汀蓮似綻香。","不同婕妤詠，託意怨君王。"]', '["病起见秋扇，风前悟感傷。","念予當咽絕，得爾致清涼。","沙鷺如搖影，汀蓮似綻香。","不同婕妤詠，託意怨君王。"]', '诗', 'shi', '', NULL, '荆州新秋病起雜題一十五首 病起見秋扇 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b6856c7-6a47-4ac6-a015-e5384f4094df', '荆州新秋病起雜題一十五首 病起見衰葉', '荆州新秋病起杂題一十五首 病起见衰葉', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["病起見衰葉，飄然似我身。","偶乘風有韻，初落地無塵。","縱得紅霑露，爭如綠帶春。","因傷此懷抱，聊寄一篇新。"]', '["病起见衰葉，飄然似我身。","偶乘风有韻，初落地無塵。","縱得紅霑露，爭如綠带春。","因傷此懷抱，聊寄一篇新。"]', '诗', 'shi', '', NULL, '荆州新秋病起雜題一十五首 病起見衰葉 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('02afe8f4-f6c5-4bf1-a20a-68a07e65c022', '荆州新秋病起雜題一十五首 病起見庭栢', '荆州新秋病起杂題一十五首 病起见庭栢', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["病起見庭栢，青青我不任。","力扶乾瘦骨，勉對歲寒心。","韻謝疎篁合，根容片石侵。","衰殘想長壽，時倚就閑吟。"]', '["病起见庭栢，青青我不任。","力扶乾瘦骨，勉对歲寒心。","韻謝疎篁合，根容片石侵。","衰殘想长壽，时倚就闲吟。"]', '诗', 'shi', '', NULL, '荆州新秋病起雜題一十五首 病起見庭栢 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea3e6403-e22f-47aa-93ef-8b9929c134d5', '荆州新秋病起雜題一十五首 病起見庭蓮', '荆州新秋病起杂題一十五首 病起见庭蓮', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["病起見庭蓮，風荷已颯然。","開時聞馥郁，枕上正纏綿。","本在滄江闊，移來碧沼圓。","却思香社裏，葉葉漏聲連。"]', '["病起见庭蓮，风荷已颯然。","开时闻馥郁，枕上正纏綿。","本在滄江闊，移来碧沼圓。","却思香社裏，葉葉漏声連。"]', '诗', 'shi', '', NULL, '荆州新秋病起雜題一十五首 病起見庭蓮 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d282653-f873-49a3-91e9-46f2f73abdb9', '荆州新秋病起雜題一十五首 病起見庭菊', '荆州新秋病起杂題一十五首 病起见庭菊', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["病起見庭菊，幾勞栽種工。","可能經臥疾，相倚自成叢。","翠萼低含露，金英盡亞風。","那知予愛爾，不在酒杯中。"]', '["病起见庭菊，幾勞栽種工。","可能經臥疾，相倚自成叢。","翠萼低含露，金英尽亞风。","那知予愛爾，不在酒杯中。"]', '诗', 'shi', '', NULL, '荆州新秋病起雜題一十五首 病起見庭菊 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6bbb6efa-94f3-40db-b461-6791ccad2279', '荆州新秋病起雜題一十五首 病起見庭石', '荆州新秋病起杂題一十五首 病起见庭石', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["病起見庭石，豈知經夏眠。","不能資藥價，空自作苔錢。","翠憶藍光底，青思瀑影邊。","巖僧應笑我，細碎種階前。"]', '["病起见庭石，豈知經夏眠。","不能資藥價，空自作苔錢。","翠憶藍光底，青思瀑影邊。","巖僧應笑我，細碎種階前。"]', '诗', 'shi', '', NULL, '荆州新秋病起雜題一十五首 病起見庭石 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('470fa0fa-3a55-4bc0-814d-7067ceae0fb8', '荆州新秋病起雜題一十五首 病起見庭莎', '荆州新秋病起杂題一十五首 病起见庭莎', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["病起見庭莎，綠階傍竹多。","遶行猶未得，靜聽復如何。","蟋蟀幽中響，蟪蛄深處歌。","不緣田地窄，剩種任婆娑。"]', '["病起见庭莎，綠階傍竹多。","遶行猶未得，静听复如何。","蟋蟀幽中响，蟪蛄深处歌。","不緣田地窄，剩種任婆娑。"]', '诗', 'shi', '', NULL, '荆州新秋病起雜題一十五首 病起見庭莎 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('36add9ff-b52f-4191-a038-be2c16ccdc6e', '荆州新秋病起雜題一十五首 病起見苔色', '荆州新秋病起杂題一十五首 病起见苔色', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["病起見苔色，凝然陣未枯。","淺深圍柱礎，詰曲遶廊廡。","碧翠文相間，青黃勢自鋪。","爲錢虛玷染，畢竟不如無。"]', '["病起见苔色，凝然陣未枯。","淺深圍柱礎，詰曲遶廊廡。","碧翠文相间，青黄勢自鋪。","爲錢虛玷染，畢竟不如無。"]', '诗', 'shi', '', NULL, '荆州新秋病起雜題一十五首 病起見苔色 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('46d85d40-5315-44c8-b0f6-33afd118bf9c', '荆州新秋病起雜題一十五首 病起見秋月', '荆州新秋病起杂題一十五首 病起见秋月', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["病起見秋月，正當三五時。","清光應鑒我，幽思更同誰。","惜坐身猶倦，牽吟氣尚羸。","明年七十六，約此健相期。"]', '["病起见秋月，正當三五时。","清光應鑒我，幽思更同誰。","惜坐身猶倦，牽吟氣尚羸。","明年七十六，約此健相期。"]', '诗', 'shi', '', NULL, '荆州新秋病起雜題一十五首 病起見秋月 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e140d77-9824-4361-a7e1-8b332e939143', '荆州新秋病起雜題一十五首 病起見閑雲', '荆州新秋病起杂題一十五首 病起见闲云', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["病起見閑雲，空中聚又分。","滯留堪笑我，舒卷不如君。","觸石終無跡，從風或有聞。","仙山足鸞鳳，歸去自同羣。"]', '["病起见闲云，空中聚又分。","滯留堪笑我，舒卷不如君。","觸石終無跡，從风或有闻。","仙山足鸾鳳，归去自同羣。"]', '诗', 'shi', '', NULL, '荆州新秋病起雜題一十五首 病起見閑雲 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('882f7430-bfcf-4e7f-a585-f8b11f5537aa', '夜坐聞雪寄所知', '夜坐闻雪寄所知', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["初宵飛霰急，竹樹灑乾輕。","不是知音者，難教愛此聲。","漸凌孤燭白，偏激苦心清。","堪笑同文友，忘眠坐到明。"]', '["初宵飞霰急，竹樹灑乾轻。","不是知音者，难教愛此声。","漸凌孤燭白，偏激苦心清。","堪笑同文友，忘眠坐到明。"]', '诗', 'shi', '', NULL, '夜坐聞雪寄所知 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5fda31cb-fd30-477b-a4a5-8237bab9f5a2', '懷洞庭', '懷洞庭', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["憶過巴陵歲，無人問去留。","中宵滿湖月，獨自在僧樓。","漁父真閑唱，靈均是謾愁。","今來欲長往，誰借木蘭舟。"]', '["憶過巴陵歲，無人问去留。","中宵满湖月，独自在僧楼。","漁父真闲唱，靈均是謾愁。","今来欲长往，誰借木蘭舟。"]', '诗', 'shi', '', NULL, '懷洞庭 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('98fdb4ac-1359-4ede-b573-5d9bba2080df', '欲遊龍山鹿苑有作', '欲游龙山鹿苑有作', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["龍山門不遠，鹿苑路非遙。","合逐閑身去，何須待客招。","年華殘兩鬢，筋骨倦長宵。","聞說峯前寺，新修白石橋。"]', '["龙山门不远，鹿苑路非遙。","合逐闲身去，何須待客招。","年华殘兩鬢，筋骨倦长宵。","闻说峯前寺，新修白石橋。"]', '诗', 'shi', '', NULL, '欲遊龍山鹿苑有作 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('51a93ef5-81f4-4a27-be27-8be261022261', '再逢晝公', '再逢晝公', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["竟陵西別後，徧地起刀兵。","彼此無緣着，雲山有處行。","久吟難敵句，終忍不求名。","年鬢俱如雪，相看眼且明。"]', '["竟陵西別後，徧地起刀兵。","彼此無緣着，云山有处行。","久吟难敵句，終忍不求名。","年鬢俱如雪，相看眼且明。"]', '诗', 'shi', '', NULL, '再逢晝公 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('32badc31-3d02-46de-896b-9087d105da9c', '送人遊武陵湘中', '送人游武陵湘中', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["爲子歌行樂，西南入武陵。","風煙無戰士，賓榻有吟僧。","山遶軍城疊，江臨寺閣層。","遍尋幽勝了，湘水泛清澄。"]', '["爲子歌行乐，西南入武陵。","风煙無戰士，賓榻有吟僧。","山遶軍城叠，江臨寺閣層。","遍尋幽勝了，湘水泛清澄。"]', '诗', 'shi', '', NULL, '送人遊武陵湘中 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3de1c6fc-2432-46f4-b110-81770248bc50', '酬九經者', '酬九經者', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["九經三史學，窮妙又窮微。","長白山初出，青雲路欲飛。","江僧酬雪句，沙鶴識麻衣。","家在黃河北，南來偶未歸。"]', '["九經三史学，窮妙又窮微。","长白山初出，青云路欲飞。","江僧酬雪句，沙鹤識麻衣。","家在黄河北，南来偶未归。"]', '诗', 'shi', '', NULL, '酬九經者 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5945190a-363d-4c3a-a443-891ba8501cee', '寄贈集灘二公', '寄贈集灘二公', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["聞有難名境，因君住更名。","軒窗中夜色，風月遶灘聲。","客好過無厭，禽幽畫不成。","終期一尋去，聊且寄吟情。"]', '["闻有难名境，因君住更名。","軒窗中夜色，风月遶灘声。","客好過無厭，禽幽畫不成。","終期一尋去，聊且寄吟情。"]', '诗', 'shi', '', NULL, '寄贈集灘二公 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('23e8fe38-6052-44ee-9407-c8541e0aa31a', '夏日作', '夏日作', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["燕雀語相和，風池滿芰荷。","可驚成事晚，殊喜得閑多。","竹衆涼欺水，苔繁綠勝莎。","無慙孤聖代，賦詠有詩歌。"]', '["燕雀語相和，风池满芰荷。","可驚成事晚，殊喜得闲多。","竹衆涼欺水，苔繁綠勝莎。","無慙孤聖代，賦詠有诗歌。"]', '诗', 'shi', '', NULL, '夏日作 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('00ec915a-7260-43dd-ad4b-5b42631ade45', '行路難', '行路难', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["下浸與高盤，不爲行路難。","是非真險惡，翻覆作峯巒。","漆媿同時黑，朱慙巧處丹。","令人畏相識，欲畫白雲看。"]', '["下浸與高盤，不爲行路难。","是非真險惡，翻覆作峯巒。","漆媿同时黑，朱慙巧处丹。","令人畏相識，欲畫白云看。"]', '诗', 'shi', '', NULL, '行路難 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('307af128-8709-41c2-b7a0-57130271570f', '送玉泉道者迴山寺', '送玉泉道者迴山寺', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["却憶西峯頂，經行絕愛憎。","別來心念念，歸去雪層層。","石塢尋春笋，苔龕續夜燈。","應悲塵土裏，追逐利名僧。"]', '["却憶西峯頂，經行絕愛憎。","別来心念念，归去雪層層。","石塢尋春笋，苔龕續夜灯。","應悲塵土裏，追逐利名僧。"]', '诗', 'shi', '', NULL, '送玉泉道者迴山寺 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c6e5441-5e97-43c9-b214-8aa62f3a669e', '謝王拾遺見訪兼寄篇什', '謝王拾遺见訪兼寄篇什', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["竹裏安禪處，生涯一印灰。","經年乞食過，昨日諫臣來。","愧把黃梅偈，曾酬白雪才。","因令識鳥跡，重疊在蒼苔。"]', '["竹裏安禪处，生涯一印灰。","經年乞食過，昨日諫臣来。","愧把黄梅偈，曾酬白雪才。","因令識鸟跡，重叠在蒼苔。"]', '诗', 'shi', '', NULL, '謝王拾遺見訪兼寄篇什 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('00a313cd-bf1b-44cd-8173-a61058525404', '題張氏池亭', '題張氏池亭', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["樹石叢叢別，詩家趣向幽。","有時閑客散，始覺細泉流。","蝶到琴棋畔，花過島嶼頭。","月明紅藕上，應見白龜遊。"]', '["樹石叢叢別，诗家趣向幽。","有时闲客散，始覺細泉流。","蝶到琴棋畔，花過島嶼头。","月明紅藕上，應见白龟游。"]', '诗', 'shi', '', NULL, '題張氏池亭 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f96f1c17-fa9a-4cac-b203-97ebb0e465b4', '送人南遊', '送人南游', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["且聽吟贈遠，君此去蒙州。","瘴國頻聞說，邊鴻亦不遊。","[蠻]花藏孔雀，野石亂犀牛。","到彼誰相慰，知音有郡侯。"]', '["且听吟贈远，君此去蒙州。","瘴国頻闻说，邊鴻亦不游。","[蠻]花藏孔雀，野石亂犀牛。","到彼誰相慰，知音有郡侯。"]', '诗', 'shi', '', NULL, '送人南遊 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b708007-3148-42a6-a9ff-4a991d487183', '題明公房', '題明公房', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["寺北聞湘浪，窗南見嶽雲。","自然高日用，何要出人羣。","瓦滴殘松雨，香爐匝印文。","近年精易道，疑者曉紛紛。"]', '["寺北闻湘浪，窗南见嶽云。","自然高日用，何要出人羣。","瓦滴殘松雨，香爐匝印文。","近年精易道，疑者晓紛紛。"]', '诗', 'shi', '', NULL, '題明公房 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f2a024be-2085-4af0-afd4-41bd0310314a', '寄顧處士', '寄顧处士', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["半年離別夢，來往即湖邊。","兩幅關山雪，尋常在眼前。","項容藏古翠，張藻卷寒煙。","藍淀圖花鳥，時人不惜錢。"]', '["半年離別梦，来往即湖邊。","兩幅关山雪，尋常在眼前。","項容藏古翠，張藻卷寒煙。","藍淀圖花鸟，时人不惜錢。"]', '诗', 'shi', '', NULL, '寄顧處士 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3188be4-268f-4b36-aec4-8a11ba78b584', '貽徐生', '貽徐生', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["可能東海子，清苦在貧居。","掃地無閑客，堆窗有古書。","少年猶若此，向老合何如。","去歲頻相訪，今來見亦疎。"]', '["可能东海子，清苦在貧居。","掃地無闲客，堆窗有古书。","少年猶若此，向老合何如。","去歲頻相訪，今来见亦疎。"]', '诗', 'shi', '', NULL, '貽徐生 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b37b3b4c-4f84-4fb2-934c-bf94c5d35929', '謝虛中上人晚秋見寄', '謝虛中上人晚秋见寄', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["楚外同文在，荆門得信時。","幾重相別意，一首晚秋詩。","日暮山沈雨，蓮殘水滿池。","登樓試南望，爲子動歸思。"]', '["楚外同文在，荆门得信时。","幾重相別意，一首晚秋诗。","日暮山沈雨，蓮殘水满池。","登楼試南望，爲子动归思。"]', '诗', 'shi', '', NULL, '謝虛中上人晚秋見寄 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3323ae6a-232d-45ad-9be9-887fda861cd9', '寄東林言之禪子', '寄东林言之禪子', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["聞思相送後，幽院閉苔錢。","使我吟還廢，聞君病未痊。","聽秋唯困坐，怕客但佯眠。","可惜東窗月，無寥過一年。"]', '["闻思相送後，幽院閉苔錢。","使我吟還廢，闻君病未痊。","听秋唯困坐，怕客但佯眠。","可惜东窗月，無寥過一年。"]', '诗', 'shi', '', NULL, '寄東林言之禪子 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0365bb66-4fc5-418c-874c-8eec2bb1731b', '寒節日寄鄉友', '寒節日寄乡友', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["歲歲逢寒食，寥寥古寺家。","踏青思故里，垂白看楊花。","原野稀疎雨，江天冷澹霞。","滄浪與湘水，歸恨共無涯。"]', '["歲歲逢寒食，寥寥古寺家。","踏青思故里，垂白看楊花。","原野稀疎雨，江天冷澹霞。","滄浪與湘水，归恨共無涯。"]', '诗', 'shi', '', NULL, '寒節日寄鄉友 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c6595eac-e121-4906-b4f8-b66ead3ac6a9', '聞西蟾從弟卜巖居嶽西有寄', '闻西蟾從弟卜巖居嶽西有寄', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["瀑布見高低，巖開巖壁西。","碧雲多舊作，紅葉幾新題。","滴瀝中疎磬，嵌空半倚梯。","仍聞樵子徑，□不到前溪。"]', '["瀑布见高低，巖开巖壁西。","碧云多旧作，紅葉幾新題。","滴瀝中疎磬，嵌空半倚梯。","仍闻樵子徑，□不到前溪。"]', '诗', 'shi', '', NULL, '聞西蟾從弟卜巖居嶽西有寄 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('601f4010-2087-40f0-86c7-6e8329248115', '寄懷西蟾師弟', '寄懷西蟾師弟', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["萬里八九月，一身西北風。","自從相示後，長記在吟中。","見說南遊遠，堪懷我姓同。","江邊忽得信，迴到岳門東。"]', '["万里八九月，一身西北风。","自從相示後，长記在吟中。","见说南游远，堪懷我姓同。","江邊忽得信，迴到岳门东。"]', '诗', 'shi', '', NULL, '寄懷西蟾師弟 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c9351812-15dc-48ff-8fd0-0d248f01dac4', '撲滿子', '撲满子', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["祗愛滿我腹，爭如滿害身。","到頭須撲破，却散與他人。"]', '["祗愛满我腹，爭如满害身。","到头須撲破，却散與他人。"]', '诗', 'shi', '', NULL, '撲滿子 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('22f74441-68c6-4125-b938-90b3fe9bacfa', '寄西川惠光大師曇域', '寄西川惠光大師曇域', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["禪月有名子，相知面未曾。","筆精垂壁溜，詩澀滴杉冰。","蜀國從棲泊，蕪城幾廢興。","憶歸應寄夢，東北過金陵。"]', '["禪月有名子，相知面未曾。","笔精垂壁溜，诗澀滴杉冰。","蜀国從棲泊，蕪城幾廢兴。","憶归應寄梦，东北過金陵。"]', '诗', 'shi', '', NULL, '寄西川惠光大師曇域 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('42c871d7-b40c-476f-8b9d-20cf75258855', '憶別匡山寄彭澤乾晝上人', '憶別匡山寄彭澤乾晝上人', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["憶別匡山日，無端是遠遊。","却迴看五老，飜悔上孤舟。","蹭蹬三千里，蹉跎二十秋。","近來空寄夢，時到虎溪頭。"]', '["憶別匡山日，無端是远游。","却迴看五老，飜悔上孤舟。","蹭蹬三千里，蹉跎二十秋。","近来空寄梦，时到虎溪头。"]', '诗', 'shi', '', NULL, '憶別匡山寄彭澤乾晝上人 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f623a51e-4768-4c26-8d7d-7530d622df3c', '又寄彭澤晝公', '又寄彭澤晝公', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["聞君彭澤住，結搆近陶公。","種菊心相似，嘗茶味不同。","湖光秋枕上，嶽翠夏窗中。","八月東林去，吟香菡萏風。"]', '["闻君彭澤住，結搆近陶公。","種菊心相似，嘗茶味不同。","湖光秋枕上，嶽翠夏窗中。","八月东林去，吟香菡萏风。"]', '诗', 'shi', '', NULL, '又寄彭澤晝公 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc224112-c305-4c52-a17d-383b339e67fb', '因覽支使孫中丞看可準大師詩序有寄', '因覽支使孫中丞看可準大師诗序有寄', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["一千篇裏選，三百首菁英。","玉尺新量出，金刀舊剪成。","錦江增古翠，仙掌減元精。","自此爲風格，留傳諸後生。"]', '["一千篇裏選，三百首菁英。","玉尺新量出，金刀旧剪成。","錦江增古翠，仙掌減元精。","自此爲风格，留傳諸後生。"]', '诗', 'shi', '', NULL, '因覽支使孫中丞看可準大師詩序有寄 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('32f53149-5549-46e8-9017-cd3b61412b40', '新秋病中枕上聞蟬', '新秋病中枕上闻蟬', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["枕上稍醒醒，忽聞蟬一聲。","此時知不死，昨日即前生。","更欲臨窗聽，猶難策杖行。","尋應同蛻殼，重飲露華清。"]', '["枕上稍醒醒，忽闻蟬一声。","此时知不死，昨日即前生。","更欲臨窗听，猶难策杖行。","尋應同蛻殼，重饮露华清。"]', '诗', 'shi', '', NULL, '新秋病中枕上聞蟬 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e353afe-506b-4331-a1be-e5de4ba27607', '寄雲蓋山先禪師', '寄云蓋山先禪師', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["曾尋湘水東，古翠積秋濃。","長老禪棲處，半天雲蓋峯。","閑牀饒得石，雜樹少於松。","近有誰堪語，瀏陽妙指蹤。"]', '["曾尋湘水东，古翠積秋濃。","长老禪棲处，半天云蓋峯。","闲牀饒得石，杂樹少於松。","近有誰堪語，瀏陽妙指蹤。"]', '诗', 'shi', '', NULL, '寄雲蓋山先禪師 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('56b1ff2a-937a-45a0-89e1-7484fce8b835', '落葉', '落葉', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["落多秋亦晚，窗外見諸鄰。","世上誰驚盡，林間獨掃頻。","蕭騷微月夜，重疊早霜晨。","昨日繁陰在，鶯聲樹樹春。"]', '["落多秋亦晚，窗外见諸鄰。","世上誰驚尽，林间独掃頻。","蕭騷微月夜，重叠早霜晨。","昨日繁陰在，鶯声樹樹春。"]', '诗', 'shi', '', NULL, '落葉 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8f10ccd-9ba3-4a51-8be0-c5686d3f51b1', '次耒陽作', '次耒陽作', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["遶岳復沿湘，衡陽又耒陽。","不堪思北客，從此入南荒。","旦夕多猨狖，淹留少雪霜。","因經杜公墓，惆悵學文章。"]', '["遶岳复沿湘，衡陽又耒陽。","不堪思北客，從此入南荒。","旦夕多猨狖，淹留少雪霜。","因經杜公墓，惆悵学文章。"]', '诗', 'shi', '', NULL, '次耒陽作 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b8763bb-cddb-4993-ad1e-47112403a9b6', '舟中晚望祝融峯', '舟中晚望祝融峯', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["天際卓寒青，舟中望晚晴。","十年關夢寐，此日向崢嶸。","巨石凌空黑，飛泉照夜明。","終當躡孤頂，坐看白雲生。"]', '["天際卓寒青，舟中望晚晴。","十年关梦寐，此日向崢嶸。","巨石凌空黑，飞泉照夜明。","終當躡孤頂，坐看白云生。"]', '诗', 'shi', '', NULL, '舟中晚望祝融峯 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('93936db3-3a85-4975-a978-b95c0b9adffc', '弔杜工部墳', '弔杜工部墳', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["鵬翅蹋於斯，明君知不知。","[域]中詩價大，荒外土墳卑。","瘴雨無時滴，蠻風有穴吹。","唯應李太白，魂魄往來疲。"]', '["鵬翅蹋於斯，明君知不知。","[域]中诗價大，荒外土墳卑。","瘴雨無时滴，蠻风有穴吹。","唯應李太白，魂魄往来疲。"]', '诗', 'shi', '', NULL, '弔杜工部墳 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b18f0ea2-40a6-4df2-a1a0-2a7a9c7d44f0', '嶽中寄殷處士', '嶽中寄殷处士', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["出嶽與入嶽，前題繼後題。","遍尋僧壁上，多在雁峯西。","近說遊江寺，將誰話石梯。","相思立高巘，山下草萋萋。"]', '["出嶽與入嶽，前題繼後題。","遍尋僧壁上，多在雁峯西。","近说游江寺，將誰話石梯。","相思立高巘，山下草萋萋。"]', '诗', 'shi', '', NULL, '嶽中寄殷處士 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4450ed44-2cba-4677-84b5-0636cf6759cf', '送幽禪師', '送幽禪師', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["霜繁野葉飛，長老卷行衣。","浮世不知處，白雲相待歸。","磬和天籟響，禪動嶽神威。","莫便言長往，勞生待發機。"]', '["霜繁野葉飞，长老卷行衣。","浮世不知处，白云相待归。","磬和天籟响，禪动嶽神威。","莫便言长往，勞生待發機。"]', '诗', 'shi', '', NULL, '送幽禪師 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ef0396a-9b74-441d-b12d-ef44d8fd2b90', '觀燒', '观燒', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["獵獵寒蕪引，承風勢不還。","放來應有主，焚去到何山。","焰入空濛裏，煙飛蒼莽間。","石中有良玉，惆悵但傷顏。"]', '["獵獵寒蕪引，承风勢不還。","放来應有主，焚去到何山。","焰入空濛裏，煙飞蒼莽间。","石中有良玉，惆悵但傷顏。"]', '诗', 'shi', '', NULL, '觀燒 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2824799b-be82-42e0-98c8-4d11bc4f0398', '詠茶十二韻', '詠茶十二韻', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["百草讓爲靈，功先百草成。","甘傳天下口，貴占火前名。","出處春無雁，收時谷有鶯。","封題從澤國，貢獻入秦京。","齅覺精新極，嘗知骨自輕。","研通天柱響，摘遶蜀山明。","賦客秋吟起，禪師晝臥驚。","角開香滿室，爐動綠凝鐺。","晚憶涼泉對，閑思異果平。","松黃乾旋泛，雲母滑隨傾。","頗貴高人寄，尤宜別匱盛。","曾尋修事法，妙盡陸先生。"]', '["百草讓爲靈，功先百草成。","甘傳天下口，貴占火前名。","出处春無雁，收时谷有鶯。","封題從澤国，貢獻入秦京。","齅覺精新極，嘗知骨自轻。","研通天柱响，摘遶蜀山明。","賦客秋吟起，禪師晝臥驚。","角开香满室，爐动綠凝鐺。","晚憶涼泉对，闲思異果平。","松黄乾旋泛，云母滑隨傾。","頗貴高人寄，尤宜別匱盛。","曾尋修事法，妙尽陸先生。"]', '诗', 'shi', '', NULL, '詠茶十二韻 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('10cd1f03-0b8c-4aa3-a50b-d9803271fe2f', '寄陽岐西峯僧', '寄陽岐西峯僧', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["西峯殘照東，瀑布灑冥鴻。","閑憶高牕外，秋晴萬里空。","藤陰藏石磴，衣毳落杉風。","日有誰來覓，層層鳥道中。"]', '["西峯殘照东，瀑布灑冥鴻。","闲憶高牕外，秋晴万里空。","藤陰藏石磴，衣毳落杉风。","日有誰来覓，層層鸟道中。"]', '诗', 'shi', '', NULL, '寄陽岐西峯僧 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9da2719c-6faa-48e8-83d1-cbcbe6634027', '迴雁峯', '迴雁峯', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["瘴雨過孱顏，危邊有徑盤。","壯堪扶壽嶽，靈合置仙壇。","影北鴻聲亂，青南客道難。"]', '["瘴雨過孱顏，危邊有徑盤。","壯堪扶壽嶽，靈合置仙壇。","影北鴻声亂，青南客道难。"]', '诗', 'shi', '', NULL, '迴雁峯 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('142f8709-117e-4a0e-94d3-afa5b7bb2589', '贈詢公上人', '贈詢公上人', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["威儀何貴重，一室貯水清。","終日松杉徑，自多蟲蟻行。","像前孤立影，鐘外數珠聲。","知悟修來事，今爲第幾生。"]', '["威儀何貴重，一室貯水清。","終日松杉徑，自多蟲蟻行。","像前孤立影，鐘外數珠声。","知悟修来事，今爲第幾生。"]', '诗', 'shi', '', NULL, '贈詢公上人 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('73615dae-d26a-4c08-99a8-a6533e8af2d5', '秋興', '秋兴', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["所見背時情，閑行亦獨行。","晚涼思水石，危閣望崢嶸。","雨外殘雲片，風中亂葉聲。","舊山吟友在，相憶夢應清。"]', '["所见背时情，闲行亦独行。","晚涼思水石，危閣望崢嶸。","雨外殘云片，风中亂葉声。","旧山吟友在，相憶梦應清。"]', '诗', 'shi', '', NULL, '秋興 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('72cfc47c-43e6-4129-b5c4-5cbebfba920c', '古寺老松', '古寺老松', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["百歲禪師說，先師指此松。","小年行道遶，早見偃枝重。","月檻移孤影，秋亭卓一峯。","終當因夜電，拏攫從雲龍。"]', '["百歲禪師说，先師指此松。","小年行道遶，早见偃枝重。","月檻移孤影，秋亭卓一峯。","終當因夜電，拏攫從云龙。"]', '诗', 'shi', '', NULL, '古寺老松 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b7aa491a-afaf-4ba5-ab62-c466fe0dd096', '題無余處士書齋', '題無余处士书斋', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["閑地從莎蘚，誰人愛此心。","琴棋懷客遠，風雪閉門深。","枕外江灘響，窗西樹石陰。","他年衡嶽寺，爲我一相尋。"]', '["闲地從莎蘚，誰人愛此心。","琴棋懷客远，风雪閉门深。","枕外江灘响，窗西樹石陰。","他年衡嶽寺，爲我一相尋。"]', '诗', 'shi', '', NULL, '題無余處士書齋 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9fc45fca-f3d8-448e-95e8-033cb9b3dcd0', '歲暮江寺住', '歲暮江寺住', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["山依枯槁容，何處見年終？","風雪軍城外，蒹葭古寺中。","孤村誰認磬，極浦夜鳴鴻。","坐憶匡廬隱，泉聲滴半空。"]', '["山依枯槁容，何处见年終？","风雪軍城外，蒹葭古寺中。","孤村誰認磬，極浦夜鳴鴻。","坐憶匡廬隐，泉声滴半空。"]', '诗', 'shi', '', NULL, '歲暮江寺住 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f754fb00-1b8c-41cb-b098-9fa1c9fade4a', '新燕', '新燕', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["棲託近佳人，應憐巧語新。","風光華屋暖，弦管牡丹晨。","遠采江泥膩，雙飛麥雨勻。","差池自有便，敢觸杏梁塵。"]', '["棲託近佳人，應怜巧語新。","风光华屋暖，弦管牡丹晨。","远采江泥膩，雙飞麦雨勻。","差池自有便，敢觸杏梁塵。"]', '诗', 'shi', '', NULL, '新燕 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('85d0e845-f7ae-43da-9278-eef010bfa700', '喻吟', '喻吟', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["日用是何專，吟疲即坐禪。","此生還可喜，餘事不相便。","頭白無邪裏，魂清有象先。","江花與芳草，莫染我情田。"]', '["日用是何專，吟疲即坐禪。","此生還可喜，餘事不相便。","头白無邪裏，魂清有象先。","江花與芳草，莫染我情田。"]', '诗', 'shi', '', NULL, '喻吟 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('335e53a1-a2b1-4976-bff8-adda5fd43ea4', '過湘江唐弘書齋', '過湘江唐弘书斋', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["四鄰無俗迹，終日大開門。","水晚來邊雁，林秋下楚猨。","一家隨難在，雙眼向書昏。","沈近騷人廟，吟應見古魂。"]', '["四鄰無俗迹，終日大开门。","水晚来邊雁，林秋下楚猨。","一家隨难在，雙眼向书昏。","沈近騷人廟，吟應见古魂。"]', '诗', 'shi', '', NULL, '過湘江唐弘書齋 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9184b407-bfa9-4307-af79-cb8439ebf014', '讀賈島集', '读賈島集', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["遺篇三百首，首首是遺冤。","知到千年外，更逢何者論。","離秦空得罪，入蜀但聽猨。","還似長沙祖，唯餘賦鵩言。"]', '["遺篇三百首，首首是遺冤。","知到千年外，更逢何者論。","離秦空得罪，入蜀但听猨。","還似长沙祖，唯餘賦鵩言。"]', '诗', 'shi', '', NULL, '讀賈島集 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('148eb136-e973-4785-810c-9f25f9ec2af0', '寄山中諸友', '寄山中諸友', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["自歸城裏寺，長憶宿山門。","終夜冥心客，諸峯呌月猨。","嵐光生眼力，泉滴爽吟魂。","只待遊方遍，還來埽樹根。"]', '["自归城裏寺，长憶宿山门。","終夜冥心客，諸峯呌月猨。","嵐光生眼力，泉滴爽吟魂。","只待游方遍，還来埽樹根。"]', '诗', 'shi', '', NULL, '寄山中諸友 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97d985cd-b7dd-4911-8f29-e126f163cbfd', '懷終南僧', '懷終南僧', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["擾擾一京塵，何門是了因。","萬重千疊嶂，一去不來人。","鳥道春殘雪，蘿龕晝定身。","寥寥石窗外，天籟動衣巾。"]', '["擾擾一京塵，何门是了因。","万重千叠嶂，一去不来人。","鸟道春殘雪，蘿龕晝定身。","寥寥石窗外，天籟动衣巾。"]', '诗', 'shi', '', NULL, '懷終南僧 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8f6c869-6a72-44bb-b5b4-ba39eefd8815', '送二友生歸宜陽', '送二友生归宜陽', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["二生俱我友，清苦輩流稀。","舊國居相近，孤帆秋共歸。","殘陽沙鳥亂，疎雨島楓飛。","幾宿多山處，猨啼燭影微。"]', '["二生俱我友，清苦輩流稀。","旧国居相近，孤帆秋共归。","殘陽沙鸟亂，疎雨島楓飞。","幾宿多山处，猨啼燭影微。"]', '诗', 'shi', '', NULL, '送二友生歸宜陽 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50ef47d6-a89f-4b9d-a332-5d35664df760', '懷從弟', '懷從弟', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["孤窗燭影微，何事阻吟思。","兄弟斷消息，山川長路岐。","日沈栖鶴塢，霜著呌猨枝。","可想爲懷抱，多愁多難時。"]', '["孤窗燭影微，何事阻吟思。","兄弟斷消息，山川长路岐。","日沈栖鹤塢，霜著呌猨枝。","可想爲懷抱，多愁多难时。"]', '诗', 'shi', '', NULL, '懷從弟 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c5c5ec4-7aa7-41e4-a90a-64ea41fbeb6f', '岳陽道中作', '岳陽道中作', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["客思尋常動，未如今斷魂。","路岐經亂後，風雪少人村。","大澤鳴寒雁，千峯啼晝猨。","爭教此時白，不上鬢鬚根。"]', '["客思尋常动，未如今斷魂。","路岐經亂後，风雪少人村。","大澤鳴寒雁，千峯啼晝猨。","爭教此时白，不上鬢鬚根。"]', '诗', 'shi', '', NULL, '岳陽道中作 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dc9c3333-5275-46c5-9ce4-9c557efe9465', '赴鄭谷郎中招遊龍興觀讀題詩[板]謁七真儀像因有十八韻', '赴鄭谷郎中招游龙兴观读題诗[板]謁七真儀像因有十八韻', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["何處陪遊勝，龍興古觀時。","詩懸大雅作，殿禮七真儀。","遠繼周南美，彌旌拱北思。","雄方垂朴略，後輩仰箴規。","對坐茵花暖，偕行蘚陣隳。","僧絛初學結，朝服久慵披。","到處琴碁傍，登樓筆硯隨。","論禪忘視聽，譚老極希夷。","照日江光遠，遮軒檜影欹。","觸鞋松子響，窺立鶴雛癡。","始貴茶巡爽，終憐酒散遲。","放懷還把杖，憇石或搘頤。","眺遠凝清眄，吟高動白髭。","風鵬心不小，蒿雀志徒卑。","顧我專無作，於身忘有爲。","叨因五字解，每忝重言期。","捨此應休也，何人更賞之。","淹留仙境晚，迴騎雪風吹。"]', '["何处陪游勝，龙兴古观时。","诗懸大雅作，殿禮七真儀。","远繼周南美，彌旌拱北思。","雄方垂朴略，後輩仰箴規。","对坐茵花暖，偕行蘚陣隳。","僧絛初学結，朝服久慵披。","到处琴碁傍，登楼笔硯隨。","論禪忘視听，譚老極希夷。","照日江光远，遮軒檜影欹。","觸鞋松子响，窺立鹤雛癡。","始貴茶巡爽，終怜酒散遲。","放懷還把杖，憇石或搘頤。","眺远凝清眄，吟高动白髭。","风鵬心不小，蒿雀志徒卑。","顧我專無作，於身忘有爲。","叨因五字解，每忝重言期。","捨此應休也，何人更賞之。","淹留仙境晚，迴騎雪风吹。"]', '诗', 'shi', '', NULL, '赴鄭谷郎中招遊龍興觀讀題詩[板]謁七真儀像因有十八韻 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('139de24b-1661-41cd-a20f-20d59c670d38', '書李秀才壁', '书李秀才壁', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["干戈阻上日，南國寄貧居。","舊里荒應盡，新年病未除。","窗風連島樹，門逕接隣蔬。","我有閑來約，相看雪滿[株]。"]', '["干戈阻上日，南国寄貧居。","旧里荒應尽，新年病未除。","窗风連島樹，门逕接隣蔬。","我有闲来約，相看雪满[株]。"]', '诗', 'shi', '', NULL, '書李秀才壁 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('277a4ee9-8d7f-41de-9399-6c52833aa58a', '聞尚顏下世', '闻尚顏下世', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["嶽僧傳的信，聞在麓山亡。","郡有爲詩客，誰來一影堂。","夢休尋灞滻，跡已絕瀟湘。","遠憶同吟石，新秋檜栢涼。"]', '["嶽僧傳的信，闻在麓山亡。","郡有爲诗客，誰来一影堂。","梦休尋灞滻，跡已絕瀟湘。","远憶同吟石，新秋檜栢涼。"]', '诗', 'shi', '', NULL, '聞尚顏下世 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d362c18-fcfe-4036-a697-1f73701e453c', '薔薇', '薔薇', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["根本似玫瑰，繁英刾外開。","香高藂有架，紅落地多苔。","去住閑人看，晴明遠蝶來。","牡丹先幾日，銷歇向塵埃。"]', '["根本似玫瑰，繁英刾外开。","香高藂有架，紅落地多苔。","去住闲人看，晴明远蝶来。","牡丹先幾日，銷歇向塵埃。"]', '诗', 'shi', '', NULL, '薔薇 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b5f033de-71c5-4f37-8b6f-24a1384d2c64', '送隆公上人', '送隆公上人', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["獨攜譚柄去，千里指人寰。","未斷生徒望，難教白日閑。","空江橫落照，大府向西山。","好騁陳那孔，誰云劫石頑。"]', '["独携譚柄去，千里指人寰。","未斷生徒望，难教白日闲。","空江橫落照，大府向西山。","好騁陳那孔，誰云劫石頑。"]', '诗', 'shi', '', NULL, '送隆公上人 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('576ddeac-7aa5-4fce-a92c-94b92f7c835c', '宿簡寂觀', '宿簡寂观', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["萬壑雲霞影，千年松檜聲。","如何教下士，容易信長生。","月共虛無白，香和沆𤅈清。","閑尋古廊畫，記得列仙名。"]', '["万壑云霞影，千年松檜声。","如何教下士，容易信长生。","月共虛無白，香和沆𤅈清。","闲尋古廊畫，記得列仙名。"]', '诗', 'shi', '', NULL, '宿簡寂觀 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dc04c087-e9d7-4996-ab1a-2e67ee8c4fbc', '遇元上人', '遇元上人', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["七澤過名山，相逢黃落殘。","杉松開寺晚，泉月話心寒。","祖遍諸方禮，經曾幾處看。","應懷出家院，紫閣近長安。"]', '["七澤過名山，相逢黄落殘。","杉松开寺晚，泉月話心寒。","祖遍諸方禮，經曾幾处看。","應懷出家院，紫閣近长安。"]', '诗', 'shi', '', NULL, '遇元上人 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b9d32a46-de5f-41ba-a261-437611f80d0d', '早梅', '早梅', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["萬木凍欲折，孤根暖獨迴。","前村深雪裏，昨夜一枝開。","風遰幽香去，禽窺素豔來。","明年如應律，先發映春臺。"]', '["万木凍欲折，孤根暖独迴。","前村深雪裏，昨夜一枝开。","风遰幽香去，禽窺素豔来。","明年如應律，先發映春台。"]', '诗', 'shi', '', NULL, '早梅 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad519176-a940-4622-b846-11a18a6c1f7c', '聽泉', '听泉', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["落石幾萬仞，冷聲飄遠空。","高秋初雨後，半夜亂山中。","只有照壁月，更無吹葉風。","幾曾廬岳聽，到曉與僧同。"]', '["落石幾万仞，冷声飄远空。","高秋初雨後，半夜亂山中。","只有照壁月，更無吹葉风。","幾曾廬岳听，到晓與僧同。"]', '诗', 'shi', '', NULL, '聽泉 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9776b3c1-a67f-4d20-bd37-45097beb0378', '送孫逸人歸廬山', '送孫逸人归廬山', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["獨自擔琴鶴，還歸瀑布東。","逍遙非俗趣，楊柳謾春風。","草遶村程綠，花盤石磴紅。","他時許相覓，五老亂雲中。"]', '["独自擔琴鹤，還归瀑布东。","逍遙非俗趣，楊柳謾春风。","草遶村程綠，花盤石磴紅。","他时許相覓，五老亂云中。"]', '诗', 'shi', '', NULL, '送孫逸人歸廬山 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e0ceaa89-9df4-4566-9a26-c049ce1d6eb0', '聽李尊師彈琴', '听李尊師彈琴', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["仙子弄瑤琴，仙山松月深。","此聲含太古，誰聽到無心。","灑石霜千片，歕崖泉萬尋。","何人傳指法，攜向海中岑。"]', '["仙子弄瑤琴，仙山松月深。","此声含太古，誰听到無心。","灑石霜千片，歕崖泉万尋。","何人傳指法，携向海中岑。"]', '诗', 'shi', '', NULL, '聽李尊師彈琴 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4cdce8c2-e3ac-4971-a1b6-0a1ceef8335b', '寄武陵微上人', '寄武陵微上人', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["善卷臺邊寺，松筠遶祖堂。","秋聲度風雨，曉色遍滄浪。","白石同誰坐，清吟過我狂。","近聞爲古律，雅道更重光。"]', '["善卷台邊寺，松筠遶祖堂。","秋声度风雨，晓色遍滄浪。","白石同誰坐，清吟過我狂。","近闻爲古律，雅道更重光。"]', '诗', 'shi', '', NULL, '寄武陵微上人 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b9e5266f-e328-43fc-9b27-e0a25012ce58', '匡山寓居棲公', '匡山寓居棲公', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["外物盡已外，閑遊且自由。","好山逢過夏，無事住經秋。","樹影殘陽寺，茶香古石樓。","何時定休講，歸漱虎溪流。"]', '["外物尽已外，闲游且自由。","好山逢過夏，無事住經秋。","樹影殘陽寺，茶香古石楼。","何时定休講，归漱虎溪流。"]', '诗', 'shi', '', NULL, '匡山寓居棲公 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1140aed1-c7d0-433e-8c2d-b4cf74b30d81', '湘西道林寺陶太尉井', '湘西道林寺陶太尉井', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["太尉遺孤井，寒澄七百年。","未聞陵谷變，終與姓名傳。","影浸無風樹，光含有月天。","林僧曉來此，滿汲灑金田。"]', '["太尉遺孤井，寒澄七百年。","未闻陵谷变，終與姓名傳。","影浸無风樹，光含有月天。","林僧晓来此，满汲灑金田。"]', '诗', 'shi', '', NULL, '湘西道林寺陶太尉井 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('54bb81d9-24c6-4720-bb37-4bb81e8bb40d', '寄松江陸龜蒙處士', '寄松江陸龟蒙处士', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["萬卷功何用，徒稱處士休。","閑欹太湖石，醉聽洞庭秋。","道在誰開口，詩成自點頭。","中間欲相訪，尋便阻戈矛。"]', '["万卷功何用，徒稱处士休。","闲欹太湖石，醉听洞庭秋。","道在誰开口，诗成自点头。","中间欲相訪，尋便阻戈矛。"]', '诗', 'shi', '', NULL, '寄松江陸龜蒙處士 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a12b8e11-1ceb-4656-a7b9-9e07046a0f99', '閉門', '閉门', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["外事休關念，灰心獨閉門。","無人來問我，白日又黃昏。","燈集飛蛾影，窗銷迸雪痕。","中心自明了，一句祖師言。"]', '["外事休关念，灰心独閉门。","無人来问我，白日又黄昏。","灯集飞蛾影，窗銷迸雪痕。","中心自明了，一句祖師言。"]', '诗', 'shi', '', NULL, '閉門 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('adc36a10-c127-4a7c-89aa-249c8c02c171', '看水', '看水', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["范蠡東浮闊，靈均北泛長。","誰知遠煙浪，別有好思量。","故國門前急，天涯照裏忙。","難收上樓興，渺漫正斜陽。"]', '["范蠡东浮闊，靈均北泛长。","誰知远煙浪，別有好思量。","故国门前急，天涯照裏忙。","难收上楼兴，渺漫正斜陽。"]', '诗', 'shi', '', NULL, '看水 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('47b6cc86-2094-426b-9e9b-f21bc50f66f7', '寄棲白上人', '寄棲白上人', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["萬國爭名地，吾師獨此閑。","題詩招上相，看雪下南山。","內殿承恩久，中條進表還。","常因秋貢客，少得掩禪關。"]', '["万国爭名地，吾師独此闲。","題诗招上相，看雪下南山。","內殿承恩久，中條進表還。","常因秋貢客，少得掩禪关。"]', '诗', 'shi', '', NULL, '寄棲白上人 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9882b26c-af56-44b6-b5ab-8630d8b26c4d', '自題', '自題', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["禪外求詩妙，年來鬢已秋。","未嘗將一字，容易謁諸侯。","挂夢山皆遠，題名石盡幽。","敢言梁太子，傍采碧雲流。"]', '["禪外求诗妙，年来鬢已秋。","未嘗將一字，容易謁諸侯。","挂梦山皆远，題名石尽幽。","敢言梁太子，傍采碧云流。"]', '诗', 'shi', '', NULL, '自題 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea8aa096-9bdf-4d8f-bbb4-95eb8acd0586', '孫支使來借詩集因有謝', '孫支使来借诗集因有謝', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["冥搜從少小，隨分得淳元。","聞說吟僧口，多傳過蜀門。","相尋江島上，共看夏雲根。","坐落遲遲日，新題互把論。"]', '["冥搜從少小，隨分得淳元。","闻说吟僧口，多傳過蜀门。","相尋江島上，共看夏云根。","坐落遲遲日，新題互把論。"]', '诗', 'shi', '', NULL, '孫支使來借詩集因有謝 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e7876be-c640-4cb1-89ac-6fa8640a3587', '夏日言懷', '夏日言懷', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["苦被流年迫，衰羸老病情。","得歸青嶂死，便共白雲生。","樹枿燒爐響，崖稜躡屐聲。","此心人信否，魂夢自分明。"]', '["苦被流年迫，衰羸老病情。","得归青嶂死，便共白云生。","樹枿燒爐响，崖稜躡屐声。","此心人信否，魂梦自分明。"]', '诗', 'shi', '', NULL, '夏日言懷 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('029d9706-a709-4a05-b283-e592e593d964', '早秋寄友生', '早秋寄友生', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["雨多殘暑歇，蟬急暮風清。","誰有閑心去，江邊看水行。","河遙紅蓼簇，野闊白煙平。","試折秋蓮葉，題詩寄竺卿。"]', '["雨多殘暑歇，蟬急暮风清。","誰有闲心去，江邊看水行。","河遙紅蓼簇，野闊白煙平。","試折秋蓮葉，題诗寄竺卿。"]', '诗', 'shi', '', NULL, '早秋寄友生 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b6fa3173-7ecd-434f-8ac9-194c44625a04', '送王秀才往松滋夏課', '送王秀才往松滋夏課', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["松滋聞古縣，明府是詩家。","靜理餘無事，[攲]眠盡落花。","江光搖夕照，柳影帶殘霞。","君去應相與，乘船泛月華。"]', '["松滋闻古縣，明府是诗家。","静理餘無事，[攲]眠尽落花。","江光搖夕照，柳影带殘霞。","君去應相與，乘船泛月华。"]', '诗', 'shi', '', NULL, '送王秀才往松滋夏課 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7462858-2a79-4f27-91b7-d163407fde03', '喜{巩/言}公自武陵至', '喜{巩/言}公自武陵至', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["已盡滄浪興，還思相楚行。","鬢全無舊黑，詩別有新清。","暫憇臨寒水，時來扣靜荆。","囊中有靈藥，終不獻公卿。"]', '["已尽滄浪兴，還思相楚行。","鬢全無旧黑，诗別有新清。","暫憇臨寒水，时来扣静荆。","囊中有靈藥，終不獻公卿。"]', '诗', 'shi', '', NULL, '喜{巩/言}公自武陵至 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6cee7519-f5f6-49d7-b973-e371d47fcfe1', '假山', '假山', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["匡廬久別離，積翠杳天涯。","靜室曾圖峭，幽亭復創奇。","典衣酬土價，擇日運工時。","信手成重疊，隨心作蔽虧。","根盤驚院窄，頂聳訝簷卑。","鎮地那言重，當軒未厭危。","巨靈何忍擘，秦政肯輕移。","晚覺莎煙觸，寒聞竹籟吹。","藍灰澄古色，泥水合凝滋。","引看僧來數，牽吟客散遲。","九華渾髣髴，五老頗參差。","蛛網藤蘿挂，春霖瀑布垂。","加添雙石笋，映帶小蓮池。","舊說雷居士，曾聞遠大師。","紅霞中結社，白壁上題詩。","顧此誠徒爾，勞心是妄爲。","經營慙培塿，賞翫愧童兒。","會入千峯去，[閑]蹤任屬誰。"]', '["匡廬久別離，積翠杳天涯。","静室曾圖峭，幽亭复創奇。","典衣酬土價，擇日運工时。","信手成重叠，隨心作蔽虧。","根盤驚院窄，頂聳訝簷卑。","鎮地那言重，當軒未厭危。","巨靈何忍擘，秦政肯轻移。","晚覺莎煙觸，寒闻竹籟吹。","藍灰澄古色，泥水合凝滋。","引看僧来數，牽吟客散遲。","九华渾髣髴，五老頗參差。","蛛網藤蘿挂，春霖瀑布垂。","加添雙石笋，映带小蓮池。","旧说雷居士，曾闻远大師。","紅霞中結社，白壁上題诗。","顧此誠徒爾，勞心是妄爲。","經營慙培塿，賞翫愧童兒。","會入千峯去，[闲]蹤任屬誰。"]', '诗', 'shi', '', NULL, '假山 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a53b111a-c5a2-4f7e-8304-662e7d18451e', '謝西川可準上人遠寄詩集', '謝西川可準上人远寄诗集', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["匡社經行外，沃洲禪宴餘。","吾師還繼此，後輩復何如。","江上傳風雅，靜中時卷舒。","堪隨樂天集，共伴白芙蕖。"]', '["匡社經行外，沃洲禪宴餘。","吾師還繼此，後輩复何如。","江上傳风雅，静中时卷舒。","堪隨乐天集，共伴白芙蕖。"]', '诗', 'shi', '', NULL, '謝西川可準上人遠寄詩集 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('49e7f63d-6571-4ae8-bdba-45e325d04945', '秋空', '秋空', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["已覺秋空極，更堪寥泬青。","只應容好月，爭合有妖星。","耿耿高河截，翛翛一雁經。","曾於洞庭宿，上下徹心靈。"]', '["已覺秋空極，更堪寥泬青。","只應容好月，爭合有妖星。","耿耿高河截，翛翛一雁經。","曾於洞庭宿，上下徹心靈。"]', '诗', 'shi', '', NULL, '秋空 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('382a3b64-6374-455b-a715-9d577c482db9', '與聶尊師話道', '與聶尊師話道', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["伯陽遺妙旨，杳杳與冥冥。","說即非難說，行還不易行。","藥中迷九轉，心外覓長生。","畢竟荒原上，一盤蒿隴平。"]', '["伯陽遺妙旨，杳杳與冥冥。","说即非难说，行還不易行。","藥中迷九轉，心外覓长生。","畢竟荒原上，一盤蒿隴平。"]', '诗', 'shi', '', NULL, '與聶尊師話道 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e29ac01-f34f-4c12-9e77-73e6ce9b9e41', '送相里秀才自京至却迴', '送相里秀才自京至却迴', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["夷門詩客至，楚寺閉蕭騷。","老病語言澀，少年風韻高。","難於尋閬島，險甚涉雲濤。","珍重西歸去，無忘役思勞。"]', '["夷门诗客至，楚寺閉蕭騷。","老病語言澀，少年风韻高。","难於尋閬島，險甚涉云濤。","珍重西归去，無忘役思勞。"]', '诗', 'shi', '', NULL, '送相里秀才自京至却迴 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b287f163-b33d-4e59-992f-0e13d164075e', '謝人寄南榴卓子', '謝人寄南榴卓子', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["幸附全材長，良工斸器殊。","千林文栢有，一尺錦榴無。","品格宜仙果，精光稱玉壺。","憐君遠相寄，多愧野蔬麤。"]', '["幸附全材长，良工斸器殊。","千林文栢有，一尺錦榴無。","品格宜仙果，精光稱玉壺。","怜君远相寄，多愧野蔬麤。"]', '诗', 'shi', '', NULL, '謝人寄南榴卓子 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5445ef9-62b4-4f4f-9462-1bd1eba27b5e', '寄舊居隣友', '寄旧居隣友', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["別後知何趣，搜奇少客同。","幾層山影下，萬樹雪聲中。","晚鼎烹茶綠，晨廚爨粟紅。","何時攜卷出，世代有名公。"]', '["別後知何趣，搜奇少客同。","幾層山影下，万樹雪声中。","晚鼎烹茶綠，晨廚爨粟紅。","何时携卷出，世代有名公。"]', '诗', 'shi', '', NULL, '寄舊居隣友 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ce1a692-e2b1-459b-b6b3-7d05a3c3e5c8', '送朱秀才歸閩', '送朱秀才归閩', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["荆門來幾日，欲往又囊空。","遠客歸南越，單衣背北風。","近鄉微有雪，到海漸無鴻。","努力成詩業，無謀謁至公。"]', '["荆门来幾日，欲往又囊空。","远客归南越，單衣背北风。","近乡微有雪，到海漸無鴻。","努力成诗業，無謀謁至公。"]', '诗', 'shi', '', NULL, '送朱秀才歸閩 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('529f8a00-8427-4bb2-b44a-423e30a60555', '龍潭作', '龙潭作', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["乍臨毛髮豎，雙壁夾湍流。","白日鳥影過，青苔龍氣浮。","蔽空雲出石，應禱雨翻湫。","四面耕桑者，先聞賀有秋。"]', '["乍臨毛髮豎，雙壁夾湍流。","白日鸟影過，青苔龙氣浮。","蔽空云出石，應禱雨翻湫。","四面耕桑者，先闻賀有秋。"]', '诗', 'shi', '', NULL, '龍潭作 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c1381762-eaca-4d76-a975-f2f1bc452257', '依韻酬謝尊師見贈二首 一', '依韻酬謝尊師见贈二首 一', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["南國搜奇久，偏傷杜甫墳。","重來經漢浦，又去入嵩雲。","舊別人稀見，新朝事漸聞。","莫將高尚跡，閑處傲明君。"]', '["南国搜奇久，偏傷杜甫墳。","重来經漢浦，又去入嵩云。","旧別人稀见，新朝事漸闻。","莫將高尚跡，闲处傲明君。"]', '诗', 'shi', '', NULL, '依韻酬謝尊師見贈二首 一 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b2f368df-6460-4a8a-a50e-067120f6a62e', '依韻酬謝尊師見贈二首 二', '依韻酬謝尊師见贈二首 二', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["嶽頂休高臥，荆門訪掩扉。","新詩遺我別，舊約與誰歸。","賢路曾無滯，良時肯自違。","明年窺日窟，仙桂露霏微。"]', '["嶽頂休高臥，荆门訪掩扉。","新诗遺我別，旧約與誰归。","賢路曾無滯，良时肯自違。","明年窺日窟，仙桂露霏微。"]', '诗', 'shi', '', NULL, '依韻酬謝尊師見贈二首 二 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f8322ff-7c32-4fe4-91fe-9435aecf8c68', '送冰禪再往湖中', '送冰禪再往湖中', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["行心寧肯住，南去與誰羣。","碧落高空處，清秋一片雲。","穿林瓶影滅，背雨錫聲分。","應笑遊方久，龍鍾楚水濆。"]', '["行心寧肯住，南去與誰羣。","碧落高空处，清秋一片云。","穿林瓶影滅，背雨錫声分。","應笑游方久，龙鍾楚水濆。"]', '诗', 'shi', '', NULL, '送冰禪再往湖中 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('187f7b35-5b29-45bc-bafe-bc52158d0e7e', '喜表公往楚王城', '喜表公往楚王城', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["已聞人捨地，結構舊基平。","一面湖光白，鄰家竹影清。","應難尋輦道，空說是王城。","誰信興亡跡，今來有磬聲。"]', '["已闻人捨地，結構旧基平。","一面湖光白，鄰家竹影清。","應难尋輦道，空说是王城。","誰信兴亡跡，今来有磬声。"]', '诗', 'shi', '', NULL, '喜表公往楚王城 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b0a827f4-c831-495e-8d03-403e6adecf57', '春雪初晴喜友生至', '春雪初晴喜友生至', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["數日不見日，飄飄勢忽開。","雖無忙事出，還有故人來。","已盡南簷滴，仍殘北牖堆。","明朝望平遠，相約在春臺。"]', '["數日不见日，飄飄勢忽开。","雖無忙事出，還有故人来。","已尽南簷滴，仍殘北牖堆。","明朝望平远，相約在春台。"]', '诗', 'shi', '', NULL, '春雪初晴喜友生至 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce741969-818b-4249-9595-72962b75aac4', '殘春連雨中偶作懷故人', '殘春連雨中偶作懷故人', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["南鄰阻杖藜，屐齒遶牀泥。","漠漠門長掩，遲遲日又西。","不知何興味，更有好詩題。","還憶東林否，行苔傍虎溪。"]', '["南鄰阻杖藜，屐齒遶牀泥。","漠漠门长掩，遲遲日又西。","不知何兴味，更有好诗題。","還憶东林否，行苔傍虎溪。"]', '诗', 'shi', '', NULL, '殘春連雨中偶作懷故人 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e2604ea6-5676-4a2a-b1b0-cfe1e8c70e7c', '送崔判官赴歸倅', '送崔判官赴归倅', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["白首從顏巷，青袍去佐官。","只應微俸祿，聊補舊飢寒。","地說丘墟甚，民聞旱歉殘。","春風吹綺席，賓主醉相歡。"]', '["白首從顏巷，青袍去佐官。","只應微俸祿，聊補旧飢寒。","地说丘墟甚，民闻旱歉殘。","春风吹綺席，賓主醉相歡。"]', '诗', 'shi', '', NULL, '送崔判官赴歸倅 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c9e8cbd1-1f7b-4021-bf12-747e5207fd84', '寒食日懷寄友人', '寒食日懷寄友人', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["萬井追寒食，閑扉獨不開。","梨花應折盡，柳絮自飛來。","夢覺懷仙島，吟行遶砌苔。","浮生已悟了，時節任相催。"]', '["万井追寒食，闲扉独不开。","梨花應折尽，柳絮自飞来。","梦覺懷仙島，吟行遶砌苔。","浮生已悟了，时節任相催。"]', '诗', 'shi', '', NULL, '寒食日懷寄友人 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c68a41ae-a46f-4772-9be4-2520fc9af597', '懷巴陵舊遊', '懷巴陵旧游', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["洞庭雲夢秋，空碧共悠悠。","孟子狂題後，何人更倚樓。","日西來遠棹，風外見平流。","終欲重尋去，僧窗古岸頭。"]', '["洞庭云梦秋，空碧共悠悠。","孟子狂題後，何人更倚楼。","日西来远棹，风外见平流。","終欲重尋去，僧窗古岸头。"]', '诗', 'shi', '', NULL, '懷巴陵舊遊 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('11219b1a-a88a-4404-a9a2-3e17ea6f9f41', '招乾晝上人宿話', '招乾晝上人宿話', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["連夜因風雪，相留在寂寥。","禪心誰指示，詩卷自焚燒。","語默鄰寒漏，窗扉向早朝。","天台若長往，還渡海門潮。"]', '["連夜因风雪，相留在寂寥。","禪心誰指示，诗卷自焚燒。","語默鄰寒漏，窗扉向早朝。","天台若长往，還渡海门潮。"]', '诗', 'shi', '', NULL, '招乾晝上人宿話 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dccb3b25-1628-4de0-9ca8-82a7b36c6b03', '荆門秋日寄友人', '荆门秋日寄友人', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["青溪知不遠，白首要難歸。","空想煙雲裏，春風鸞鶴飛。","誰論傳法偈，自補坐禪衣。","未謝侯門去，尋常即掩扉。"]', '["青溪知不远，白首要难归。","空想煙云裏，春风鸾鹤飞。","誰論傳法偈，自補坐禪衣。","未謝侯门去，尋常即掩扉。"]', '诗', 'shi', '', NULL, '荆門秋日寄友人 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f04fc4c7-cefc-4ed3-8f84-b993dd9a557e', '哭鄭谷郎中', '哭鄭谷郎中', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["朝衣閑典盡，酒病覺難醫。","下世無遺恨，傳家有大詩。","新墳青嶂疊，寒食白雲垂。","長憶招吟夜，前年風雪時。"]', '["朝衣闲典尽，酒病覺难醫。","下世無遺恨，傳家有大诗。","新墳青嶂叠，寒食白云垂。","长憶招吟夜，前年风雪时。"]', '诗', 'shi', '', NULL, '哭鄭谷郎中 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc80325a-99e4-4054-a9dc-bd9ad4243cfc', '題東林十八賢真堂', '題东林十八賢真堂', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["白藕花前舊影堂，劉雷風骨畫龍章。","共輕天子諸侯貴，同愛吾師一法長。","陶令醉多招不得，謝公心亂入無方。","何人到此思高躅，嵐點苔痕滿粉牆。"]', '["白藕花前旧影堂，劉雷风骨畫龙章。","共轻天子諸侯貴，同愛吾師一法长。","陶令醉多招不得，謝公心亂入無方。","何人到此思高躅，嵐点苔痕满粉牆。"]', '诗', 'shi', '', NULL, '題東林十八賢真堂 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('78c3aadb-7b08-4345-990e-57401f8d564b', '題南岳般若寺', '題南岳般若寺', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["諸峯翠少中峯翠，五寺名高此寺名。","石路險盤嵐靄滑，僧窗高倚泬寥明。","凌空殿閣由天設，遍地杉松是自生。","更有上方難上處，紫苔紅蘚遶崢嶸。"]', '["諸峯翠少中峯翠，五寺名高此寺名。","石路險盤嵐靄滑，僧窗高倚泬寥明。","凌空殿閣由天設，遍地杉松是自生。","更有上方难上处，紫苔紅蘚遶崢嶸。"]', '诗', 'shi', '', NULL, '題南岳般若寺 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3161e003-06a1-4c10-b9cc-fa4f4cdc6fcf', '寄廬岳僧', '寄廬岳僧', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["一聞飛錫別區中，深入西南瀑布峯。","天際雪埋千片石，洞門冰折幾株松。","煙霞明媚棲心地，苔蘚縈紆出世蹤。","莫問江邊舊居寺，火燒兵劫斷秋鐘。"]', '["一闻飞錫別區中，深入西南瀑布峯。","天際雪埋千片石，洞门冰折幾株松。","煙霞明媚棲心地，苔蘚縈紆出世蹤。","莫问江邊旧居寺，火燒兵劫斷秋鐘。"]', '诗', 'shi', '', NULL, '寄廬岳僧 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c764e5a-afbc-41ad-b82d-2858301564c5', '遊谷山寺', '游谷山寺', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["城裏尋常見碧稜，水邊朝暮送歸僧。","數峯雲脚垂平地，一徑松聲徹上層。","寒澗不生浮世物，陰崖猶積去年冰。","此身有底難拋事，時復攜筇信步登。"]', '["城裏尋常见碧稜，水邊朝暮送归僧。","數峯云脚垂平地，一徑松声徹上層。","寒澗不生浮世物，陰崖猶積去年冰。","此身有底难拋事，时复携筇信步登。"]', '诗', 'shi', '', NULL, '遊谷山寺 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c7e3855-313c-491c-9d69-d4ed7dacf80d', '楚寺寒夜作', '楚寺寒夜作', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["寒爐局促坐成勞，暗淡燈光照二毛。","水寺閑來僧寂寂，雪風吹去雁嗷嗷。","江山積疊歸程遠，魂夢穿沿過處高。","畢竟忘言是吾道，袈裟不稱揖蕭曹。"]', '["寒爐局促坐成勞，暗淡灯光照二毛。","水寺闲来僧寂寂，雪风吹去雁嗷嗷。","江山積叠归程远，魂梦穿沿過处高。","畢竟忘言是吾道，袈裟不稱揖蕭曹。"]', '诗', 'shi', '', NULL, '楚寺寒夜作 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('60d33344-d3cc-497c-b5c0-f59ee8e6b9f4', '送泰禪師歸南岳', '送泰禪師归南岳', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["石龕閑鏁白猨邊，歸去程途半在船。","林簇曉霜離水寺，路穿新燒入山泉。","已尋嵐壁臨空盡，却看星辰向地懸。","有興寄題紅葉上，不妨收拾別爲編。"]', '["石龕闲鏁白猨邊，归去程途半在船。","林簇晓霜離水寺，路穿新燒入山泉。","已尋嵐壁臨空尽，却看星辰向地懸。","有兴寄題紅葉上，不妨收拾別爲編。"]', '诗', 'shi', '', NULL, '送泰禪師歸南岳 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('479e0432-a820-4788-a579-0f4448c1a3e6', '山中寄凝密大師兄弟', '山中寄凝密大師兄弟', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["一爐薪盡室空然，萬象何妨在眼前。","時有興來還覓句，已無心去即安禪。","山門影落秋風樹，水國光凝夕照天。","借問荀家兄弟內，八龍頭角讓誰先。"]', '["一爐薪尽室空然，万象何妨在眼前。","时有兴来還覓句，已無心去即安禪。","山门影落秋风樹，水国光凝夕照天。","借问荀家兄弟內，八龙头角讓誰先。"]', '诗', 'shi', '', NULL, '山中寄凝密大師兄弟 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('53c6cfa7-ac39-401b-ad07-2a7c3606f75b', '海棠花', '海棠花', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["繁於桃李盛於梅，寒食旬前社後開。","半月暄和留豔態，兩時風雨免傷摧。","人憐格異詩重賦，蝶戀香多夜更來。","猶得殘紅向春暮，牡丹相繼發池臺。"]', '["繁於桃李盛於梅，寒食旬前社後开。","半月暄和留豔態，兩时风雨免傷摧。","人怜格異诗重賦，蝶戀香多夜更来。","猶得殘紅向春暮，牡丹相繼發池台。"]', '诗', 'shi', '', NULL, '海棠花 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('08fef0e4-f09b-4bf2-be68-016c0f8bff2f', '題贈湘西龍安寺利禪師', '題贈湘西龙安寺利禪師', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["頭白已無行脚念，自開荒寺住煙蘿。","門前路到瀟湘盡，石上雲歸岳麓多。","南祖衣盂曾禮謁，東林泉月舊經過。","閑來松外看城郭，一片紅塵隔逝波。"]', '["头白已無行脚念，自开荒寺住煙蘿。","门前路到瀟湘尽，石上云归岳麓多。","南祖衣盂曾禮謁，东林泉月旧經過。","闲来松外看城郭，一片紅塵隔逝波。"]', '诗', 'shi', '', NULL, '題贈湘西龍安寺利禪師 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c48bfcc5-f3b2-4451-8ee8-af4531a5026b', '寄文浩百法', '寄文浩百法', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["當時六祖在黃梅，五百人中眼獨開。","入室偈聞傳絕唱，昇堂客謾恃多才。","鐵牛無用成真角，石女能生是聖胎。","聞說欲拋經論去，莫教惆悵却空迴。"]', '["當时六祖在黄梅，五百人中眼独开。","入室偈闻傳絕唱，昇堂客謾恃多才。","鐵牛無用成真角，石女能生是聖胎。","闻说欲拋經論去，莫教惆悵却空迴。"]', '诗', 'shi', '', NULL, '寄文浩百法 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6e958390-3dd2-4373-ab95-99622c7481a6', '謝人寄新詩集', '謝人寄新诗集', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["所聞新事即戈矛，欲去終疑是暗投。","遠客寄言還有在，此門將謂總無休。","千篇著述誠難得，一字知音不易求。","時入思量向何處，月圓孤凭水邊樓。"]', '["所闻新事即戈矛，欲去終疑是暗投。","远客寄言還有在，此门將謂總無休。","千篇著述誠难得，一字知音不易求。","时入思量向何处，月圓孤凭水邊楼。"]', '诗', 'shi', '', NULL, '謝人寄新詩集 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6423f9d6-9d28-4564-bb87-b32d57f06a78', '謝元願上人遠寄檀溪集', '謝元願上人远寄檀溪集', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["白首蕭條居漢浦，清吟編集號檀溪。","有人收拾應如玉，無主知音只似泥。","入理半同黃葉句，遣懷多擬碧雲題。","猶能爲我相思在，千里封來夢澤西。"]', '["白首蕭條居漢浦，清吟編集號檀溪。","有人收拾應如玉，無主知音只似泥。","入理半同黄葉句，遣懷多擬碧云題。","猶能爲我相思在，千里封来梦澤西。"]', '诗', 'shi', '', NULL, '謝元願上人遠寄檀溪集 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80f879b3-0b18-43af-94ca-c774e89e9480', '寄道林寺諸友', '寄道林寺諸友', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["吟興終依異境長，舊遊時入靜思量。","江聲裏過東西寺，樹影中行上下方。","春色濕僧巾屨膩，松花沾鶴骨毛香。","老來何計重歸去，千里重湖浪渺茫。"]', '["吟兴終依異境长，旧游时入静思量。","江声裏過东西寺，樹影中行上下方。","春色濕僧巾屨膩，松花沾鹤骨毛香。","老来何計重归去，千里重湖浪渺茫。"]', '诗', 'shi', '', NULL, '寄道林寺諸友 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac535cf7-3d3c-4a8b-88cc-10860986b0a6', '贈智滿三藏', '贈智满三藏', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["灌頂清涼一滴通，大毗盧藏遍虛空。","欲飛薝蔔花無盡，須待陀羅尼有功。","金杵力摧魔界黑，水精光透夜燈紅。","可堪東獻明天子，命服新酬贊國風。"]', '["灌頂清涼一滴通，大毗盧藏遍虛空。","欲飞薝蔔花無尽，須待陀羅尼有功。","金杵力摧魔界黑，水精光透夜灯紅。","可堪东獻明天子，命服新酬贊国风。"]', '诗', 'shi', '', NULL, '贈智滿三藏 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('70b0dd8f-3815-40ea-9d7b-0e0c1b22d8a1', '謝王先輩湘中迴惠示卷軸', '謝王先輩湘中迴惠示卷軸', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["少小即懷風雅情，獨能遺象琢淳精。","不教霜雪侵玄鬢，便向雲霄換好名。","攜去湘江聞鼓瑟，袖來緱嶺伴吹笙。","多君百首貽衰颯，留把吟行訪竺卿。"]', '["少小即懷风雅情，独能遺象琢淳精。","不教霜雪侵玄鬢，便向云霄換好名。","携去湘江闻鼓瑟，袖来緱嶺伴吹笙。","多君百首貽衰颯，留把吟行訪竺卿。"]', '诗', 'shi', '', NULL, '謝王先輩湘中迴惠示卷軸 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3cf7c137-d5b8-48e1-812e-0ea9b056ac71', '荆渚寄懷西蜀無染大師兄', '荆渚寄懷西蜀無染大師兄', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["大潙心付白崖前，寶月分輝照蜀天。","聖主降情延北內，諸侯稽首問南禪。","清秋不動驪龍海，紅日無私罔象川。","欲聽吾宗舊山說，地邊身老楚江邊。"]', '["大潙心付白崖前，寶月分輝照蜀天。","聖主降情延北內，諸侯稽首问南禪。","清秋不动驪龙海，紅日無私罔象川。","欲听吾宗旧山说，地邊身老楚江邊。"]', '诗', 'shi', '', NULL, '荆渚寄懷西蜀無染大師兄 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('94cb5b04-e3f9-4cb2-849e-8b7657796deb', '謝武陵徐巡官遠寄五七字詩集', '謝武陵徐巡官远寄五七字诗集', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["五字才將七字爭，爲君聊敢試懸衡。","鼎湖菡萏搖金影，蓬島鸞皇舞翠聲。","還是靈龜巢得穩，要須仙子駕方行。","兩邊珍重遙相惠，何夕燈前盡此情。"]', '["五字才將七字爭，爲君聊敢試懸衡。","鼎湖菡萏搖金影，蓬島鸾皇舞翠声。","還是靈龟巢得穩，要須仙子駕方行。","兩邊珍重遙相惠，何夕灯前尽此情。"]', '诗', 'shi', '', NULL, '謝武陵徐巡官遠寄五七字詩集 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a91bf2b0-6ba5-4c88-8433-ff456d70a128', '重宿舊房與愚上人靜話', '重宿旧房與愚上人静話', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["曾此棲心過十冬，今來瀟灑屬生公。","檀欒舊植青添翠，菡萏新栽白換紅。","北面城臨燈影合，西隣壁近講聲通。","不知門下趨筵士，何似當時石解空。"]', '["曾此棲心過十冬，今来瀟灑屬生公。","檀欒旧植青添翠，菡萏新栽白換紅。","北面城臨灯影合，西隣壁近講声通。","不知门下趨筵士，何似當时石解空。"]', '诗', 'shi', '', NULL, '重宿舊房與愚上人靜話 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('69ccd68e-76b6-4472-a228-7fac8116d0a0', '謝南平王賜山雞', '謝南平王賜山雞', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["五色文章類彩鸞，楚人羅得半摧殘。","金籠莫恨傷冠幘，玉粒頒慙剪羽翰。","孤立影危丹檻裏，雙棲伴在白雲端。","上台愛育通幽細，却放溪山去不難。"]', '["五色文章類彩鸾，楚人羅得半摧殘。","金籠莫恨傷冠幘，玉粒頒慙剪羽翰。","孤立影危丹檻裏，雙棲伴在白云端。","上台愛育通幽細，却放溪山去不难。"]', '诗', 'shi', '', NULL, '謝南平王賜山雞 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e45df110-8ab8-4e43-b5bb-d8ef0ac82b63', '荆門病中雨後書懷寄幕中知己', '荆门病中雨後书懷寄幕中知己', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["病根翻作憶山勞，一雨聊堪浣鬱陶。","心白未能忘水月，眼青獨得見秋毫。","蟬聲晚簇枝枝急，雲影晴分片片高。","還憶赤松兄弟否，別來應見鶴衣毛。"]', '["病根翻作憶山勞，一雨聊堪浣鬱陶。","心白未能忘水月，眼青独得见秋毫。","蟬声晚簇枝枝急，云影晴分片片高。","還憶赤松兄弟否，別来應见鹤衣毛。"]', '诗', 'shi', '', NULL, '荆門病中雨後書懷寄幕中知己 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('759ee047-917a-4a49-affd-383fee929dd2', '宿江寺', '宿江寺', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["島僧留宿慰衰顏，舊住何妨老未還。","身共錫聲離鳥外，跡同雲影過人間。","曾無夢入朝天路，憶有詩題隔海山。","珍重來晨渡江去，九華青裏扣松關。"]', '["島僧留宿慰衰顏，旧住何妨老未還。","身共錫声離鸟外，跡同云影過人间。","曾無梦入朝天路，憶有诗題隔海山。","珍重来晨渡江去，九华青裏扣松关。"]', '诗', 'shi', '', NULL, '宿江寺 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('698fd1d7-bd94-4db8-a131-fca4bd77ef7b', '謝貫微上人寄示古風今體四軸', '謝貫微上人寄示古风今體四軸', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["四軸騷詞書八行，捧吟肌骨遍清涼。","謾求龍樹能醫眼，休問圖澄學洗腸。","今體盡搜初剖判，古風淳鑿未玄黃。","不知誰肯降文陣，闇點旌旗敵子房。"]', '["四軸騷词书八行，捧吟肌骨遍清涼。","謾求龙樹能醫眼，休问圖澄学洗腸。","今體尽搜初剖判，古风淳鑿未玄黄。","不知誰肯降文陣，闇点旌旗敵子房。"]', '诗', 'shi', '', NULL, '謝貫微上人寄示古風今體四軸 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef913822-6acf-4bb9-993c-4ebcdf3ce131', '荆州貫休大師舊房', '荆州貫休大師旧房', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["疎篁抽笋柳垂陰，舊是休公種境吟。","入貢文儒來請益，出官卿相駐過尋。","右軍書畫神傳髓，康樂文章夢授心。","銷得青城千嶂下，白蓮標塔帝恩深。"]', '["疎篁抽笋柳垂陰，旧是休公種境吟。","入貢文儒来請益，出官卿相駐過尋。","右軍书畫神傳髓，康乐文章梦授心。","銷得青城千嶂下，白蓮標塔帝恩深。"]', '诗', 'shi', '', NULL, '荆州貫休大師舊房 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cdb5e910-b2dd-472d-a292-3fd991281be0', '寄谷山長老', '寄谷山长老', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["遊遍名山祖遍尋，却來塵世渾光陰。","肯將的的吾師意，擬付茫茫弟子心。","豈有虛空遮道眼，不妨文字問知音。","滄浪萬頃三更月，天上何如水底深。"]', '["游遍名山祖遍尋，却来塵世渾光陰。","肯將的的吾師意，擬付茫茫弟子心。","豈有虛空遮道眼，不妨文字问知音。","滄浪万頃三更月，天上何如水底深。"]', '诗', 'shi', '', NULL, '寄谷山長老 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03f9784e-5572-4bd5-a336-edd81a34b189', '寄黃暉處士', '寄黄暉处士', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["蒙氏藝傳黃氏子，獨聞相繼得名高。","鋒鋩妙奪金雞距，纖利精分玉兔毫。","濡染只應親賦詠，風流不稱近方刀。","何妨寄我臨池興，忍使江淹役夢勞。"]', '["蒙氏藝傳黄氏子，独闻相繼得名高。","鋒鋩妙奪金雞距，纖利精分玉兔毫。","濡染只應親賦詠，风流不稱近方刀。","何妨寄我臨池兴，忍使江淹役梦勞。"]', '诗', 'shi', '', NULL, '寄黃暉處士 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f52e91b4-136a-419b-929c-3a768939524b', '荆門勉懷寄道林寺諸友', '荆门勉懷寄道林寺諸友', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["榮枯得失理昭然，誰斅離騷更問天。","生下便知真夢幻，老來何必歎流年。","清風不變詩應在，明月無蹤道可傳。","珍重匡廬沃洲主，拂衣拋却好林泉。"]', '["榮枯得失理昭然，誰斅離騷更问天。","生下便知真梦幻，老来何必歎流年。","清风不变诗應在，明月無蹤道可傳。","珍重匡廬沃洲主，拂衣拋却好林泉。"]', '诗', 'shi', '', NULL, '荆門勉懷寄道林寺諸友 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1fa14626-2576-4120-be7f-9b7a44b71295', '荅崔校書', '荅崔校书', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["雪色衫衣絕點塵，明知富貴是浮雲。","不隨喧滑迷真性，何用潺湲洗汚聞。","北闕會拋紅駊騀，東林社憶白氛氳。","清吟有興頻相示，欲得多慙蠹蝕文。"]', '["雪色衫衣絕点塵，明知富貴是浮云。","不隨喧滑迷真性，何用潺湲洗汚闻。","北闕會拋紅駊騀，东林社憶白氛氳。","清吟有兴頻相示，欲得多慙蠹蝕文。"]', '诗', 'shi', '', NULL, '荅崔校書 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a7c74d4-ccf3-44ea-8c23-5caadc174805', '乞櫻桃', '乞櫻桃', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["去年曾賦此花詩，幾聽南園爛熟時。","嚼破紅香堪換骨，摘殘丹顆欲燒枝。","流鶯偷啄心應醉，行客潛窺眼亦癡。","聞說張筵就珠樹，任從攀折半離披。"]', '["去年曾賦此花诗，幾听南园爛熟时。","嚼破紅香堪換骨，摘殘丹顆欲燒枝。","流鶯偷啄心應醉，行客潛窺眼亦癡。","闻说張筵就珠樹，任從攀折半離披。"]', '诗', 'shi', '', NULL, '乞櫻桃 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e3fd930-32f2-4055-a97a-f45045d26e40', '寄南雅上人', '寄南雅上人', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["曾得音書慰暮年，相思多故信難傳。","清吟何處題紅葉，舊社空懷墮白蓮。","山水本同真趣向，侯門剛有薄因緣。","他時不得君招隱，會逐南歸楚客船。"]', '["曾得音书慰暮年，相思多故信难傳。","清吟何处題紅葉，旧社空懷墮白蓮。","山水本同真趣向，侯门剛有薄因緣。","他时不得君招隐，會逐南归楚客船。"]', '诗', 'shi', '', NULL, '寄南雅上人 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e0d3b21d-07c4-468c-856b-650d7f34d1d7', '寄歐陽侍郎', '寄歐陽侍郎', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["又聞繁總在嘉州，職重身閑倚寺樓。","大象影和山面落，兩江聲合郡前流。","棋輕國手知難敵，詩是天才肯易酬。","畢竟男兒自高達，從來心不是悠悠。"]', '["又闻繁總在嘉州，職重身闲倚寺楼。","大象影和山面落，兩江声合郡前流。","棋轻国手知难敵，诗是天才肯易酬。","畢竟男兒自高達，從来心不是悠悠。"]', '诗', 'shi', '', NULL, '寄歐陽侍郎 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9421ca75-ec29-4853-b00d-e3a7fe24e0a8', '與崔校書靜話言懷', '與崔校书静話言懷', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["同年生在咸通裏，事佛爲儒趣盡高。","我性已甘披祖衲，君心猶待脫藍袍。","霜髭曉幾臨銅鏡，雪鬢寒疎落剃刀。","出世朝天俱未得，不妨還往有風騷。"]', '["同年生在咸通裏，事佛爲儒趣尽高。","我性已甘披祖衲，君心猶待脫藍袍。","霜髭晓幾臨銅镜，雪鬢寒疎落剃刀。","出世朝天俱未得，不妨還往有风騷。"]', '诗', 'shi', '', NULL, '與崔校書靜話言懷 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64ebd3bb-0b7f-402a-8ab4-ea31cb490079', '謝人惠拄杖', '謝人惠拄杖', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["邛州靈境產修篁，九節材應表九陽。","造化已能分尺度，保持爭合與尋常。","幽林剪破清秋影，高手攜來綠玉光。","深謝魯儒憐潦倒，欲教撐拄遶禪牀。"]', '["邛州靈境產修篁，九節材應表九陽。","造化已能分尺度，保持爭合與尋常。","幽林剪破清秋影，高手携来綠玉光。","深謝魯儒怜潦倒，欲教撐拄遶禪牀。"]', '诗', 'shi', '', NULL, '謝人惠拄杖 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c4422f1-a943-453f-92ab-f5e9b10371a2', '謝秦府推官寄丹臺集', '謝秦府推官寄丹台集', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["秦王手筆序丹臺，不錯褒揚最上才。","鳳闕幾傳爲匠碩，龍門曾用振風雷。","錢郎未竭精華去，元白終存作者來。","兩軸蚌胎驪頷耀，枉臨禪室伴寒灰。"]', '["秦王手笔序丹台，不錯褒揚最上才。","鳳闕幾傳爲匠碩，龙门曾用振风雷。","錢郎未竭精华去，元白終存作者来。","兩軸蚌胎驪頷耀，枉臨禪室伴寒灰。"]', '诗', 'shi', '', NULL, '謝秦府推官寄丹臺集 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0cd71b5-447f-47c1-b7fd-c1897b40a355', '題畫鷺鷥兼簡孫郎中', '題畫鷺鷥兼簡孫郎中', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["曾向滄江看不真，却因圖畫見精神。","何妨金粉資高格，不用丹青點此身。","蒲葉岸長堪映帶，荻花叢晚好相親。","思量畫得勝籠得，野性由來不戀人。"]', '["曾向滄江看不真，却因圖畫见精神。","何妨金粉資高格，不用丹青点此身。","蒲葉岸长堪映带，荻花叢晚好相親。","思量畫得勝籠得，野性由来不戀人。"]', '诗', 'shi', '', NULL, '題畫鷺鷥兼簡孫郎中 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d4eabee-0c78-4b7a-b0e8-d72fc2ce4568', '賀行軍太傅得白氏東林集', '賀行軍太傅得白氏东林集', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["樂天歌詠有遺編，留在東林伴白蓮。","百尺典墳隨喪亂，一家風雅獨完全。","常聞荆渚通侯論，果遂吳都使者傳。","仰賀斯文歸朗鑒，永資聲政入薰弦。"]', '["乐天歌詠有遺編，留在东林伴白蓮。","百尺典墳隨喪亂，一家风雅独完全。","常闻荆渚通侯論，果遂吳都使者傳。","仰賀斯文归朗鑒，永資声政入薰弦。"]', '诗', 'shi', '', NULL, '賀行軍太傅得白氏東林集 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cde282bf-0fc9-4137-b86d-2ea05b7e800c', '韶陽微公', '韶陽微公', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["曲江晴影石千株，吾子思歸夢斷初。","有信北來山疊疊，無言南去雨疎疎。","祖師門接園林路，丞相家同井邑居。","閑野老身留得否，相招多是秀才書。"]', '["曲江晴影石千株，吾子思归梦斷初。","有信北来山叠叠，無言南去雨疎疎。","祖師门接园林路，丞相家同井邑居。","闲野老身留得否，相招多是秀才书。"]', '诗', 'shi', '', NULL, '韶陽微公 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('99059bde-ecf3-413e-820c-586952a4ef99', '將之匡岳過尋陽', '將之匡岳過尋陽', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["帆過尋陽晚霽開，西風北雁似相催。","大都浪後青堆沒，五老雲中翠疊來。","此路便堪歸水石，何門更合向塵埃。","遠公林下蓮池畔，箇箇高人盡有才。"]', '["帆過尋陽晚霽开，西风北雁似相催。","大都浪後青堆沒，五老云中翠叠来。","此路便堪归水石，何门更合向塵埃。","远公林下蓮池畔，箇箇高人尽有才。"]', '诗', 'shi', '', NULL, '將之匡岳過尋陽 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c7c6ae30-66f8-49c1-ba5c-03b62bf81c12', '寄湘幕王重書記', '寄湘幕王重书記', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["拋擲浟江舊釣磯，日參籌畫廢吟詩。","可能有事關心後，得似無人識面時。","官好近聞加茜服，藥靈曾說換霜髭。","高才直氣平生志，除却徒知即不知。"]', '["拋擲浟江旧釣磯，日參籌畫廢吟诗。","可能有事关心後，得似無人識面时。","官好近闻加茜服，藥靈曾说換霜髭。","高才直氣平生志，除却徒知即不知。"]', '诗', 'shi', '', NULL, '寄湘幕王重書記 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d5cc543d-11aa-4deb-aa8d-5e17b2f72a0b', '宿沈彬進士書院', '宿沈彬進士书院', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["相期只爲話篇章，踏雪曾來宿此房。","喧滑盡消城漏滴，窗扉初掩岳茶香。","舊山春暖生薇蕨，大國塵昏懼殺傷。","應有太平時節在，寒宵未臥共思量。"]', '["相期只爲話篇章，踏雪曾来宿此房。","喧滑尽消城漏滴，窗扉初掩岳茶香。","旧山春暖生薇蕨，大国塵昏懼殺傷。","應有太平时節在，寒宵未臥共思量。"]', '诗', 'shi', '', NULL, '宿沈彬進士書院 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6df5256e-78af-4c54-9395-007ad3463acf', '靜院', '静院', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["花院相重點破苔，誰心肯此話心灰。","好風時傍疎篁起，幽鳥晚從何處來？","筆硯興狂師沈謝，香燈魂斷憶宗雷。","浮生已問空王了，箭急光陰一任催。"]', '["花院相重点破苔，誰心肯此話心灰。","好风时傍疎篁起，幽鸟晚從何处来？","笔硯兴狂師沈謝，香灯魂斷憶宗雷。","浮生已问空王了，箭急光陰一任催。"]', '诗', 'shi', '', NULL, '靜院 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a89b1879-338a-4912-a6c6-5e21bac3f4d2', '送白處士遊峨嵋', '送白处士游峨嵋', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["閑身誰道是羈遊，西指峨嵋碧頂頭。","琴鶴幾程隨客棹，風霜何處宿龍湫。","尋僧石磴臨天井，斸藥秋崖倒瀑流。","莫爲寰瀛多事在，客星相逐不迴休。"]', '["闲身誰道是羈游，西指峨嵋碧頂头。","琴鹤幾程隨客棹，风霜何处宿龙湫。","尋僧石磴臨天井，斸藥秋崖倒瀑流。","莫爲寰瀛多事在，客星相逐不迴休。"]', '诗', 'shi', '', NULL, '送白處士遊峨嵋 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('13e741a2-9c9e-4594-8238-e390d182754c', '寄顧蟾處士', '寄顧蟾处士', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["久聞爲客過蒼梧，休說攜家歸鏡湖。","山水顛狂應盡在，[鬢]毛凋落免貧無。","和僧搶入雲中峭，帶鶴驅成澗底孤。","春醉醒來有餘興，因人乞與武陵圖。"]', '["久闻爲客過蒼梧，休说携家归镜湖。","山水顛狂應尽在，[鬢]毛凋落免貧無。","和僧搶入云中峭，带鹤驱成澗底孤。","春醉醒来有餘兴，因人乞與武陵圖。"]', '诗', 'shi', '', NULL, '寄顧蟾處士 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc40b164-5d54-419a-acdd-60141cad70a5', '懷金陵知舊', '懷金陵知旧', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["海門相別住荆門，六度秋光兩鬢根。","萬象倒心難蓋口，一生無事可傷魂。","石頭城外青山疊，北固窗前白浪翻。","盡是共游題版處，有誰惆悵拂苔痕。"]', '["海门相別住荆门，六度秋光兩鬢根。","万象倒心难蓋口，一生無事可傷魂。","石头城外青山叠，北固窗前白浪翻。","尽是共游題版处，有誰惆悵拂苔痕。"]', '诗', 'shi', '', NULL, '懷金陵知舊 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('907749c8-6b53-4587-a4c2-d0ef699e13c8', '喜得自牧上人書', '喜得自牧上人书', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["吳都使者泛驚濤，靈一傳書慰毳袍。","別興偶隨雲水遠，知音本自國風高。","身依閑淡中銷日，髮向清涼處落刀。","聞著括囊新集了，擬教誰與序離騷。"]', '["吳都使者泛驚濤，靈一傳书慰毳袍。","別兴偶隨云水远，知音本自国风高。","身依闲淡中銷日，髮向清涼处落刀。","闻著括囊新集了，擬教誰與序離騷。"]', '诗', 'shi', '', NULL, '喜得自牧上人書 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f2263b7-4acf-4fc8-9c8b-0b64421f5ce0', '驚秋', '驚秋', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["曉窗驚覺向秋風，萬里心凝淡蕩中。","池影碎飜紅菡萏，井聲乾落綠梧桐。","破除閑事渾歸道，銷耗勞生旋逐空。","妖殺九原狐兔意，豈知丘隴是英雄。"]', '["晓窗驚覺向秋风，万里心凝淡蕩中。","池影碎飜紅菡萏，井声乾落綠梧桐。","破除闲事渾归道，銷耗勞生旋逐空。","妖殺九原狐兔意，豈知丘隴是英雄。"]', '诗', 'shi', '', NULL, '驚秋 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('408fa9f3-969b-4ced-872d-3c67988c8b9a', '聞沈彬赴吳都請辟', '闻沈彬赴吳都請辟', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["長訝高眠得穩無，果隨徵辟起江湖。","鴛鴦已列罇罍貴，鷗鶴休懷釣渚孤。","白日不妨扶漢祚，清才何讓賦吳都。","可能更憶相尋夜，雪滿諸峯火一爐。"]', '["长訝高眠得穩無，果隨徵辟起江湖。","鴛鴦已列罇罍貴，鷗鹤休懷釣渚孤。","白日不妨扶漢祚，清才何讓賦吳都。","可能更憶相尋夜，雪满諸峯火一爐。"]', '诗', 'shi', '', NULL, '聞沈彬赴吳都請辟 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8664f8c0-15c3-46f6-a291-12d426efd682', '寄江夏仁公', '寄江夏仁公', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["寺閣高連黃鶴樓，簷前檻底大江流。","幾因秋霽澄空外，獨爲詩情到上頭。","白日有餘閑送客，紫衣何啻貴封侯。","別來多少新吟也，不寄南宗老比丘。"]', '["寺閣高連黄鹤楼，簷前檻底大江流。","幾因秋霽澄空外，独爲诗情到上头。","白日有餘闲送客，紫衣何啻貴封侯。","別来多少新吟也，不寄南宗老比丘。"]', '诗', 'shi', '', NULL, '寄江夏仁公 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f478fc9-82f5-46bb-a7c2-32c312f2109a', '中春林下偶作', '中春林下偶作', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["淨境無人可共攜，閑眠未起日光低。","浮生莫把還丹續，萬事須將至理齊。","花在月明蝴蝶夢，雨餘山綠杜鵑啼。","何能向外求攀折，巖桂枝條拂石梯。"]', '["淨境無人可共携，闲眠未起日光低。","浮生莫把還丹續，万事須將至理齊。","花在月明蝴蝶梦，雨餘山綠杜鵑啼。","何能向外求攀折，巖桂枝條拂石梯。"]', '诗', 'shi', '', NULL, '中春林下偶作 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b1aacbaa-27b9-40c5-8ed4-5708c9b778f7', '送劉秀才歸桑水寧覲', '送劉秀才归桑水寧覲', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["歸和初喜戢戈矛，乍捧鄉書感去留。","雁序分飛離漢口，鴒原騫翥在鼇頭。","家鄰紫塞仍千里，路過黃河更幾州。","應到高堂問安後，却攜文入帝京遊。"]', '["归和初喜戢戈矛，乍捧乡书感去留。","雁序分飞離漢口，鴒原騫翥在鼇头。","家鄰紫塞仍千里，路過黄河更幾州。","應到高堂问安後，却携文入帝京游。"]', '诗', 'shi', '', NULL, '送劉秀才歸桑水寧覲 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f76a711-3d6a-45d4-9385-07bdda535ba5', '寄曹松', '寄曹松', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["舊制新題削復刊，工夫過甚琢琅玕。","藥中求見黃芽易，詩裏思聞白雪難。","扣寂頗同心在定，鑿空何止髮衝冠。","夜來月苦懷高論，數樹霜邊獨傍欄。"]', '["旧制新題削复刊，工夫過甚琢琅玕。","藥中求见黄芽易，诗裏思闻白雪难。","扣寂頗同心在定，鑿空何止髮衝冠。","夜来月苦懷高論，數樹霜邊独傍欄。"]', '诗', 'shi', '', NULL, '寄曹松 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b6720361-8068-43b2-b768-5be3081a5b31', '酬蜀國歐陽學士', '酬蜀国歐陽学士', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["因緣劉表駐經行，又聽西風墮葉聲。","鶴髮不堪言此世，峨嵋空約在他生。","已從禪祖參真性，敢向詩家認好名。","深愧故人憐潦倒，每傳仙語下南荆。"]', '["因緣劉表駐經行，又听西风墮葉声。","鹤髮不堪言此世，峨嵋空約在他生。","已從禪祖參真性，敢向诗家認好名。","深愧故人怜潦倒，每傳仙語下南荆。"]', '诗', 'shi', '', NULL, '酬蜀國歐陽學士 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0de2b0b9-eec7-4310-b4ee-f9e65aaa0926', '寄荆幕孫郎中', '寄荆幕孫郎中', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["珠履風流憶富春，三千鵷鷺讓精神。","詩工鑿破清求妙，道論研通白見真。","四座共推操檄健，一家誰信買書貧。","別來鄉國魂應斷，劒閣東西盡戰塵。"]', '["珠履风流憶富春，三千鵷鷺讓精神。","诗工鑿破清求妙，道論研通白见真。","四座共推操檄健，一家誰信買书貧。","別来乡国魂應斷，劒閣东西尽戰塵。"]', '诗', 'shi', '', NULL, '寄荆幕孫郎中 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5da58fe6-8dd7-404b-9039-b97f4c1de736', '謝王詹事垂訪', '謝王詹事垂訪', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["鳥外孤峯未得歸，人間觸類是無機。","方悲鹿軫棲江寺，忽訝軺車降竹扉。","王澤乍聞譚渙汗，國風那得話玄微。","應驚老病炎天裏，枯骨肩橫一衲衣。"]', '["鸟外孤峯未得归，人间觸類是無機。","方悲鹿軫棲江寺，忽訝軺车降竹扉。","王澤乍闻譚渙汗，国风那得話玄微。","應驚老病炎天裏，枯骨肩橫一衲衣。"]', '诗', 'shi', '', NULL, '謝王詹事垂訪 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('90ba8d2f-0cd0-4b92-a735-9b95b652a47b', '題南平後園牡丹', '題南平後园牡丹', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["暖披煙豔照西園，翠幄朱欄護列仙。","玉帳笙歌留盡日，瑤臺伴侶待歸天。","香多覺受風光剩，紅重知含雨露偏。","上客分明記開處，明年開更勝今年。"]', '["暖披煙豔照西园，翠幄朱欄護列仙。","玉帳笙歌留尽日，瑤台伴侶待归天。","香多覺受风光剩，紅重知含雨露偏。","上客分明記开处，明年开更勝今年。"]', '诗', 'shi', '', NULL, '題南平後園牡丹 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b149cbb-8afb-4733-8c81-3b2ddec93ee7', '和李書記', '和李书記', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["繁極全分青帝功，開時獨占上春風。","吳姬舞雪非真豔，漢后題詩是怨紅。","遠蜨戀香拋別苑，野鶯銜得出深宮。","君看萬態當筵處，羞殺薔薇點碎叢。"]', '["繁極全分青帝功，开时独占上春风。","吳姬舞雪非真豔，漢后題诗是怨紅。","远蜨戀香拋別苑，野鶯銜得出深宮。","君看万態當筵处，羞殺薔薇点碎叢。"]', '诗', 'shi', '', NULL, '和李書記 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('90cd671b-e7d6-44da-98dd-98b545733145', '謝孫郎中寄示', '謝孫郎中寄示', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["一念禪餘味國風，早因持論偶名公。","久傷琴喪人亡後，忽有雲和雪唱同。","繩琢靜聞罤象外，是非閑見寂寥中。","時來日往緣真趣，不覺秋江度塞鴻。"]', '["一念禪餘味国风，早因持論偶名公。","久傷琴喪人亡後，忽有云和雪唱同。","繩琢静闻罤象外，是非闲见寂寥中。","时来日往緣真趣，不覺秋江度塞鴻。"]', '诗', 'shi', '', NULL, '謝孫郎中寄示 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf679d8e-9c66-443b-ba26-8483114622d4', '愛吟', '愛吟', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["正堪凝思掩禪扃，又被詩魔惱竺卿。","偶凭窗扉從落照，不眠風雪到殘更。","皎然未必迷前習，支遁寧非悟後生。","傳寫會逢精鑒者，也應知是詠閑情。"]', '["正堪凝思掩禪扃，又被诗魔惱竺卿。","偶凭窗扉從落照，不眠风雪到殘更。","皎然未必迷前習，支遁寧非悟後生。","傳寫會逢精鑒者，也應知是詠闲情。"]', '诗', 'shi', '', NULL, '愛吟 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2bbc37d7-649f-4ab0-bb44-d629736310ab', '寄懷東林寺匡白監寺', '寄懷东林寺匡白監寺', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["南岳別來無約後，東林歸住有前緣。","閑搜好句題紅葉，靜斂霜眉對白蓮。","雁塔影分疎檜月，虎溪聲合幾峯泉。","修心若似伊耶舍，傳記須添十九賢。"]', '["南岳別来無約後，东林归住有前緣。","闲搜好句題紅葉，静斂霜眉对白蓮。","雁塔影分疎檜月，虎溪声合幾峯泉。","修心若似伊耶舍，傳記須添十九賢。"]', '诗', 'shi', '', NULL, '寄懷東林寺匡白監寺 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b21f9b40-9614-4147-88e6-1feb24e56553', '謝人惠十色花牋幷棋子', '謝人惠十色花牋幷棋子', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["陵州棋子浣花牋，深愧攜來自錦州。","海蚌琢成星落落，吳綾隱出雁翩翩。","留防桂苑題詩客，惜寄桃源敵手仙。","捧受不堪思出處，七千餘里劒門前。"]', '["陵州棋子浣花牋，深愧携来自錦州。","海蚌琢成星落落，吳綾隐出雁翩翩。","留防桂苑題诗客，惜寄桃源敵手仙。","捧受不堪思出处，七千餘里劒门前。"]', '诗', 'shi', '', NULL, '謝人惠十色花牋幷棋子 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('521f5114-a3ab-4cad-97ca-0ec76f4237a3', '夏日寓居寄友人', '夏日寓居寄友人', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["北遊兵阻復南還，因寄荆州病掩關。","日月坐銷江上寺，清涼魂斷剡中山。","披緇影跡堪藏拙，出世身心合向閑。","多謝扶風大君子，相思時到寂寥間。"]', '["北游兵阻复南還，因寄荆州病掩关。","日月坐銷江上寺，清涼魂斷剡中山。","披緇影跡堪藏拙，出世身心合向闲。","多謝扶风大君子，相思时到寂寥间。"]', '诗', 'shi', '', NULL, '夏日寓居寄友人 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d9b4c79-fb34-46de-b9a6-4a5abed3e38a', '中秋十四日夜對月上南平主人', '中秋十四日夜对月上南平主人', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["今宵前夕皆堪翫，何必圓時始竭才。","空說輪中有天子，不知何處是樓臺？","終憂明夜雲遮却，且埽閑居坐看來。","玉兔銀蟾似多意，乍臨棠樹影裴回。"]', '["今宵前夕皆堪翫，何必圓时始竭才。","空说輪中有天子，不知何处是楼台？","終憂明夜云遮却，且埽闲居坐看来。","玉兔銀蟾似多意，乍臨棠樹影裴回。"]', '诗', 'shi', '', NULL, '中秋十四日夜對月上南平主人 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa36ef5d-e5f9-40d9-85fb-d73e935d5bec', '謝人惠十才子圖', '謝人惠十才子圖', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["丹青妙寫十才人，玉峭冰稜姑射神。","醉舞離披真鸑鷟，狂吟崩倒瑞麒麟。","飜騰造化山曾竭，採掇珠璣海幾貧。","猶得知音與圖畫，草堂閑挂似相親。"]', '["丹青妙寫十才人，玉峭冰稜姑射神。","醉舞離披真鸑鷟，狂吟崩倒瑞麒麟。","飜腾造化山曾竭，採掇珠璣海幾貧。","猶得知音與圖畫，草堂闲挂似相親。"]', '诗', 'shi', '', NULL, '謝人惠十才子圖 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bcadd6e1-05cf-4e4d-981f-a26d44e49960', '荆門病中寄懷鄉人歐陽侍郎彬', '荆门病中寄懷乡人歐陽侍郎彬', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["誰會荆州一老夫，夢勞神役憶匡廬。","碧雲雁影紛紛去，黃葉蟾聲漸漸無。","口淡莫分餐氣味，身羸但覺病肌膚。","可憐饌玉燒蘭者，肯慰寒偎雪夜爐。"]', '["誰會荆州一老夫，梦勞神役憶匡廬。","碧云雁影紛紛去，黄葉蟾声漸漸無。","口淡莫分餐氣味，身羸但覺病肌膚。","可怜饌玉燒蘭者，肯慰寒偎雪夜爐。"]', '诗', 'shi', '', NULL, '荆門病中寄懷鄉人歐陽侍郎彬 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('44cfe45d-a987-435f-b01e-deeef3e7f9ce', '送譚三藏入京', '送譚三藏入京', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["阿闍梨與佛身同，灌頂難施利濟功。","持咒力須資運祚，度人心要似虛空。","東周路踏紅塵裏，北極門瞻紫氣中。","好進焚文霑帝澤，却歸天策繼真風。"]', '["阿闍梨與佛身同，灌頂难施利濟功。","持咒力須資運祚，度人心要似虛空。","东周路踏紅塵裏，北極门瞻紫氣中。","好進焚文霑帝澤，却归天策繼真风。"]', '诗', 'shi', '', NULL, '送譚三藏入京 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1810abca-6fb3-4d0e-be59-160a9dd73336', '寄酬秦府高推官輦', '寄酬秦府高推官輦', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["天台衡嶽舊曾尋，閑憶留題白石林。","歲月已殘衰颯鬢，風騷猶壯寂寥心。","緱山碧樹遮藏密，丹穴紅霞掩暎深。","爭得相逢一攜手，拂衣同去聽玄音。"]', '["天台衡嶽旧曾尋，闲憶留題白石林。","歲月已殘衰颯鬢，风騷猶壯寂寥心。","緱山碧樹遮藏密，丹穴紅霞掩暎深。","爭得相逢一携手，拂衣同去听玄音。"]', '诗', 'shi', '', NULL, '寄酬秦府高推官輦 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c168defd-466e-442c-b561-10058e26cd1d', '敘懷寄高推官', '敘懷寄高推官', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["搜新編舊與誰評，自向無聲認有聲。","已覺愛來多廢道，可堪傳去更沽名。","風松韻裏忘形坐，霜月光中共影行。","還勝御溝寒夜水，狂吟衝尹甚傷情。"]', '["搜新編旧與誰評，自向無声認有声。","已覺愛来多廢道，可堪傳去更沽名。","风松韻裏忘形坐，霜月光中共影行。","還勝御溝寒夜水，狂吟衝尹甚傷情。"]', '诗', 'shi', '', NULL, '敘懷寄高推官 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('951d6b65-df55-4929-b4d9-e04d019257e1', '送朱侍御自洛陽歸閬州寧覲', '送朱侍御自洛陽归閬州寧覲', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["尋常西望故園時，幾處魂隨落照飛。","客路舊縈秦甸出，鄉程今遶漢陽歸。","已過巫峽沈青靄，忽認峨嵋在翠微。","從此倚門休望斷，交親喜換老萊衣。"]', '["尋常西望故园时，幾处魂隨落照飞。","客路旧縈秦甸出，乡程今遶漢陽归。","已過巫峽沈青靄，忽認峨嵋在翠微。","從此倚门休望斷，交親喜換老萊衣。"]', '诗', 'shi', '', NULL, '送朱侍御自洛陽歸閬州寧覲 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba046639-36e2-4c14-a065-3fd108868e7a', '貽惠暹上人', '貽惠暹上人', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["經論功餘更業詩，又於難裏縱天機。","吳朝客見投文去，楚國僧迎著紫歸。","已得聲名先振俗，不妨風雪更探微。","金陵高憶恩門在，終挂雲帆重一飛。"]', '["經論功餘更業诗，又於难裏縱天機。","吳朝客见投文去，楚国僧迎著紫归。","已得声名先振俗，不妨风雪更探微。","金陵高憶恩门在，終挂云帆重一飞。"]', '诗', 'shi', '', NULL, '貽惠暹上人 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('582d1357-8688-4ca3-b140-7d20b9ced881', '酬西蜀廣濟大師見寄', '酬西蜀廣濟大師见寄', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["猶得吾師繼頌聲，百篇相愛寄南荆。","卷開錦水霞光爛，吟入峨嵋雪氣清。","楚外已甘推絕唱，蜀中誰敢共懸衡。","應憐無可同無本，終向風騷作弟兄。"]', '["猶得吾師繼頌声，百篇相愛寄南荆。","卷开錦水霞光爛，吟入峨嵋雪氣清。","楚外已甘推絕唱，蜀中誰敢共懸衡。","應怜無可同無本，終向风騷作弟兄。"]', '诗', 'shi', '', NULL, '酬西蜀廣濟大師見寄 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f26f8f0-41fd-4768-9f0e-d60d22c3cffb', '江寺春殘寄幕中知己二首 一', '江寺春殘寄幕中知己二首 一', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["誰遣西來負岳雲，自由歸去竟何因。","山龕薜荔應殘雪，江寺玫瑰又度春。","早歲便師無學士，臨年却作有爲人。","何妨夜醮時相憶，伴醉佯狂笑老身。"]', '["誰遣西来負岳云，自由归去竟何因。","山龕薜荔應殘雪，江寺玫瑰又度春。","早歲便師無学士，臨年却作有爲人。","何妨夜醮时相憶，伴醉佯狂笑老身。"]', '诗', 'shi', '', NULL, '江寺春殘寄幕中知己二首 一 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('99401bfe-0dd5-4d61-b9fc-b2dc666ad753', '江寺春殘寄幕中知己二首 二', '江寺春殘寄幕中知己二首 二', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["社蓮慚與幕蓮同，岳寺蕭條儉府雄。","冷淡獨開香火裏，殷妍行列綺羅中。","秋加玉露何傷白，夜醉金缸不那紅。","閑憶遺民此心地，一般無染喻真空。"]', '["社蓮慚與幕蓮同，岳寺蕭條儉府雄。","冷淡独开香火裏，殷妍行列綺羅中。","秋加玉露何傷白，夜醉金缸不那紅。","闲憶遺民此心地，一般無染喻真空。"]', '诗', 'shi', '', NULL, '江寺春殘寄幕中知己二首 二 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('806fc8b2-fb8f-4d66-be20-faab4c1100db', '寄玉泉實仁上人', '寄玉泉實仁上人', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["往歲曾尋聖跡時，樹邊三遶禮吾師。","敢望護法將軍記，且喜焚香弟子知。","後會未期心的的，前峯欲下步遲遲。","今來老劣難行甚，空寂無緣但寄詩。"]', '["往歲曾尋聖跡时，樹邊三遶禮吾師。","敢望護法將軍記，且喜焚香弟子知。","後會未期心的的，前峯欲下步遲遲。","今来老劣难行甚，空寂無緣但寄诗。"]', '诗', 'shi', '', NULL, '寄玉泉實仁上人 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4979a8e7-75d5-4633-99a3-6f38efdc40fa', '荆渚感懷寄僧達禪弟三首 一', '荆渚感懷寄僧達禪弟三首 一', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["電擊流年七十三，齒衰氣沮竟何堪。","誰云有句傳天下，自愧無心寄嶺南。","曉漱氣嫌通市井，晚烹香憶落雲潭。","鄰峯道者應彈指，蘚剝藤纏舊石龕。"]', '["電擊流年七十三，齒衰氣沮竟何堪。","誰云有句傳天下，自愧無心寄嶺南。","晓漱氣嫌通市井，晚烹香憶落云潭。","鄰峯道者應彈指，蘚剝藤纏旧石龕。"]', '诗', 'shi', '', NULL, '荆渚感懷寄僧達禪弟三首 一 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7ad8764d-4748-4f5d-90e3-0784e322f023', '荆渚感懷寄僧達禪弟三首 二', '荆渚感懷寄僧達禪弟三首 二', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["十五年前會虎溪，白蓮齋後便來西。","干戈時變信雖絕，吳楚路長魂不迷。","黃葉喻曾同我悟，碧雲情近與誰攜。","春殘相憶荆江岸，一隻杜鵑頭上啼。"]', '["十五年前會虎溪，白蓮斋後便来西。","干戈时变信雖絕，吳楚路长魂不迷。","黄葉喻曾同我悟，碧云情近與誰携。","春殘相憶荆江岸，一隻杜鵑头上啼。"]', '诗', 'shi', '', NULL, '荆渚感懷寄僧達禪弟三首 二 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e8f9d86-5cb7-437a-b9a7-265a786a46eb', '荆渚感懷寄僧達禪弟三首 三', '荆渚感懷寄僧達禪弟三首 三', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["鶴嶺僧來細話君，依前高尚跡難羣。","自拋南岳三生石，長傍西山數片雲。","丹訪葛洪無舊竈，詩尋靈觀有遺文。","莫將離別爲相隔，心似虛空幾處分。"]', '["鹤嶺僧来細話君，依前高尚跡难羣。","自拋南岳三生石，长傍西山數片云。","丹訪葛洪無旧竈，诗尋靈观有遺文。","莫將離別爲相隔，心似虛空幾处分。"]', '诗', 'shi', '', NULL, '荆渚感懷寄僧達禪弟三首 三 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('400a774f-d199-449b-9279-798e6ed92337', '寄孫魴秀才', '寄孫魴秀才', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["郡樓東面寺牆西，顏子生涯竹屋低。","書案飛颺風落絮，地苔狼藉燕銜泥。","吟窗晚凭春篁密，行徑斜穿夏菜齊。","別後相思頻夢到，二年同此賦閑題。"]', '["郡楼东面寺牆西，顏子生涯竹屋低。","书案飞颺风落絮，地苔狼藉燕銜泥。","吟窗晚凭春篁密，行徑斜穿夏菜齊。","別後相思頻梦到，二年同此賦闲題。"]', '诗', 'shi', '', NULL, '寄孫魴秀才 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c2f93c9b-9745-4b23-8bda-1517094ab72b', '送李評事往宜春', '送李評事往宜春', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["蘭舟西去是通津，名郡賢侯下禮頻。","山遍寺樓看仰岫，臺連城閣上宜春。","鴻心夜過鄉心亂，雪韻朝飛句韻新。","別有官榮身外趣，月江松徑訪禪人。"]', '["蘭舟西去是通津，名郡賢侯下禮頻。","山遍寺楼看仰岫，台連城閣上宜春。","鴻心夜過乡心亂，雪韻朝飞句韻新。","別有官榮身外趣，月江松徑訪禪人。"]', '诗', 'shi', '', NULL, '送李評事往宜春 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e9ce2f2-8bfa-462f-8920-4ab9ad7f89a8', '中春感興', '中春感兴', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["春風日日雨時時，寒力潛從暖勢衰。","一氣不言含有象，萬靈何處謝無私。","詩通物理行堪掇，道合天機坐可窺。","應是正人持造化，盡驅幽細入罏鎚。"]', '["春风日日雨时时，寒力潛從暖勢衰。","一氣不言含有象，万靈何处謝無私。","诗通物理行堪掇，道合天機坐可窺。","應是正人持造化，尽驱幽細入罏鎚。"]', '诗', 'shi', '', NULL, '中春感興 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b4e4d7f-0398-4e4e-859b-618fa08481cb', '早鶯', '早鶯', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["何處經年閟好音，暖風催出囀喬林。","羽毛新刷陶潛菊，喉舌初調叔夜琴。","藏雨並棲紅杏密，避人雙入綠楊深。","曉來枝上千般語，應共桃花說舊心。"]', '["何处經年閟好音，暖风催出囀喬林。","羽毛新刷陶潛菊，喉舌初調叔夜琴。","藏雨並棲紅杏密，避人雙入綠楊深。","晓来枝上千般語，應共桃花说旧心。"]', '诗', 'shi', '', NULL, '早鶯 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9a255c6-6562-489b-9bd2-6f30457faed9', '酬尚顏上人', '酬尚顏上人', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["紫綬蒼髭百歲侵，綠苔芳草遶堦深。","不妨好鳥喧高臥，切忌閑人聒正吟。","魯鼎寂寥休辨口，劫灰銷變莫宣心。","還憐我有冥搜癖，時把新詩過竹尋。"]', '["紫綬蒼髭百歲侵，綠苔芳草遶堦深。","不妨好鸟喧高臥，切忌闲人聒正吟。","魯鼎寂寥休辨口，劫灰銷变莫宣心。","還怜我有冥搜癖，时把新诗過竹尋。"]', '诗', 'shi', '', NULL, '酬尚顏上人 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd976e08-8954-4be2-9dea-e00bedbf29b7', '寄倪署郎中', '寄倪署郎中', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["風雨冥冥春闇移，紅殘綠滿海棠枝。","帝鄉久別江鄉住，椿笋何如櫻笋時。","海內擅名君作賦，林間外學我爲詩。","近聞南國升南省，應笑無機老病師。"]', '["风雨冥冥春闇移，紅殘綠满海棠枝。","帝乡久別江乡住，椿笋何如櫻笋时。","海內擅名君作賦，林间外学我爲诗。","近闻南国升南省，應笑無機老病師。"]', '诗', 'shi', '', NULL, '寄倪署郎中 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c695097-e927-4739-81f5-d5364d905608', '題鄭郎中谷仰山居', '題鄭郎中谷仰山居', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["簷壁層層映水天，半乘岡壠半民田。","王維愛甚難拋畫，支遁憐多不惜錢。","巨石盡含金玉氣，亂峯深鎖棟梁煙。","秦爭漢奪虛勞力，却是巢由得穩眠。"]', '["簷壁層層映水天，半乘岡壠半民田。","王維愛甚难拋畫，支遁怜多不惜錢。","巨石尽含金玉氣，亂峯深鎖棟梁煙。","秦爭漢奪虛勞力，却是巢由得穩眠。"]', '诗', 'shi', '', NULL, '題鄭郎中谷仰山居 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('43840e11-48c5-411c-ac5e-b0ee437e3c21', '湘中寓居春日感懷', '湘中寓居春日感懷', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["江禽野獸兩堪傷，避射驚彈各自忙。","頭角任多無獬豸，羽毛雖衆讓鴛鴦。","落苔紅小櫻桃熟，侵井青纖燕麥長。","吟把離騷憶前事，汨羅春浪撼殘陽。"]', '["江禽野獸兩堪傷，避射驚彈各自忙。","头角任多無獬豸，羽毛雖衆讓鴛鴦。","落苔紅小櫻桃熟，侵井青纖燕麦长。","吟把離騷憶前事，汨羅春浪撼殘陽。"]', '诗', 'shi', '', NULL, '湘中寓居春日感懷 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80b06d39-4ae9-4450-a21d-3c14001091dd', '瀟湘', '瀟湘', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["寒清健碧遠相含，珠媚根源在極南。","流古遰今空作島，逗山衝壁自爲潭。","遷來賈誼愁無限，謫過靈均恨不堪。","畢竟輸他老漁叟，綠蓑青竹釣濃藍。"]', '["寒清健碧远相含，珠媚根源在極南。","流古遰今空作島，逗山衝壁自爲潭。","遷来賈誼愁無限，謫過靈均恨不堪。","畢竟輸他老漁叟，綠蓑青竹釣濃藍。"]', '诗', 'shi', '', NULL, '瀟湘 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('860aeae7-09cc-4d42-b8be-ecef133560d3', '寄友生', '寄友生', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["風騷情味近如何，門底寒流屋裏莎。","曾摘園蔬留我宿，共吟江月看鴻過。","時危苦恨無收拾，道妙深誇有琢磨。","涼夜欹眠應得夢，平生心肺似君多。"]', '["风騷情味近如何，门底寒流屋裏莎。","曾摘园蔬留我宿，共吟江月看鴻過。","时危苦恨無收拾，道妙深誇有琢磨。","涼夜欹眠應得梦，平生心肺似君多。"]', '诗', 'shi', '', NULL, '寄友生 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9394cbf8-1ee7-4817-958b-97ad57239d6a', '酬荅退上人', '酬荅退上人', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["鬚鬢三分白二分，一生蹤跡出人羣。","嵩丘夢憶諸峰雪，衡岳禪依五寺雲。","青衲幾臨高瀑濯，苦吟曾許斷猿聞。","荒村殘臘相逢夜，月滿鴻多楚水濆。"]', '["鬚鬢三分白二分，一生蹤跡出人羣。","嵩丘梦憶諸峰雪，衡岳禪依五寺云。","青衲幾臨高瀑濯，苦吟曾許斷猿闻。","荒村殘臘相逢夜，月满鴻多楚水濆。"]', '诗', 'shi', '', NULL, '酬荅退上人 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6cf026d9-3101-406e-965b-c9f3862712e0', '山中春懷', '山中春懷', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["心魂役役不曾歸，萬象相牽向極微。","所得或憂逢郢刃，凡言皆欲奪天機。","遊深晚谷香充鼻，坐苦春松粉滿衣。","何物不爲狼籍境，桃花和雨更霏霏。"]', '["心魂役役不曾归，万象相牽向極微。","所得或憂逢郢刃，凡言皆欲奪天機。","游深晚谷香充鼻，坐苦春松粉满衣。","何物不爲狼籍境，桃花和雨更霏霏。"]', '诗', 'shi', '', NULL, '山中春懷 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('19e855e5-4949-43d9-bcbd-7247f31e73a3', '寄鄭谷郎中', '寄鄭谷郎中', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["上國誰傳消息過，醉眠醒坐對嵯峨。","身離道士衣裳少，筆荅禪師句偈多。","南岸郡鐘涼度枕，西齋竹露冷霑莎。","還應笑我降心外，惹得詩魔助佛魔。"]', '["上国誰傳消息過，醉眠醒坐对嵯峨。","身離道士衣裳少，笔荅禪師句偈多。","南岸郡鐘涼度枕，西斋竹露冷霑莎。","還應笑我降心外，惹得诗魔助佛魔。"]', '诗', 'shi', '', NULL, '寄鄭谷郎中 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a312852c-7859-4f22-bafe-ff04554d45ba', '寄萍鄉唐稟正字', '寄萍乡唐稟正字', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["新書聲價滿皇都，高臥林中更起無。","春興酒香薰肺腑，夜吟雲氣濕髭鬚。","同登水閣僧皆別，共上漁船鶴亦孤。","長憶前年送行處，洞門殘日照菖蒲。"]', '["新书声價满皇都，高臥林中更起無。","春兴酒香薰肺腑，夜吟云氣濕髭鬚。","同登水閣僧皆別，共上漁船鹤亦孤。","长憶前年送行处，洞门殘日照菖蒲。"]', '诗', 'shi', '', NULL, '寄萍鄉唐稟正字 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e247f7c-b878-4168-96ea-d364fd243edf', '秋夕書懷', '秋夕书懷', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["涼多夜永擁山袍，片石閑欹不覺勞。","蟋蟀遶牀無夢寐，梧桐滿地有蕭騷。","平生樂道心常切，五字逢人價合高。","破落西窗向殘月，露聲如雨滴蓬蒿。"]', '["涼多夜永擁山袍，片石闲欹不覺勞。","蟋蟀遶牀無梦寐，梧桐满地有蕭騷。","平生乐道心常切，五字逢人價合高。","破落西窗向殘月，露声如雨滴蓬蒿。"]', '诗', 'shi', '', NULL, '秋夕書懷 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a0206127-03ce-48da-943d-3bffc19062ce', '亂後經西山寺', '亂後經西山寺', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["松燒寺破是刀兵，谷變陵遷事可驚。","雲裏乍逢新住主，石邊重認舊題名。","閑臨菡萏荒池坐，亂踏鴛鴦破瓦行。","欲伴高僧重結社，此身無計捨前程。"]', '["松燒寺破是刀兵，谷变陵遷事可驚。","云裏乍逢新住主，石邊重認旧題名。","闲臨菡萏荒池坐，亂踏鴛鴦破瓦行。","欲伴高僧重結社，此身無計捨前程。"]', '诗', 'shi', '', NULL, '亂後經西山寺 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e997d2b3-1b23-438e-8b44-be0ac1858921', '題梁賢巽公房', '題梁賢巽公房', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["吳王廟側有高房，簾影南軒日正長。","吹苑野風桃葉碧，壓畦春露菜花黃。","懸燈向後惟冥默，凭案前頭即渺茫。","知有虎溪歸夢切，寺門松折社僧亡。"]', '["吳王廟側有高房，簾影南軒日正长。","吹苑野风桃葉碧，壓畦春露菜花黄。","懸灯向後惟冥默，凭案前头即渺茫。","知有虎溪归梦切，寺门松折社僧亡。"]', '诗', 'shi', '', NULL, '題梁賢巽公房 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('805df3c2-f7b3-4bfe-a0d4-ded719d46c26', '塘上閑作', '塘上闲作', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["閑行閑坐藉莎煙，此興堪思二古賢。","陶靖節居彭澤畔，賀知章在鏡池邊。","鴛鴦著對能飛繡，菡萏成羣不語仙。","形影騰騰夕陽裏，數峰危翠滴漁船。"]', '["闲行闲坐藉莎煙，此兴堪思二古賢。","陶靖節居彭澤畔，賀知章在镜池邊。","鴛鴦著对能飞繡，菡萏成羣不語仙。","形影腾腾夕陽裏，數峰危翠滴漁船。"]', '诗', 'shi', '', NULL, '塘上閑作 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0901d774-7d42-4120-86ea-de20528ed4de', '江上望遠山寄鄭谷郎中', '江上望远山寄鄭谷郎中', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["危碧層層映水天，半垂岡隴下民田。","王維愛甚難拋畫，支遁高多不惜錢。","巨石盡含金玉氣，亂峰閑鎖棟梁煙。","秦爭漢奪空勞力，却是巢由得穩眠。"]', '["危碧層層映水天，半垂岡隴下民田。","王維愛甚难拋畫，支遁高多不惜錢。","巨石尽含金玉氣，亂峰闲鎖棟梁煙。","秦爭漢奪空勞力，却是巢由得穩眠。"]', '诗', 'shi', '', NULL, '江上望遠山寄鄭谷郎中 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e8155a25-b507-4e55-92ac-506392a73bce', '送人自蜀迴南遊', '送人自蜀迴南游', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["錦水東浮情尚鬱，湘波南泛思何長。","蜀魂巴狖悲殘夜，越鳥燕鴻叫夕陽。","煙月幾般爲客路，林泉四絕是吾鄉。","尋幽必有僧相指，宋杜題詩近舊房。"]', '["錦水东浮情尚鬱，湘波南泛思何长。","蜀魂巴狖悲殘夜，越鸟燕鴻叫夕陽。","煙月幾般爲客路，林泉四絕是吾乡。","尋幽必有僧相指，宋杜題诗近旧房。"]', '诗', 'shi', '', NULL, '送人自蜀迴南遊 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b4bc6da1-63ce-4931-84ba-8f6f8072fa3d', '寄无願上人', '寄无願上人', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["六十八去七十歲，與師年鬢不爭多。","誰言生死無消處，還有修行那得何。","開士安能窮好惡，故人堪憶舊經過。","會歸原上焚身後，一陣灰飛也[任他]。"]', '["六十八去七十歲，與師年鬢不爭多。","誰言生死無消处，還有修行那得何。","开士安能窮好惡，故人堪憶旧經過。","會归原上焚身後，一陣灰飞也[任他]。"]', '诗', 'shi', '', NULL, '寄无願上人 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f40f92df-1a70-465c-b207-fcf98cadc0e3', '懷瀟湘即事寄友人', '懷瀟湘即事寄友人', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["浸野淫空澹蕩和，十年鄰住聽漁歌。","城臨遠櫂浮煙泊，寺近閑人泛月過。","岸引綠蕪春雨細，汀連斑竹晚風多。","可憐千古懷沙處，還有魚龍弄白波。"]', '["浸野淫空澹蕩和，十年鄰住听漁歌。","城臨远櫂浮煙泊，寺近闲人泛月過。","岸引綠蕪春雨細，汀連斑竹晚风多。","可怜千古懷沙处，還有鱼龙弄白波。"]', '诗', 'shi', '', NULL, '懷瀟湘即事寄友人 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5918924b-3b3b-4a58-a8b4-d2a106f59290', '謝橘洲人寄橘', '謝橘洲人寄橘', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["洞庭栽種似瀟湘，綠遶人家帶夕陽。","霜裛露蒸千樹熟，浪圍風撼一洲香。","洪崖遣後名何遠，陸績懷來事更長。","藏貯待供賓客好，石榴宜稱映舟光。"]', '["洞庭栽種似瀟湘，綠遶人家带夕陽。","霜裛露蒸千樹熟，浪圍风撼一洲香。","洪崖遣後名何远，陸績懷来事更长。","藏貯待供賓客好，石榴宜稱映舟光。"]', '诗', 'shi', '', NULL, '謝橘洲人寄橘 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f5128fc6-ddea-4359-be1f-134f9ed9151d', '自貽', '自貽', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["心中身外更何猜，坐石看雲養聖胎。","名在好詩誰逐去，跡依閑處自歸來。","時添瀑布新缾水，旋換旃檀舊印灰。","晴出寺門驚往事，古松千尺半蒼苔。"]', '["心中身外更何猜，坐石看云養聖胎。","名在好诗誰逐去，跡依闲处自归来。","时添瀑布新缾水，旋換旃檀旧印灰。","晴出寺门驚往事，古松千尺半蒼苔。"]', '诗', 'shi', '', NULL, '自貽 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab60a4e1-93e8-453e-9055-f5a9abe51740', '寄益上人', '寄益上人', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["長想尋君道路遙，亂山霜後火新燒。","近聞移住鄰衡岳，幾度題詩上石橋。","古木傳聲連峭壁，一燈懸影過中宵。","風騷味薄誰相愛，攲枕常多夢鮑昭。"]', '["长想尋君道路遙，亂山霜後火新燒。","近闻移住鄰衡岳，幾度題诗上石橋。","古木傳声連峭壁，一灯懸影過中宵。","风騷味薄誰相愛，攲枕常多梦鲍昭。"]', '诗', 'shi', '', NULL, '寄益上人 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d5a9149-b703-4f7d-8467-a2f1b61e2ccc', '行次宜春寄湘西諸友', '行次宜春寄湘西諸友', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["幸無名利路相迷，雙履尋山上柏梯。","衣鉢祖辭梅嶺外，香燈社別橘洲西。","雲中石壁青[侵]漢，樹下苔錢綠遶溪。","我愛遠遊君愛住，此心他約與誰攜。"]', '["幸無名利路相迷，雙履尋山上柏梯。","衣鉢祖辞梅嶺外，香灯社別橘洲西。","云中石壁青[侵]漢，樹下苔錢綠遶溪。","我愛远游君愛住，此心他約與誰携。"]', '诗', 'shi', '', NULL, '行次宜春寄湘西諸友 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c49308e2-1a42-4536-8c4a-30189e7a85ec', '送略禪者歸南岳', '送略禪者归南岳', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["林下鐘殘又拂衣，錫聲還獨向南飛。","千峰[冷]截冥鴻處，一徑險通禪客歸。","青石上行苔片片，古杉邊宿雨霏霏。","勞生有願應回首，忍著無心與物違。"]', '["林下鐘殘又拂衣，錫声還独向南飞。","千峰[冷]截冥鴻处，一徑險通禪客归。","青石上行苔片片，古杉邊宿雨霏霏。","勞生有願應回首，忍著無心與物違。"]', '诗', 'shi', '', NULL, '送略禪者歸南岳 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff9b89c8-455b-445a-b3e3-792d1276e899', '詠懷寄知己', '詠懷寄知己', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["已得浮生到老閑，且將新句擬玄關。","自知清興來無盡，誰道淳風去不還。","三百正聲傳世後，五千真理在人間。","此心終待相逢說，時復登樓看暮山。"]', '["已得浮生到老闲，且將新句擬玄关。","自知清兴来無尽，誰道淳风去不還。","三百正声傳世後，五千真理在人间。","此心終待相逢说，时复登楼看暮山。"]', '诗', 'shi', '', NULL, '詠懷寄知己 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a72a217-0b56-475e-85b5-3c2dab844dde', '寄吳拾遺', '寄吳拾遺', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["新竹將誰搉重輕，皎然評裏見權衡。","非無苦到難搜處，合有清垂不朽名。","疎雨晚衝蓮葉響，亂蟬涼抱檜梢鳴。","野橋閑背殘陽立，翻憶蘇卿送子卿。"]', '["新竹將誰搉重轻，皎然評裏见權衡。","非無苦到难搜处，合有清垂不朽名。","疎雨晚衝蓮葉响，亂蟬涼抱檜梢鳴。","野橋闲背殘陽立，翻憶蘇卿送子卿。"]', '诗', 'shi', '', NULL, '寄吳拾遺 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c4f9662-7fe7-4c15-9ce6-c1a39528e475', '春晴感興', '春晴感兴', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["連旬陰翳曉來晴，水滿圓塘照日明。","岸草短長邊過客，江花紅白裏啼鶯。","野無征戰時堪望，山有樓臺煖好行。","桑柘依依禾黍綠，可憐歸去是張衡。"]', '["連旬陰翳晓来晴，水满圓塘照日明。","岸草短长邊過客，江花紅白裏啼鶯。","野無征戰时堪望，山有楼台煖好行。","桑柘依依禾黍綠，可怜归去是張衡。"]', '诗', 'shi', '', NULL, '春晴感興 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('89b6b63f-7899-416d-9c27-e2f8e0848bb8', '謝道友拄杖', '謝道友拄杖', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["翦自南巖瀑布邊，寒光七尺乳珠連。","持來未入塵埃路，乞與應憐老病年。","欹影夜歸青石澗，卓痕秋過綠苔錢。","他時攜上嵩峰頂，把倚長松看洛川。"]', '["翦自南巖瀑布邊，寒光七尺乳珠連。","持来未入塵埃路，乞與應怜老病年。","欹影夜归青石澗，卓痕秋過綠苔錢。","他时携上嵩峰頂，把倚长松看洛川。"]', '诗', 'shi', '', NULL, '謝道友拄杖 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e806ac8-3084-46ee-8530-630623ad4d0c', '東林寄別修睦上人', '东林寄別修睦上人', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["行心乞得見秋風，雙履難留去住蹤。","紅葉正多離社客，白雲無限向嵩峰。","囊中自欠詩千首，身外誰知事幾重。","此別不能爲後約，年華相似逼衰容。"]', '["行心乞得见秋风，雙履难留去住蹤。","紅葉正多離社客，白云無限向嵩峰。","囊中自欠诗千首，身外誰知事幾重。","此別不能爲後約，年华相似逼衰容。"]', '诗', 'shi', '', NULL, '東林寄別修睦上人 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50cd4ba1-47b5-476b-9b7c-1b3bba01cad6', '夏日原西避暑寄吟友', '夏日原西避暑寄吟友', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["熱煙疎竹古原西，日日乘涼此杖藜。","閑處雨聲隨霹靂，旱田人望隔虹霓。","蟬依獨樹乾吟苦，鳥憶平川渴過齊。","別有相招好泉石，瑞花瑤草盡堪攜。"]', '["熱煙疎竹古原西，日日乘涼此杖藜。","闲处雨声隨霹靂，旱田人望隔虹霓。","蟬依独樹乾吟苦，鸟憶平川渴過齊。","別有相招好泉石，瑞花瑤草尽堪携。"]', '诗', 'shi', '', NULL, '夏日原西避暑寄吟友 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('78c0e5b9-fe24-41b2-9e32-b5664a0d12e2', '懷匡阜', '懷匡阜', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["荆州連歲滯遊方，拄杖塵封六尺光。","洗面有香思石溜，冥心無撓憶山牀。","閑機但媿時機速，靜論須慙世論長。","昨夜分明夢歸去，薜蘿幽逕遶禪房。"]', '["荆州連歲滯游方，拄杖塵封六尺光。","洗面有香思石溜，冥心無撓憶山牀。","闲機但媿时機速，静論須慙世論长。","昨夜分明梦归去，薜蘿幽逕遶禪房。"]', '诗', 'shi', '', NULL, '懷匡阜 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b46a564e-934c-4423-9127-c214763a059c', '靜坐', '静坐', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["繩牀欹坐任崩頹，雙眼醒醒閉復開。","日月更無閑裏過，風騷時有靜中來。","天真自得生難捨，世幻誰驚死不迴。","何處堪投此蹤跡，水邊晴去上高臺。"]', '["繩牀欹坐任崩頹，雙眼醒醒閉复开。","日月更無闲裏過，风騷时有静中来。","天真自得生难捨，世幻誰驚死不迴。","何处堪投此蹤跡，水邊晴去上高台。"]', '诗', 'shi', '', NULL, '靜坐 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('422fca69-2b55-4658-a4ef-6bd53f89d2d1', '寄湘中諸友', '寄湘中諸友', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["碧雲諸友盡黃眸，石點花飛更說無。","嵐翠濕衣松接院，芙蓉薰面寺臨湖。","沃洲高臥心何僻，匡社長禪興亦孤。","爭似楚王文物國，金鑣紫綬讓前途。"]', '["碧云諸友尽黄眸，石点花飞更说無。","嵐翠濕衣松接院，芙蓉薰面寺臨湖。","沃洲高臥心何僻，匡社长禪兴亦孤。","爭似楚王文物国，金鑣紫綬讓前途。"]', '诗', 'shi', '', NULL, '寄湘中諸友 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7a78089b-83ca-4aef-ba3f-db272023bc30', '荅无願上人書', '荅无願上人书', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["鄭生驅蹇峴山迴，傳得安公好信來。","千里阻修俱老骨，八行重疊慰寒灰。","春殘桃李猶開戶，雪滿松杉始上臺。","必有南遊山水興，漢江平穩好浮杯。"]', '["鄭生驱蹇峴山迴，傳得安公好信来。","千里阻修俱老骨，八行重叠慰寒灰。","春殘桃李猶开戶，雪满松杉始上台。","必有南游山水兴，漢江平穩好浮杯。"]', '诗', 'shi', '', NULL, '荅无願上人書 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('00752ffe-f56c-4cb1-9370-0488dd1736e0', '送胤公歸闕', '送胤公归闕', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["西朝歸去見高情，應戀香燈近聖明。","關令莫疑非馬辯，道安還跨赤驢行。","充齋野店蔬無味，灑笠平原雪有聲。","忍惜文章便閑得，看他趨競取時名。"]', '["西朝归去见高情，應戀香灯近聖明。","关令莫疑非马辯，道安還跨赤驢行。","充斋野店蔬無味，灑笠平原雪有声。","忍惜文章便闲得，看他趨競取时名。"]', '诗', 'shi', '', NULL, '送胤公歸闕 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c0f6275-b20c-4e76-9a42-76124ee2be99', '感時', '感时', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["忽忽枕前蝴蝶夢，悠悠覺後利名塵。","無窮今日明朝事，有限生來死去人。","終與狐狸爲窟穴，謾師龜鶴養精神。","可憐顏子能消息，虛室坐忘心最真。"]', '["忽忽枕前蝴蝶梦，悠悠覺後利名塵。","無窮今日明朝事，有限生来死去人。","終與狐狸爲窟穴，謾師龟鹤養精神。","可怜顏子能消息，虛室坐忘心最真。"]', '诗', 'shi', '', NULL, '感時 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc0442bb-141a-4a4d-b9db-c6f43e689ae6', '湖上逸人', '湖上逸人', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["澹蕩光中翡翠飛，田田初出柳絲絲。","吟沿綠島時逢鶴，醉泛清波或見龜。","七澤釣師應識我，中原逐鹿不知誰。","秋風水寺僧相近，一徑蘆花到竹籬。"]', '["澹蕩光中翡翠飞，田田初出柳絲絲。","吟沿綠島时逢鹤，醉泛清波或见龟。","七澤釣師應識我，中原逐鹿不知誰。","秋风水寺僧相近，一徑蘆花到竹籬。"]', '诗', 'shi', '', NULL, '湖上逸人 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f478b21-d349-4d73-b9f1-1b95f0c00dca', '懷巴陵', '懷巴陵', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["垂白堪思大亂前，薄遊曾駐洞庭邊。","尋僧古寺沿沙岸，倚杖殘陽落水天。","蘭蘂蔫菸騷客廟，煙波晴闊釣師船。","此時欲買君山住，嬾就商人乞箇錢。"]', '["垂白堪思大亂前，薄游曾駐洞庭邊。","尋僧古寺沿沙岸，倚杖殘陽落水天。","蘭蘂蔫菸騷客廟，煙波晴闊釣師船。","此时欲買君山住，嬾就商人乞箇錢。"]', '诗', 'shi', '', NULL, '懷巴陵 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0897db5-c1ed-4ddd-b043-1e508d81712e', '渚宮謝楊秀才自嵩山相訪', '渚宮謝楊秀才自嵩山相訪', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["嵩峰有客遠相尋，塵滿麻衣袖苦吟。","花盡草長方閉戶，道孤身老正傷心。","紅堆落日雲千仞，碧撼涼風竹一林。","惆悵雅聲消歇去，喜君聊此暫披襟。"]', '["嵩峰有客远相尋，塵满麻衣袖苦吟。","花尽草长方閉戶，道孤身老正傷心。","紅堆落日云千仞，碧撼涼风竹一林。","惆悵雅声消歇去，喜君聊此暫披襟。"]', '诗', 'shi', '', NULL, '渚宮謝楊秀才自嵩山相訪 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('28c497eb-4a9e-46ad-9420-d1cd8e72a57e', '荆門寄沈彬', '荆门寄沈彬', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["罷趨明聖嬾從知，鶴氅褵褷遂性披。","道有靜君堪托迹，詩無賢子擬傳誰。","松聲白日邊行止，日影紅霞裏夢思。","珍重兩篇千里達，去年江上雪飛時。"]', '["罷趨明聖嬾從知，鹤氅褵褷遂性披。","道有静君堪托迹，诗無賢子擬傳誰。","松声白日邊行止，日影紅霞裏梦思。","珍重兩篇千里達，去年江上雪飞时。"]', '诗', 'shi', '', NULL, '荆門寄沈彬 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c7179df-f20d-4bfe-ae79-218891f3dd0b', '讀陰符經', '读陰符經', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["遶窗風竹骨輕安，閑借陰符仰臥看。","絕利一源真有謂，空勞萬卷是無端。","清虛可保昇雲易，嗜慾終知入聖難。","三要洞開何用閉，高臺時去凭欄干。"]', '["遶窗风竹骨轻安，闲借陰符仰臥看。","絕利一源真有謂，空勞万卷是無端。","清虛可保昇云易，嗜慾終知入聖难。","三要洞开何用閉，高台时去凭欄干。"]', '诗', 'shi', '', NULL, '讀陰符經 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0cec80ce-9fd4-4421-a6d2-15b9a4f6a102', '寄吳國知舊', '寄吳国知旧', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["淮甸當年憶旅遊，衲衣椶笠外何求。","城中古巷尋詩客，橋上殘陽背酒樓。","晴色水雲天合影，晚聲名利市爭頭。","可憐王化融融裏，惆悵無僧似惠休。"]', '["淮甸當年憶旅游，衲衣椶笠外何求。","城中古巷尋诗客，橋上殘陽背酒楼。","晴色水云天合影，晚声名利市爭头。","可怜王化融融裏，惆悵無僧似惠休。"]', '诗', 'shi', '', NULL, '寄吳國知舊 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c29e843-3fe1-4dd8-b105-ab9db3d94806', '移居', '移居', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["上台言任養疎愚，乞與西城水滿湖。","吹榻好風終日有，趂涼閑客片時無。","檀欒翠擁清蟬在，菡萏紅殘白鳥孤。","欲問存思搜抉妙，幾聯詩許敵三都。"]', '["上台言任養疎愚，乞與西城水满湖。","吹榻好风終日有，趂涼闲客片时無。","檀欒翠擁清蟬在，菡萏紅殘白鸟孤。","欲问存思搜抉妙，幾聯诗許敵三都。"]', '诗', 'shi', '', NULL, '移居 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('57185aa8-e155-45d7-8869-e5c9c758202d', '喜彬上人見訪', '喜彬上人见訪', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["高吟欲繼沃州師，千里相尋問課虛。","殘臘江山行盡處，滿衣風雪到閑居。","攜來律韻清何甚，趣入幽微旨不疎。","莫惜天機細搥琢，他時終可擬芙蕖。"]', '["高吟欲繼沃州師，千里相尋问課虛。","殘臘江山行尽处，满衣风雪到闲居。","携来律韻清何甚，趣入幽微旨不疎。","莫惜天機細搥琢，他时終可擬芙蕖。"]', '诗', 'shi', '', NULL, '喜彬上人見訪 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c200b097-3c92-4d31-bc8f-0f6e9ba5b4d6', '荆州新秋寺居寫懷詩五首上南平王 一', '荆州新秋寺居寫懷诗五首上南平王 一', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["竹如翡翠侵簾影，苔學琉璃布地紋。","高臥更無如此樂，遠遊何必愛他雲。","閑聽謝朓吟爲政，靜看蕭何坐致君。","只恐老身衰朽速，他年不得頌鴻勳。"]', '["竹如翡翠侵簾影，苔学琉璃布地紋。","高臥更無如此乐，远游何必愛他云。","闲听謝朓吟爲政，静看蕭何坐致君。","只恐老身衰朽速，他年不得頌鴻勳。"]', '诗', 'shi', '', NULL, '荆州新秋寺居寫懷詩五首上南平王 一 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0634b87b-4642-4eb5-b515-d20343955284', '荆州新秋寺居寫懷詩五首上南平王 二', '荆州新秋寺居寫懷诗五首上南平王 二', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["井梧黃落暮蟬清，久駐金臺但暗驚。","事佛未憐諸弟子，談空爭動上公卿。","合歸鳥外藏幽跡，敢向人前認好名。","滿印白檀燈一醆，可能酬謝得聰明。"]', '["井梧黄落暮蟬清，久駐金台但暗驚。","事佛未怜諸弟子，談空爭动上公卿。","合归鸟外藏幽跡，敢向人前認好名。","满印白檀灯一醆，可能酬謝得聰明。"]', '诗', 'shi', '', NULL, '荆州新秋寺居寫懷詩五首上南平王 二 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cea97cf1-bab7-4002-b648-ce7b36e5eaba', '荆州新秋寺居寫懷詩五首上南平王 三', '荆州新秋寺居寫懷诗五首上南平王 三', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["金湯裏面境何求，寶殿東邊院最幽。","栽種已添新竹影，畫圖兼列遠山秋。","形容豈合親公子，章句爭堪狎士流。","虛負岷峨老僧約，年年雪水下汀洲。"]', '["金湯裏面境何求，寶殿东邊院最幽。","栽種已添新竹影，畫圖兼列远山秋。","形容豈合親公子，章句爭堪狎士流。","虛負岷峨老僧約，年年雪水下汀洲。"]', '诗', 'shi', '', NULL, '荆州新秋寺居寫懷詩五首上南平王 三 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ebaa588-df7d-43c9-9473-34a544be9b7c', '荆州新秋寺居寫懷詩五首上南平王 四', '荆州新秋寺居寫懷诗五首上南平王 四', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["漢江西岸蜀江東，六稔安禪教化中。","託跡幸將王粲別，歸心寧與子山同。","尊罍豈識曹參酒，賓客還親宋玉風。","又見去年三五夕，一輪寒魄破煙空。"]', '["漢江西岸蜀江东，六稔安禪教化中。","託跡幸將王粲別，归心寧與子山同。","尊罍豈識曹參酒，賓客還親宋玉风。","又见去年三五夕，一輪寒魄破煙空。"]', '诗', 'shi', '', NULL, '荆州新秋寺居寫懷詩五首上南平王 四 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('02671a74-c809-4b0d-bda5-9c0c13a0cbc7', '荆州新秋寺居寫懷詩五首上南平王 五', '荆州新秋寺居寫懷诗五首上南平王 五', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["石龕閑鎖舊居峰，何事膺門歲月重。","五七詩中叨見遇，三千客外許疎慵。","迎涼蟋蟀喧閑思，積雨莓苔沒屐蹤。","會待英雄啓金口，却教擔錫入雲松。"]', '["石龕闲鎖旧居峰，何事膺门歲月重。","五七诗中叨见遇，三千客外許疎慵。","迎涼蟋蟀喧闲思，積雨莓苔沒屐蹤。","會待英雄啓金口，却教擔錫入云松。"]', '诗', 'shi', '', NULL, '荆州新秋寺居寫懷詩五首上南平王 五 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ee9828b-0fac-4fad-8102-580d2f6b32ce', '送李秀才歸湘中', '送李秀才归湘中', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["詞客攜文訪病夫，因吟送別憶湘湖。","寒消浦溆催鴻鴈，暖入溪山養鷓鴣。","僧向月中尋岳麓，雲從城上去蒼梧。","君歸爲問峰前寺，舊住僧房鎖在無。"]', '["词客携文訪病夫，因吟送別憶湘湖。","寒消浦溆催鴻鴈，暖入溪山養鷓鴣。","僧向月中尋岳麓，云從城上去蒼梧。","君归爲问峰前寺，旧住僧房鎖在無。"]', '诗', 'shi', '', NULL, '送李秀才歸湘中 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('06bc7707-ca57-457a-a9d9-4ae5e76d1e27', '寄吳國西供奉', '寄吳国西供奉', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["別來相憶夢多迷，君住東朝我楚西。","瑤闕合陪龍象位，春山休記鷓鴣啼。","承恩位與千官別，應制才將十子齊。","幾笑遠公慵送客，慇懃只到寺前溪。"]', '["別来相憶梦多迷，君住东朝我楚西。","瑤闕合陪龙象位，春山休記鷓鴣啼。","承恩位與千官別，應制才將十子齊。","幾笑远公慵送客，慇懃只到寺前溪。"]', '诗', 'shi', '', NULL, '寄吳國西供奉 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c9426817-cbbc-4a85-b69e-8cb396095c43', '謝人惠端溪硯', '謝人惠端溪硯', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["端人鑿斷碧溪潯，善價爭教惜萬金。","礱琢已曾經敏手，研磨終見透堅心。","安排得主難移動，含貯隨時任淺深。","保重更求裝鈿匣，閑將濡染寄知音。"]', '["端人鑿斷碧溪潯，善價爭教惜万金。","礱琢已曾經敏手，研磨終见透堅心。","安排得主难移动，含貯隨时任淺深。","保重更求裝鈿匣，闲將濡染寄知音。"]', '诗', 'shi', '', NULL, '謝人惠端溪硯 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed98061e-db22-4793-80dc-2f01955f9e9a', '送吳先輩赴京', '送吳先輩赴京', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["煙霄已遂明經第，江漢重來問苦吟。","託興偶憑風月遠，忘機終在寂寥深。","千篇未聽常徒口，一字須防作者心。","此日與君聊話別，老身難約更相尋。"]', '["煙霄已遂明經第，江漢重来问苦吟。","託兴偶憑风月远，忘機終在寂寥深。","千篇未听常徒口，一字須防作者心。","此日與君聊話別，老身难約更相尋。"]', '诗', 'shi', '', NULL, '送吳先輩赴京 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ceeb434-dc8e-4b20-ae8b-6a151e4f762e', '和西蜀可準大師遠寄之什', '和西蜀可準大師远寄之什', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["莫知何路去追攀，空想人間出世間。","杜口已同居士室，傳心休問祖師山。","禪中不住方爲定，說處無生始是閑。","珍重希音遠相寄，亂峰西望疊孱顏。"]', '["莫知何路去追攀，空想人间出世间。","杜口已同居士室，傳心休问祖師山。","禪中不住方爲定，说处無生始是闲。","珍重希音远相寄，亂峰西望叠孱顏。"]', '诗', 'shi', '', NULL, '和西蜀可準大師遠寄之什 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aa96314f-39bf-4ecc-8319-cf8aa39fceb7', '荆門暮冬與節公話別', '荆门暮冬與節公話別', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["漳河湘岸柳關頭，離別相逢四十秋。","我憶黃梅夢南國，君懷明主去東周。","幾程霜雪經殘臘，何處封疆過舊遊。","好及春風承帝澤，莫忘衰朽臥林丘。"]', '["漳河湘岸柳关头，離別相逢四十秋。","我憶黄梅梦南国，君懷明主去东周。","幾程霜雪經殘臘，何处封疆過旧游。","好及春风承帝澤，莫忘衰朽臥林丘。"]', '诗', 'shi', '', NULL, '荆門暮冬與節公話別 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c9e99678-f359-4705-a24e-76d33876b05c', '賀孫支使郎中遷居', '賀孫支使郎中遷居', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["別認公侯禮上才，築金何啻舊燕臺。","地連東閣橫頭買，門對西園正面開。","不隔紅塵趨棨戟，只拖珠履赴尊罍。","應逢明月清霜夜，閑領笙歌宴此來。"]', '["別認公侯禮上才，築金何啻旧燕台。","地連东閣橫头買，门对西园正面开。","不隔紅塵趨棨戟，只拖珠履赴尊罍。","應逢明月清霜夜，闲領笙歌宴此来。"]', '诗', 'shi', '', NULL, '賀孫支使郎中遷居 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0942ddd7-e853-4d06-90a9-d4b6d7d0a753', '庭際新移松竹', '庭際新移松竹', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["三莖瘦竹兩株松，瑟瑟翛翛韻且同。","抱節乍離新澗雪，盤根遠別舊林風。","歲寒相倚無塵地，蔭影分明有月中。","更待陽和信催促，碧梢青杪看凌空。"]', '["三莖瘦竹兩株松，瑟瑟翛翛韻且同。","抱節乍離新澗雪，盤根远別旧林风。","歲寒相倚無塵地，蔭影分明有月中。","更待陽和信催促，碧梢青杪看凌空。"]', '诗', 'shi', '', NULL, '庭際新移松竹 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a5437149-3579-42fe-b4ef-7073774c942b', '荆門寄題禪月大師影堂', '荆门寄題禪月大師影堂', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["澤國聞師泥日後，蜀王全禮葬餘灰。","白蓮塔向清泉鎖，禪月堂臨錦水開。","西岳千篇傳古律，南宗一句印靈臺。","不堪隻履還西去，葱嶺如今無使迴。"]', '["澤国闻師泥日後，蜀王全禮葬餘灰。","白蓮塔向清泉鎖，禪月堂臨錦水开。","西岳千篇傳古律，南宗一句印靈台。","不堪隻履還西去，葱嶺如今無使迴。"]', '诗', 'shi', '', NULL, '荆門寄題禪月大師影堂 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e28aa6b6-1d1e-4c32-84c5-01a7ce57690e', '賀雪', '賀雪', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["上清凝結下乾坤，爲瑞爲祥表致君。","日月影從光外過，山河形向靜中分。","歌揚郢路誰同聽，聲灑梁園客共聞。","堪想畫堂簾卷次，輕隨舞袖正紛紛。"]', '["上清凝結下乾坤，爲瑞爲祥表致君。","日月影從光外過，山河形向静中分。","歌揚郢路誰同听，声灑梁园客共闻。","堪想畫堂簾卷次，轻隨舞袖正紛紛。"]', '诗', 'shi', '', NULL, '賀雪 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('47b20531-9fb9-43cf-a7c4-35ca1cfa60e2', '荆州寄貫微上人', '荆州寄貫微上人', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["舊齋休憶對松關，各在王侯顧遇間。","命服已霑天渥澤，衲衣猶擁祖斕斑。","相思莫救燒心火，留滯難移壓腦山。","得失兩途俱不是，笑他高臥碧孱顏。"]', '["旧斋休憶对松关，各在王侯顧遇间。","命服已霑天渥澤，衲衣猶擁祖斕斑。","相思莫救燒心火，留滯难移壓腦山。","得失兩途俱不是，笑他高臥碧孱顏。"]', '诗', 'shi', '', NULL, '荆州寄貫微上人 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8481a319-3e97-417e-b80c-80ef3c3be2d6', '送休師歸長沙寧覲', '送休師归长沙寧覲', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["高堂親老本師存，多難長懸兩處魂。","已說戰塵消漢口，便隨征櫂別荆門。","晴吟野闊無耕地，晚宿灣深有釣村。","他日更思衰老否，七年相伴琢詩言。"]', '["高堂親老本師存，多难长懸兩处魂。","已说戰塵消漢口，便隨征櫂別荆门。","晴吟野闊無耕地，晚宿灣深有釣村。","他日更思衰老否，七年相伴琢诗言。"]', '诗', 'shi', '', NULL, '送休師歸長沙寧覲 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('09b794d3-9891-42ce-963a-6956af4a4974', '江上夏日', '江上夏日', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["無處清陰似剡溪，火雲奇崛倚空齊。","千山冷疊湖光外，一扇涼搖楚色西。","碧樹影疎風易斷，綠蕪平遠日難低。","故園舊寺臨湘水，斑竹煙深越鳥啼。"]', '["無处清陰似剡溪，火云奇崛倚空齊。","千山冷叠湖光外，一扇涼搖楚色西。","碧樹影疎风易斷，綠蕪平远日难低。","故园旧寺臨湘水，斑竹煙深越鸟啼。"]', '诗', 'shi', '', NULL, '江上夏日 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0be9ef35-add8-4d77-b340-74a6c1434f42', '渚宮春日因懷有作', '渚宮春日因懷有作', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["舊業樹連湘樹遠，家山雲與嶽雲平。","僧來已說無耕釣，鴈去那知有弟兄。","客思莫牽蝴蝶夢，鄉心自憶鷓鴣聲。","沙頭南望堪腸斷，誰把歸舟載我行。"]', '["旧業樹連湘樹远，家山云與嶽云平。","僧来已说無耕釣，鴈去那知有弟兄。","客思莫牽蝴蝶梦，乡心自憶鷓鴣声。","沙头南望堪腸斷，誰把归舟載我行。"]', '诗', 'shi', '', NULL, '渚宮春日因懷有作 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee1819e9-bcc9-4e19-91eb-a7459e2d9ab6', '松化爲石', '松化爲石', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["盤根幾聳翠崖前，却偃凌雲化至堅。","乍結精華齊永劫，不隨凋變已千年。","逢賢必用鐫辭立，遇聖終將刻印傳。","肯似荆山鑿餘者，蘚封頑滯臥嵐煙。"]', '["盤根幾聳翠崖前，却偃凌云化至堅。","乍結精华齊永劫，不隨凋变已千年。","逢賢必用鐫辞立，遇聖終將刻印傳。","肯似荆山鑿餘者，蘚封頑滯臥嵐煙。"]', '诗', 'shi', '', NULL, '松化爲石 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9359c006-efa4-4fe7-b5d3-8fca624a8ae1', '寄澧陽吳使君', '寄澧陽吳使君', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["南客西來話使君，涔陽風雨變行春。","四鄰耕釣趨仁政，千里煙花壓路塵。","去獸未勝除狡吏，還珠爭似復逋民。","紅蘭浦暖攜才子，爛醉連題賦白蘋。"]', '["南客西来話使君，涔陽风雨变行春。","四鄰耕釣趨仁政，千里煙花壓路塵。","去獸未勝除狡吏，還珠爭似复逋民。","紅蘭浦暖携才子，爛醉連題賦白蘋。"]', '诗', 'shi', '', NULL, '寄澧陽吳使君 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aedb4818-0a73-498a-bc4c-2f2819f92180', '湘江送客', '湘江送客', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["湘江秋色湛如冰，楚客離懷暮不勝。","千里碧雲聞塞鴈，幾程青草見巴陵。","寒濤響疊晨征樐，岸葦叢明夜泊燈。","鸚鵡洲邊若回首，爲思前事一捫膺。"]', '["湘江秋色湛如冰，楚客離懷暮不勝。","千里碧云闻塞鴈，幾程青草见巴陵。","寒濤响叠晨征樐，岸葦叢明夜泊灯。","鸚鵡洲邊若回首，爲思前事一捫膺。"]', '诗', 'shi', '', NULL, '湘江送客 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6bc4c6a4-b467-4081-a690-5506b0e4ef86', '暮遊岳麓寺', '暮游岳麓寺', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["寺樓高出碧崖稜，城裏誰知在上層。","初雪灑來喬木暝，遠禽飛過大江澄。","閑消不睡憐長夜，靜照無言謝一燈。","迴首何邊是空地，四村桑麥遍丘陵。"]', '["寺楼高出碧崖稜，城裏誰知在上層。","初雪灑来喬木暝，远禽飞過大江澄。","闲消不睡怜长夜，静照無言謝一灯。","迴首何邊是空地，四村桑麦遍丘陵。"]', '诗', 'shi', '', NULL, '暮遊岳麓寺 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('786007f1-0304-4231-92c6-205172c3c6e9', '林下留別道友', '林下留別道友', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["住亦無依去是閑，何心終戀此林間。","片雲孤鶴東西路，四海九州多少山。","靜坐趁涼移樹影，興隨題處著苔斑。","秋來洗浣行衣了，還爾鄰僧舊竹關。"]', '["住亦無依去是闲，何心終戀此林间。","片云孤鹤东西路，四海九州多少山。","静坐趁涼移樹影，兴隨題处著苔斑。","秋来洗浣行衣了，還爾鄰僧旧竹关。"]', '诗', 'shi', '', NULL, '林下留別道友 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2989cae6-17f2-4307-b616-d08e8645325c', '道林寺居寄岳麓禪師二首 一', '道林寺居寄岳麓禪師二首 一', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["門前石路徹中峰，樹影泉聲在半空。","尋去未應勞上下，往來殊已倦西東。","髭根盡白孤雲並，心跡全忘片月同。","長憶高窗夏天裏，古松青檜午時風。"]', '["门前石路徹中峰，樹影泉声在半空。","尋去未應勞上下，往来殊已倦西东。","髭根尽白孤云並，心跡全忘片月同。","长憶高窗夏天裏，古松青檜午时风。"]', '诗', 'shi', '', NULL, '道林寺居寄岳麓禪師二首 一 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f85ba725-3ce0-4d6c-be80-8870ff1300f1', '道林寺居寄岳麓禪師二首 二', '道林寺居寄岳麓禪師二首 二', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["山袍不稱下紅塵，各是閑居島外身。","兩處煙霞門寂寂，一般苔蘚石磷磷。","禪關悟後寧疑物，詩格玄來不傍人。","月照經行更誰見，露華松粉點衣巾。"]', '["山袍不稱下紅塵，各是闲居島外身。","兩处煙霞门寂寂，一般苔蘚石磷磷。","禪关悟後寧疑物，诗格玄来不傍人。","月照經行更誰见，露华松粉点衣巾。"]', '诗', 'shi', '', NULL, '道林寺居寄岳麓禪師二首 二 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb5a8a7b-3a52-49f5-9668-d1b23be22207', '亂後江西過孫魴舊居因寄', '亂後江西過孫魴旧居因寄', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["舊遊重到倍悲涼，吟憶同人倚寺牆。","何處暮蟬喧逆旅，此中山鳥噪垂楊。","寰區有主權兵器，風月無人掌桂香。","欲寄此心空北望，塞鴻天末失歸行。"]', '["旧游重到倍悲涼，吟憶同人倚寺牆。","何处暮蟬喧逆旅，此中山鸟噪垂楊。","寰區有主權兵器，风月無人掌桂香。","欲寄此心空北望，塞鴻天末失归行。"]', '诗', 'shi', '', NULL, '亂後江西過孫魴舊居因寄 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c185b257-7c7a-4910-a29c-368417fb5345', '宜春江上寄仰山長老二首 一', '宜春江上寄仰山长老二首 一', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["水隔孤城城隔山，水邊時望憶師閑。","清泉白日中峰上，落日半空栖鳥還。","雲影觸衣分朵朵，雨聲吹磬散潺潺。","傳心莫學羅浮去，後輩思量待扣關。"]', '["水隔孤城城隔山，水邊时望憶師闲。","清泉白日中峰上，落日半空栖鸟還。","云影觸衣分朵朵，雨声吹磬散潺潺。","傳心莫学羅浮去，後輩思量待扣关。"]', '诗', 'shi', '', NULL, '宜春江上寄仰山長老二首 一 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('25e3d347-bc4f-4ed2-93d2-e3167b608fa6', '宜春江上寄仰山長老二首 二', '宜春江上寄仰山长老二首 二', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["雨晴天半碧光流，影倒殘陽濕郡樓。","絕頂有人經劫在，浮生無客暫時遊。","窗開萬壑春泉亂，塔鎖孤燈萬木稠。","欲爲吾師拂衣去，白雲紅葉又新秋。"]', '["雨晴天半碧光流，影倒殘陽濕郡楼。","絕頂有人經劫在，浮生無客暫时游。","窗开万壑春泉亂，塔鎖孤灯万木稠。","欲爲吾師拂衣去，白云紅葉又新秋。"]', '诗', 'shi', '', NULL, '宜春江上寄仰山長老二首 二 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d51cab45-a2b4-4fc5-8cc0-14a2db2e0eb3', '螢', '螢', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["透窗穿竹住還移，萬類俱閑始見伊。","難把寸光藏暗室，自持孤影助明時。","空庭散逐金風起，亂葉爭投玉露垂。","後代儒生懶收拾，夜深飛過讀書帷。"]', '["透窗穿竹住還移，万類俱闲始见伊。","难把寸光藏暗室，自持孤影助明时。","空庭散逐金风起，亂葉爭投玉露垂。","後代儒生懶收拾，夜深飞過读书帷。"]', '诗', 'shi', '', NULL, '螢 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3582f0b1-a468-4cd5-9fa1-97c91524e890', '湘中送翁員外歸閩', '湘中送翁員外归閩', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["船滿琴書與酒杯，清湘影裏片帆開。","人歸南國鄉園去，鴈逐西風日夜來。","天勢漸低分海樹，山程欲盡見城臺。","此身未別江邊寺，猶看星郎奉詔迴。"]', '["船满琴书與酒杯，清湘影裏片帆开。","人归南国乡园去，鴈逐西风日夜来。","天勢漸低分海樹，山程欲尽见城台。","此身未別江邊寺，猶看星郎奉詔迴。"]', '诗', 'shi', '', NULL, '湘中送翁員外歸閩 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31f6c917-bfc8-42ff-8747-db914d4e684f', '寄居道林寺作', '寄居道林寺作', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["嵐濕南朝殿塔寒，此中因得謝塵寰。","已同庭樹千株老，未負溪雲一片閑。","石鏡舊遊臨皎潔，岳蓮曾上徹孱顏。","如今衰颯成多病，黃葉風前晝掩關。"]', '["嵐濕南朝殿塔寒，此中因得謝塵寰。","已同庭樹千株老，未負溪云一片闲。","石镜旧游臨皎潔，岳蓮曾上徹孱顏。","如今衰颯成多病，黄葉风前晝掩关。"]', '诗', 'shi', '', NULL, '寄居道林寺作 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('845d1ec6-2222-41c7-a335-a68be3292540', '沙鷗', '沙鷗', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["暖傍漁船睡不驚，可憐孤潔似華亭。","晚來灣浦衝平碧，晴過汀洲拂淺青。","翡翠靜中修羽翼，鴛鴦閑處事儀形。","何如飛入漢宮裏，留與興亡作典經。"]', '["暖傍漁船睡不驚，可怜孤潔似华亭。","晚来灣浦衝平碧，晴過汀洲拂淺青。","翡翠静中修羽翼，鴛鴦闲处事儀形。","何如飞入漢宮裏，留與兴亡作典經。"]', '诗', 'shi', '', NULL, '沙鷗 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e09dac8e-d8d4-41ee-9a69-545e90ff32a3', '和翁員外題馬太傅宅賈相公井', '和翁員外題马太傅宅賈相公井', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["飛塵不敢下相干，闇脈傍應潤牡丹。","心任短長投玉綆，底須三五映金盤。","神工舊製泓澄在，天澤時加瀲灧寒。","太傅欲旌前古事，星郎屬思久憑欄。"]', '["飞塵不敢下相干，闇脈傍應潤牡丹。","心任短长投玉綆，底須三五映金盤。","神工旧製泓澄在，天澤时加瀲灧寒。","太傅欲旌前古事，星郎屬思久憑欄。"]', '诗', 'shi', '', NULL, '和翁員外題馬太傅宅賈相公井 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a67a7489-ad7f-4f08-8368-e508911cdea3', '看雲', '看云', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["何峰觸石濕苔錢，便逐高風離瀑泉。","深處臥來真隱逸，上頭行去是神仙。","千尋有影滄江底，萬里無蹤碧落邊。","長憶舊山青壁裏，遶庵閑伴老僧禪。"]', '["何峰觸石濕苔錢，便逐高风離瀑泉。","深处臥来真隐逸，上头行去是神仙。","千尋有影滄江底，万里無蹤碧落邊。","长憶旧山青壁裏，遶庵闲伴老僧禪。"]', '诗', 'shi', '', NULL, '看雲 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a9865338-b3f8-463f-b8b9-7edd736926f7', '對雪寄荆幕知己', '对雪寄荆幕知己', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["猛勢微開萬里清，月中看似日中明。","此時鷗鷺無人見，何處關山有客行。","郢唱轉高誰敢和，巴歌相顧自銷聲。","江齋卷箔含毫久，應想梁王禮不經。"]', '["猛勢微开万里清，月中看似日中明。","此时鷗鷺無人见，何处关山有客行。","郢唱轉高誰敢和，巴歌相顧自銷声。","江斋卷箔含毫久，應想梁王禮不經。"]', '诗', 'shi', '', NULL, '對雪寄荆幕知己 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('76b5edde-423b-4f81-b569-5d29d631707a', '送相里秀才赴舉', '送相里秀才赴舉', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["兩上東堂不見春，文明重去有誰親。","曾逢少海尊前客，舊是神仙會裏人。","已遂風雲催化羽，却將雷電助燒鱗。","明年自此登龍後，迴首荆門一路塵。"]', '["兩上东堂不见春，文明重去有誰親。","曾逢少海尊前客，旧是神仙會裏人。","已遂风云催化羽，却將雷電助燒鱗。","明年自此登龙後，迴首荆门一路塵。"]', '诗', 'shi', '', NULL, '送相里秀才赴舉 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('35f52c07-03db-48c5-b687-5b55cdad2c99', '荆門疾中喜謝尊師自南嶽來相里秀才自京至', '荆门疾中喜謝尊師自南嶽来相里秀才自京至', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["閑堂晝臥眼初開，強起徐行遶砌苔。","鶴氅人從衡嶽至，鶉衣客自洛陽來。","坐聞鄰樹栖幽鳥，吟覺江雲發早雷。","西笑東遊此相別，兩途消息待誰迴。"]', '["闲堂晝臥眼初开，強起徐行遶砌苔。","鹤氅人從衡嶽至，鶉衣客自洛陽来。","坐闻鄰樹栖幽鸟，吟覺江云發早雷。","西笑东游此相別，兩途消息待誰迴。"]', '诗', 'shi', '', NULL, '荆門疾中喜謝尊師自南嶽來相里秀才自京至 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c24ecb6-8eb2-4d59-81ba-191bcf2d3e19', '吟興自述', '吟兴自述', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["前習都由未盡空，生知雅學妙難窮。","一千首出悲哀外，五十年銷雪月中。","興去不妨歸靜慮，情來何止發真風。","曾無一字干聲利，豈愧操心負至公。"]', '["前習都由未尽空，生知雅学妙难窮。","一千首出悲哀外，五十年銷雪月中。","兴去不妨归静慮，情来何止發真风。","曾無一字干声利，豈愧操心負至公。"]', '诗', 'shi', '', NULL, '吟興自述 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eeb6e700-8559-43e8-b261-1d817479b9c5', '送謝尊師自南嶽出入京', '送謝尊師自南嶽出入京', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["曾聽鹿鳴逢世亂，因披羽服隱衡陽。","幾多事隔丹霄興，三十年成兩鬢霜。","芝朮未甘銷勇氣，風騷無那激剛腸。","中朝舊有知音在，可是悠悠入帝鄉。"]', '["曾听鹿鳴逢世亂，因披羽服隐衡陽。","幾多事隔丹霄兴，三十年成兩鬢霜。","芝朮未甘銷勇氣，风騷無那激剛腸。","中朝旧有知音在，可是悠悠入帝乡。"]', '诗', 'shi', '', NULL, '送謝尊師自南嶽出入京 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b8c30576-e071-46e2-9b32-cc86000cc015', '送司空學士赴京', '送司空学士赴京', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["弘文初命下江邊，難戀沙鷗與釣船。","藍綬乍稱新學士，白衫初脫舊神仙。","龍山送別風生路，雞樹從容雪照筵。","重謁往年金牓主，便將才術佐陶甄。"]', '["弘文初命下江邊，难戀沙鷗與釣船。","藍綬乍稱新学士，白衫初脫旧神仙。","龙山送別风生路，雞樹從容雪照筵。","重謁往年金牓主，便將才術佐陶甄。"]', '诗', 'shi', '', NULL, '送司空學士赴京 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b3f96422-be66-4f78-9741-b6a16328b978', '春寄尚顏', '春寄尚顏', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["含桃花謝杏花開，杜宇新啼燕子來。","好事可能無分得，名山長似有人催。","簷聲未斷前旬雨，電影還連後夜雷。","心跡共師爭幾許，似人嫌處自遲迴。"]', '["含桃花謝杏花开，杜宇新啼燕子来。","好事可能無分得，名山长似有人催。","簷声未斷前旬雨，電影還連後夜雷。","心跡共師爭幾許，似人嫌处自遲迴。"]', '诗', 'shi', '', NULL, '春寄尚顏 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('92ab02e1-5588-41d7-9e9e-efa688155a86', '寄梁先輩', '寄梁先輩', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["慈恩塔下曲江邊，別後多應夢到仙。","時去與誰論此事，亂來何處覓同年？","陳琳筆硯甘前席，甪里煙霞待共眠。","愛惜麻衣好顏色，未教朱紫汚天然。"]', '["慈恩塔下曲江邊，別後多應梦到仙。","时去與誰論此事，亂来何处覓同年？","陳琳笔硯甘前席，甪里煙霞待共眠。","愛惜麻衣好顏色，未教朱紫汚天然。"]', '诗', 'shi', '', NULL, '寄梁先輩 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2a08e0e5-cb2f-4af0-9b05-b4e1e49edbbd', '荆諸偶作', '荆諸偶作', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["無味吟詩即把經，竟將疎野訪誰行。","身依江寺庭無樹，山遶天涯路有兵。","竹瓦雨聲漂永日，紙窗燈焰照殘更。","從容一覺清涼夢，歸到龍潭掃石枰。"]', '["無味吟诗即把經，竟將疎野訪誰行。","身依江寺庭無樹，山遶天涯路有兵。","竹瓦雨声漂永日，紙窗灯焰照殘更。","從容一覺清涼梦，归到龙潭掃石枰。"]', '诗', 'shi', '', NULL, '荆諸偶作 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e0653b9-7543-451c-ace3-bb723c193c47', '城中晚夏思山', '城中晚夏思山', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["葛衣霑汗功雖健，紙扇搖風力甚卑。","苦熱恨無行脚處，微涼喜到立秋時。","竹軒靜看蜘蛛挂，莎徑閑聽蟋蟀移。","天外有山歸即是，豈同遊子暮何之。"]', '["葛衣霑汗功雖健，紙扇搖风力甚卑。","苦熱恨無行脚处，微涼喜到立秋时。","竹軒静看蜘蛛挂，莎徑闲听蟋蟀移。","天外有山归即是，豈同游子暮何之。"]', '诗', 'shi', '', NULL, '城中晚夏思山 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8057999-df23-4bc7-b453-5314b2d6ced1', '憶舊山', '憶旧山', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["誰請衰羸住北州，七年魂夢舊山丘。","心清檻底瀟湘月，骨冷禪中太華秋。","高節未聞馴虎豹，片言何以傲王侯。","應須脫灑孤峰去，始是分明箇剃頭。"]', '["誰請衰羸住北州，七年魂梦旧山丘。","心清檻底瀟湘月，骨冷禪中太华秋。","高節未闻馴虎豹，片言何以傲王侯。","應須脫灑孤峰去，始是分明箇剃头。"]', '诗', 'shi', '', NULL, '憶舊山 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5876f377-86a8-4d2b-aa52-7f9f5799938a', '寄體休', '寄體休', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["南州君去爲尋醫，病色應除似舊時。","久別莫忘廬阜約，却來須有洞庭詩。","金陵往歲同窺井，峴首前秋共讀碑。","兩處山河見興廢，相思更切臥雲期。"]', '["南州君去爲尋醫，病色應除似旧时。","久別莫忘廬阜約，却来須有洞庭诗。","金陵往歲同窺井，峴首前秋共读碑。","兩处山河见兴廢，相思更切臥云期。"]', '诗', 'shi', '', NULL, '寄體休 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b6c5f195-2466-4111-a607-7d04f15948e2', '過陸鴻漸舊居', '過陸鴻漸旧居', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["楚客西來過舊居，讀碑尋傳見終初。","佯狂未必輕儒業，高尚何妨誦佛書。","種竹岸香連菡萏，煮茶泉影落蟾蜍。","如今若更生來此，知有何人贈白驢。"]', '["楚客西来過旧居，读碑尋傳见終初。","佯狂未必轻儒業，高尚何妨誦佛书。","種竹岸香連菡萏，煮茶泉影落蟾蜍。","如今若更生来此，知有何人贈白驢。"]', '诗', 'shi', '', NULL, '過陸鴻漸舊居 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a72bd30-0a5a-4e6d-a379-a306f7d55350', '寄懷鍾陵舊遊因寄知己', '寄懷鍾陵旧游因寄知己', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["洗井僧來說舊遊，西江東岸是城樓。","昔年淹跡因王化，長日凭欄看水流。","真觀上人棲樹石，陳陶處士在林丘。","終拖老病重尋去，得到匡廬死便休。"]', '["洗井僧来说旧游，西江东岸是城楼。","昔年淹跡因王化，长日凭欄看水流。","真观上人棲樹石，陳陶处士在林丘。","終拖老病重尋去，得到匡廬死便休。"]', '诗', 'shi', '', NULL, '寄懷鍾陵舊遊因寄知己 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('94625b68-648e-4e16-8ecd-6d7d872836b2', '遣懷', '遣懷', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["病腸休洗老休醫，七十能饒百歲期。","不死任還蓬島客，無生自有雪山師。","浮雲聚散俱關慮，明月相逢好展眉。","既兆未萌閑酌度，不如中抱是尋思。"]', '["病腸休洗老休醫，七十能饒百歲期。","不死任還蓬島客，無生自有雪山師。","浮云聚散俱关慮，明月相逢好展眉。","既兆未萌闲酌度，不如中抱是尋思。"]', '诗', 'shi', '', NULL, '遣懷 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('89136f94-cbae-4c64-8d93-ef416bb838d3', '懷武陵因寄幕中韓先輩何從事', '懷武陵因寄幕中韓先輩何從事', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["武陵嘉致跡多幽，每見圖經恨白頭。","溪浪碧通何處去，桃花紅過郡前流。","常聞相幕鴛鴻興，日向神仙洞府遊。","鑿井耕田人在否，如今天子正徵搜。"]', '["武陵嘉致跡多幽，每见圖經恨白头。","溪浪碧通何处去，桃花紅過郡前流。","常闻相幕鴛鴻兴，日向神仙洞府游。","鑿井耕田人在否，如今天子正徵搜。"]', '诗', 'shi', '', NULL, '懷武陵因寄幕中韓先輩何從事 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eceea92a-673b-48d5-b5e6-12cad740aed8', '贈樊處士', '贈樊处士', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["小子聲名天下知，滿簪霜雪白麻衣。","誰將一著爭先後，共向長安定是非。","有路未曾迷日用，無貪終不亂天機。","閑尋道士過仙觀，賭得黃庭兩卷歸。"]', '["小子声名天下知，满簪霜雪白麻衣。","誰將一著爭先後，共向长安定是非。","有路未曾迷日用，無貪終不亂天機。","闲尋道士過仙观，賭得黄庭兩卷归。"]', '诗', 'shi', '', NULL, '贈樊處士 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ed4861c-0dee-4bcc-80c4-9e4227fd2fa3', '荆渚逢禪友', '荆渚逢禪友', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["澤國相逢話一宵，雲山偶別隔前朝。","社思匡岳無宗炳，詩憶揚州有鮑昭。","晨野黍離春漠漠，水天星粲夜遙遙。","閑吟莫忘傳心祖，曾立階前雪到腰。"]', '["澤国相逢話一宵，云山偶別隔前朝。","社思匡岳無宗炳，诗憶揚州有鲍昭。","晨野黍離春漠漠，水天星粲夜遙遙。","闲吟莫忘傳心祖，曾立階前雪到腰。"]', '诗', 'shi', '', NULL, '荆渚逢禪友 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('abdd7568-fbdd-4ba2-aeee-8ed4483c6788', '送僧歸洛中', '送僧归洛中', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["赤日彤霞照晚坡，東州道路興如何。","蟬離楚柳鳴猶少，葉到嵩雲落漸多。","海內自爲閑去住，關頭誰問舊經過。","叮嚀與訪春山寺，白樂天真在也麽。"]', '["赤日彤霞照晚坡，东州道路兴如何。","蟬離楚柳鳴猶少，葉到嵩云落漸多。","海內自爲闲去住，关头誰问旧經過。","叮嚀與訪春山寺，白乐天真在也麽。"]', '诗', 'shi', '', NULL, '送僧歸洛中 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e01acfd-beec-4345-933d-19d0f212ea21', '道林寓居', '道林寓居', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["秋泉一片樹千株，暮汲寒燒外有餘。","青嶂這邊來已熟，紅塵那畔去應疎。","風騷未肯忘雕琢，瀟灑無妨更剃除。","即問沃州開士僻，愛禽憐駿意何如。"]', '["秋泉一片樹千株，暮汲寒燒外有餘。","青嶂這邊来已熟，紅塵那畔去應疎。","风騷未肯忘雕琢，瀟灑無妨更剃除。","即问沃州开士僻，愛禽怜駿意何如。"]', '诗', 'shi', '', NULL, '道林寓居 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d0dbc01-842e-43ee-aa6a-e6d31966cce7', '仙掌', '仙掌', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["峭形寒倚夕陽天，毛女蓮花翠影連。","雲外自爲高出手，人間誰合鬬揮拳。","鶴拋青漢來巖檜，僧隔黃河望頂煙。","晴露紅霞長滿掌，只應棲託是神仙。"]', '["峭形寒倚夕陽天，毛女蓮花翠影連。","云外自爲高出手，人间誰合鬬揮拳。","鹤拋青漢来巖檜，僧隔黄河望頂煙。","晴露紅霞长满掌，只應棲託是神仙。"]', '诗', 'shi', '', NULL, '仙掌 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf3fc1be-e0fc-41ea-a7c5-f5bc57ed6ea9', '中秋月', '中秋月', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["空碧無雲露濕衣，羣星光外湧清規。","東樓莫礙漸高勢，四海待看當午時。","還許分明吟皓魄，肯教幽暗取丹枝。","可憐半夜嬋娟影，正對五侯殘酒池。"]', '["空碧無云露濕衣，羣星光外湧清規。","东楼莫礙漸高勢，四海待看當午时。","還許分明吟皓魄，肯教幽暗取丹枝。","可怜半夜嬋娟影，正对五侯殘酒池。"]', '诗', 'shi', '', NULL, '中秋月 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d63bb71-c82a-476e-82e7-07504f0de911', '送禪者遊南岳', '送禪者游南岳', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["忽隨南櫂去衡陽，誰住江邊樹下房。","塵夢是非都覺了，野雲心地更何妨。","漸臨瀑布聽猨思，却背岣嶁有鴈行。","想到中峰上層寺，石窗秋霽見瀟湘。"]', '["忽隨南櫂去衡陽，誰住江邊樹下房。","塵梦是非都覺了，野云心地更何妨。","漸臨瀑布听猨思，却背岣嶁有鴈行。","想到中峰上層寺，石窗秋霽见瀟湘。"]', '诗', 'shi', '', NULL, '送禪者遊南岳 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('579a5aee-42b5-4567-98f8-26a5b697523b', '聞道林諸友嘗茶因有寄', '闻道林諸友嘗茶因有寄', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["槍旗冉冉綠叢園，穀雨初晴叫杜鵑。","摘帶嶽華蒸曉露，碾和松粉煮春泉。","高人夢惜藏巖裏，白硾封題寄火前。","應念苦吟耽睡起，不堪無過夕陽天。"]', '["槍旗冉冉綠叢园，穀雨初晴叫杜鵑。","摘带嶽华蒸晓露，碾和松粉煮春泉。","高人梦惜藏巖裏，白硾封題寄火前。","應念苦吟耽睡起，不堪無過夕陽天。"]', '诗', 'shi', '', NULL, '聞道林諸友嘗茶因有寄 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0f164e6-56f4-49a6-9fd1-5423bfdef258', '將歸舊山留別錯公', '將归旧山留別錯公', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["舊峰前昨下來時，白石叢叢間紫薇。","章句不堪歌有道，溪山只合退無機。","雲含曖態晴猶在，鶴養閑神晝不飛。","欲去更思過丈室，二年頻此揖清暉。"]', '["旧峰前昨下来时，白石叢叢间紫薇。","章句不堪歌有道，溪山只合退無機。","云含曖態晴猶在，鹤養闲神晝不飞。","欲去更思過丈室，二年頻此揖清暉。"]', '诗', 'shi', '', NULL, '將歸舊山留別錯公 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0553a7d2-4691-4a15-afb8-b69f83229a6f', '聞尚顏上人剏居有寄', '闻尚顏上人剏居有寄', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["麓山南面橘洲西，別搆新齋與竹齊。","野客已聞將鶴贈，江僧未說有詩題。","窗臨杳靄寒千嶂，枕遍潺湲月一溪。","可想乍移禪榻處，松陰冷濕壁新泥。"]', '["麓山南面橘洲西，別搆新斋與竹齊。","野客已闻將鹤贈，江僧未说有诗題。","窗臨杳靄寒千嶂，枕遍潺湲月一溪。","可想乍移禪榻处，松陰冷濕壁新泥。"]', '诗', 'shi', '', NULL, '聞尚顏上人剏居有寄 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b546a6e8-eaca-40a7-a80a-962b9f99c8b9', '庚午歲九日作', '庚午歲九日作', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["門底秋苔嫩似藍，此中消息興何堪。","亂離偷過九月九，頭尾算來三十三。","雲影半晴開夢澤，菊花微暖傍江潭。","故人今日在不在，胡鴈背風飛向南。"]', '["门底秋苔嫩似藍，此中消息兴何堪。","亂離偷過九月九，头尾算来三十三。","云影半晴开梦澤，菊花微暖傍江潭。","故人今日在不在，胡鴈背风飞向南。"]', '诗', 'shi', '', NULL, '庚午歲九日作 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('043978af-e3aa-4166-a0c0-99ab38fa0e1f', '逢進士沈彬', '逢進士沈彬', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["欲話趨時首重騷，因君倍惜剃頭刀。","千般貴在能過達，一片心閑不那高。","山疊好雲藏玉鳥，海翻狂浪隔金鼇。","時應記得長安事，曾向文場屬思勞。"]', '["欲話趨时首重騷，因君倍惜剃头刀。","千般貴在能過達，一片心闲不那高。","山叠好云藏玉鸟，海翻狂浪隔金鼇。","时應記得长安事，曾向文場屬思勞。"]', '诗', 'shi', '', NULL, '逢進士沈彬 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a333073d-79a7-4d7e-9847-ecdcf98baa6e', '聞王員外新恩有寄', '闻王員外新恩有寄', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["欲退無因貴逼來，少儀官美右丞才。","青袍早許淹花幕，霜簡方聞謝柏臺。","金諾靜宜資講誦，玉山寒稱奉尊罍。","西峰有客思相賀，門隔瀟湘雪未開。"]', '["欲退無因貴逼来，少儀官美右丞才。","青袍早許淹花幕，霜簡方闻謝柏台。","金諾静宜資講誦，玉山寒稱奉尊罍。","西峰有客思相賀，门隔瀟湘雪未开。"]', '诗', 'shi', '', NULL, '聞王員外新恩有寄 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4137f4d3-87f4-4bb6-98da-50119620e993', '秋夕言懷寄所知', '秋夕言懷寄所知', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["休問蒙莊材不材，孤燈影共傍寒灰。","忘筌話道心甘死，候體論詩口懶開。","窗外風濤連建業，夢中雲水憶天台。","相疎却是相知分，誰訝經年一度來。"]', '["休问蒙莊材不材，孤灯影共傍寒灰。","忘筌話道心甘死，候體論诗口懶开。","窗外风濤連建業，梦中云水憶天台。","相疎却是相知分，誰訝經年一度来。"]', '诗', 'shi', '', NULL, '秋夕言懷寄所知 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('569d6d04-e8e1-4d9d-bea3-e818919a830e', '答禪者', '答禪者', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["五老峰前相遇時，兩無言語只揚眉。","南宗北祖皆如此，天上人間更問誰。","山衲靜披雲片片，鐵刀涼削鬢絲絲。","閑吟莫學湯從事，拋却袈裟負本師。"]', '["五老峰前相遇时，兩無言語只揚眉。","南宗北祖皆如此，天上人间更问誰。","山衲静披云片片，鐵刀涼削鬢絲絲。","闲吟莫学湯從事，拋却袈裟負本師。"]', '诗', 'shi', '', NULL, '答禪者 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('60b40ae2-e5bb-473b-8a5f-7cccd10cfc3a', '寄尚顏', '寄尚顏', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["莫向孤峰道息機，有人偷眼羨吾師。","滿身光化年前寵，幾軸開平歲裏詩。","北闕故人隨喪亂，南山舊寺在參差。","清吟但憶徐方政，應恨當時不見時。"]', '["莫向孤峰道息機，有人偷眼羨吾師。","满身光化年前寵，幾軸开平歲裏诗。","北闕故人隨喪亂，南山旧寺在參差。","清吟但憶徐方政，應恨當时不见时。"]', '诗', 'shi', '', NULL, '寄尚顏 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7c70edd-9890-4313-a80a-4a3f6672dfac', '梓栗杖送人', '梓栗杖送人', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["禪家何物贈分襟，只有天台杖一尋。","拄去客歸青洛遠，採來僧入白雲深。","遊山曾把探龍穴，出世期將指佛心。","此日江邊贈君後，却攜筇杖向東林。"]', '["禪家何物贈分襟，只有天台杖一尋。","拄去客归青洛远，採来僧入白云深。","游山曾把探龙穴，出世期將指佛心。","此日江邊贈君後，却携筇杖向东林。"]', '诗', 'shi', '', NULL, '梓栗杖送人 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7a8914f-7cb4-4eaf-863a-39af17cae487', '寄朗陵二禪友', '寄朗陵二禪友', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["瀟湘曾宿話詩評，荆楚連秋阻野情。","金錫罷遊雙鬢白，鐵盂終守一齋清。","篇章老欲齊高手，風月閑思到極精。","南望山門石何處，滄浪雲夢浸天橫。"]', '["瀟湘曾宿話诗評，荆楚連秋阻野情。","金錫罷游雙鬢白，鐵盂終守一斋清。","篇章老欲齊高手，风月闲思到極精。","南望山门石何处，滄浪云梦浸天橫。"]', '诗', 'shi', '', NULL, '寄朗陵二禪友 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('191bd6b5-afe7-41f0-99d7-008b771b8e6e', '燈', '灯', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["幽光耿耿草堂空，窗隔飛蛾恨不通。","紅燼自凝清夜朵，赤心長謝碧紗籠。","雲藏水國城臺裏，雨閉松門殿塔中。","金屋玉堂開照睡，豈知螢雪有深功。"]', '["幽光耿耿草堂空，窗隔飞蛾恨不通。","紅燼自凝清夜朵，赤心长謝碧紗籠。","云藏水国城台裏，雨閉松门殿塔中。","金屋玉堂开照睡，豈知螢雪有深功。"]', '诗', 'shi', '', NULL, '燈 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b2ef0000-07b7-4280-bcb7-714c3dde5e04', '寄金陵幕中李郎中', '寄金陵幕中李郎中', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["龍門支派富才能，年少飛翔便大鵬。","久待尊罍臨鐵甕，又從幢節鎮金陵。","精神一隻秋空鶴，騷雅千尋夏井冰。","長憶相招宿華館，數宵忘寢盡寒燈。"]', '["龙门支派富才能，年少飞翔便大鵬。","久待尊罍臨鐵甕，又從幢節鎮金陵。","精神一隻秋空鹤，騷雅千尋夏井冰。","长憶相招宿华館，數宵忘寢尽寒灯。"]', '诗', 'shi', '', NULL, '寄金陵幕中李郎中 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a1778ab5-de06-4036-a3d6-60dfc0bf4d66', '寄韓蛻秀才', '寄韓蛻秀才', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["松門高不似侯門，蘚逕鞋蹤觸處分。","遠事即爲無害鳥，多閑便是有情雲。","那憂寵辱來驚我，且寄風騷去敵君。","[知]伴李膺琴酒外，絳紗閑卷共論文。"]', '["松门高不似侯门，蘚逕鞋蹤觸处分。","远事即爲無害鸟，多闲便是有情云。","那憂寵辱来驚我，且寄风騷去敵君。","[知]伴李膺琴酒外，絳紗闲卷共論文。"]', '诗', 'shi', '', NULL, '寄韓蛻秀才 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('030c2e5a-4197-4d1f-a081-60190821b101', '湘中春興', '湘中春兴', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["雨歇江明苑樹乾，物妍時泰恣遊盤。","更無輕翠勝楊柳，盡覺濃華在牡丹。","終日去還拋寂寞，遶池迴却凭欄干。","紅芳片片由青帝，忍向西園看落殘。"]', '["雨歇江明苑樹乾，物妍时泰恣游盤。","更無轻翠勝楊柳，尽覺濃华在牡丹。","終日去還拋寂寞，遶池迴却凭欄干。","紅芳片片由青帝，忍向西园看落殘。"]', '诗', 'shi', '', NULL, '湘中春興 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c4b6ef5c-7fa4-471c-989c-09eefb397dac', '送錯公栖公南遊', '送錯公栖公南游', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["洪偃湯休道不殊，高帆共載興何俱。","北京喪亂離丹鳳，南國煙花入鷓鴣。","明月團圓臨桂水，白雲重疊起蒼梧。","威儀本是朝天士，暫向遼荒住得無。"]', '["洪偃湯休道不殊，高帆共載兴何俱。","北京喪亂離丹鳳，南国煙花入鷓鴣。","明月團圓臨桂水，白云重叠起蒼梧。","威儀本是朝天士，暫向遼荒住得無。"]', '诗', 'shi', '', NULL, '送錯公栖公南遊 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc734223-28c2-4e54-806e-55ed2f4ea0e0', '寄南岳諸道友', '寄南岳諸道友', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["南望衡陽積瘴開，去年曾踏雪遊迴。","謾爲楚客蹉跎過，却是邊鴻的當來。","乳竇孤明含海日，石橋危滑長春苔。","終尋十八高人去，共坐蒼崖養聖胎。"]', '["南望衡陽積瘴开，去年曾踏雪游迴。","謾爲楚客蹉跎過，却是邊鴻的當来。","乳竇孤明含海日，石橋危滑长春苔。","終尋十八高人去，共坐蒼崖養聖胎。"]', '诗', 'shi', '', NULL, '寄南岳諸道友 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac097c85-092b-42c1-81fc-fbf374e4ac28', '送韓蛻秀才赴舉', '送韓蛻秀才赴舉', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["槐花館驛暮塵昏，此去分明吏部孫。","才器合居科第首，風流幸是縉紳門。","春和洛水清無浪，雪洗高峰碧斷根。","堪想都人齊指點，列仙相次上崑崙。"]', '["槐花館驛暮塵昏，此去分明吏部孫。","才器合居科第首，风流幸是縉紳门。","春和洛水清無浪，雪洗高峰碧斷根。","堪想都人齊指点，列仙相次上崑崙。"]', '诗', 'shi', '', NULL, '送韓蛻秀才赴舉 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d44b4860-13a9-4bdd-9e03-6e212b34e1f0', '[溪]居寓言', '[溪]居寓言', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["秋蔬數壠傍潺湲，頗覺生涯異俗緣。","詩興難窮花草外，野情何限水雲邊。","蟲聲遶屋無人語，月影當松有鶴眠。","寄向東溪老樵道，莫催丹桂博青錢。"]', '["秋蔬數壠傍潺湲，頗覺生涯異俗緣。","诗兴难窮花草外，野情何限水云邊。","蟲声遶屋無人語，月影當松有鹤眠。","寄向东溪老樵道，莫催丹桂博青錢。"]', '诗', 'shi', '', NULL, '[溪]居寓言 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cde18858-f034-40ef-ae14-e99e2ff9630f', '遣懷', '遣懷', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["詩病相兼老病深，世醫徒更費千金。","餘生豈必虛拋擲，未死何妨樂詠吟。","流水不迴休歎息，白雲無跡莫追尋。","閑身自有閑消處，黃葉清風蟬一林。"]', '["诗病相兼老病深，世醫徒更費千金。","餘生豈必虛拋擲，未死何妨乐詠吟。","流水不迴休歎息，白云無跡莫追尋。","闲身自有闲消处，黄葉清风蟬一林。"]', '诗', 'shi', '', NULL, '遣懷 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9317d841-2126-47db-bab7-d2e2e5288641', '自湘中將入蜀留別諸友', '自湘中將入蜀留別諸友', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["巾舃初隨入蜀船，風帆吼過洞庭煙。","七千里路到何處，十二峰雲更那邊。","巫女暮歸林淅瀝，巴猨吟斷月嬋娟。","來年五月峨嵋雪，坐看消融滿錦川。"]', '["巾舃初隨入蜀船，风帆吼過洞庭煙。","七千里路到何处，十二峰云更那邊。","巫女暮归林淅瀝，巴猨吟斷月嬋娟。","来年五月峨嵋雪，坐看消融满錦川。"]', '诗', 'shi', '', NULL, '自湘中將入蜀留別諸友 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a03ac44-f9e8-4554-b280-89298ed3504b', '寄匡阜諸公二首 一', '寄匡阜諸公二首 一', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["松頭柏頂碧森森，虛檻寒吹夏景深。","靜社可追長往跡，白蓮難問久修心。","山圍四面纔容寺，月到中宵始滿林。","爭學忘言住幽勝，吾師遺集盡清吟。"]', '["松头柏頂碧森森，虛檻寒吹夏景深。","静社可追长往跡，白蓮难问久修心。","山圍四面纔容寺，月到中宵始满林。","爭学忘言住幽勝，吾師遺集尽清吟。"]', '诗', 'shi', '', NULL, '寄匡阜諸公二首 一 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('48c3f519-0bc3-45d0-9bef-c71b41819c10', '寄匡阜諸公二首 二', '寄匡阜諸公二首 二', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["峰前林下東西寺，地角天涯來往僧。","泉月淨流閑世界，杉松深鎖盡香燈。","爭無大士重修社，合有諸賢更服膺。","曾寄鄰房挂缾錫，雨聞巖溜解春冰。"]', '["峰前林下东西寺，地角天涯来往僧。","泉月淨流闲世界，杉松深鎖尽香灯。","爭無大士重修社，合有諸賢更服膺。","曾寄鄰房挂缾錫，雨闻巖溜解春冰。"]', '诗', 'shi', '', NULL, '寄匡阜諸公二首 二 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b1a77c3d-e4e2-4df3-9384-c3b258c7a83d', '送人入蜀', '送人入蜀', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["何必閑吟蜀道難，知君心出嶮巘間。","尋常秋泛江陵去，容易春浮錦水還。","兩面碧懸神女峽，幾重青出丈人山。","文君酒市逢初雪，滿貰新沽洗旅顏。"]', '["何必闲吟蜀道难，知君心出嶮巘间。","尋常秋泛江陵去，容易春浮錦水還。","兩面碧懸神女峽，幾重青出丈人山。","文君酒市逢初雪，满貰新沽洗旅顏。"]', '诗', 'shi', '', NULL, '送人入蜀 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9074264d-f9ae-452d-a5ca-4eeadb950347', '酬廬山張處士', '酬廬山張处士', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["髮枯身老任浮沉，懶泥秋風更役吟。","新事向人堪結舌，舊詩開卷但傷心。","苔牀臥憶泉聲遶，麻履行思樹影深。","終謝柴桑與彭澤，醉遊閑訪入東林。"]', '["髮枯身老任浮沉，懶泥秋风更役吟。","新事向人堪結舌，旧诗开卷但傷心。","苔牀臥憶泉声遶，麻履行思樹影深。","終謝柴桑與彭澤，醉游闲訪入东林。"]', '诗', 'shi', '', NULL, '酬廬山張處士 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('be9a8954-4c83-4652-b934-d9037b29c419', '寄峴山道人', '寄峴山道人', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["鳳門高對鹿門青，往歲經過恨未平。","辯鼎上人方話道，臥龍丞相忽追兵。","爐峰已負重迴計，華嶽終懸未去情。","聞說東周天子聖，會搖金錫却西行。"]', '["鳳门高对鹿门青，往歲經過恨未平。","辯鼎上人方話道，臥龙丞相忽追兵。","爐峰已負重迴計，华嶽終懸未去情。","闻说东周天子聖，會搖金錫却西行。"]', '诗', 'shi', '', NULL, '寄峴山道人 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('45eb45b5-0c32-4195-9f26-90a04e72486f', '送王處士遊蜀', '送王处士游蜀', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["又挂寒帆向錦川，木蘭舟裏過殘年。","自修姹姹爐中物，擬作飄飄水上仙。","三峽浪喧明月夜，萬州山到夕陽天。","來年的有荆南信，迴札應緘十色牋。"]', '["又挂寒帆向錦川，木蘭舟裏過殘年。","自修姹姹爐中物，擬作飄飄水上仙。","三峽浪喧明月夜，万州山到夕陽天。","来年的有荆南信，迴札應緘十色牋。"]', '诗', 'shi', '', NULL, '送王處士遊蜀 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('552c55a6-5b99-4b8b-9617-f94fdf22aeba', '懷金陵李推官僧自牧', '懷金陵李推官僧自牧', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["秣陵長憶共吟遊，儒釋風騷道上流。","蓮幕少年輕謝朓，雪山真子鄙湯休。","也應有作懷清苦，莫謂無心過白頭。","欲附別來千萬意，病身初起向殘秋。"]', '["秣陵长憶共吟游，儒釋风騷道上流。","蓮幕少年轻謝朓，雪山真子鄙湯休。","也應有作懷清苦，莫謂無心過白头。","欲附別来千万意，病身初起向殘秋。"]', '诗', 'shi', '', NULL, '懷金陵李推官僧自牧 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0547d4c2-f1ec-4c00-a00e-c74a6de1b13c', '寄尋萍公', '寄尋萍公', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["聞在湓城多寄住，隨時談笑渾塵埃。","孤峰恐憶便歸去，浮世要看還下來。","萬頃野煙春雨斷，九條寒浪晚窗開。","虎溪橋上龍潭寺，曾此相尋踏雪迴。"]', '["闻在湓城多寄住，隨时談笑渾塵埃。","孤峰恐憶便归去，浮世要看還下来。","万頃野煙春雨斷，九條寒浪晚窗开。","虎溪橋上龙潭寺，曾此相尋踏雪迴。"]', '诗', 'shi', '', NULL, '寄尋萍公 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e07b043d-1caf-4d42-8016-c1ba1dbe07b2', '得李推官近寄懷', '得李推官近寄懷', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["荆門前歲使乎迴，求得星郎近制來。","連日借吟終不已，一燈忘寢又重開。","秋風漫作牽情賦，春草真爲入夢才。","堪笑陳宮諸狎客，當時空有箇追陪。"]', '["荆门前歲使乎迴，求得星郎近制来。","連日借吟終不已，一灯忘寢又重开。","秋风漫作牽情賦，春草真爲入梦才。","堪笑陳宮諸狎客，當时空有箇追陪。"]', '诗', 'shi', '', NULL, '得李推官近寄懷 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b93cea2-1597-485b-af2b-02958879c9ac', '對菊', '对菊', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["蝶醉風狂半折時，冷煙清露壓離披。","欲傾琥珀盃浮爾，好把茱萸朵配伊。","孔雀毛衣應者是，鳳凰金翠更無之。","何因栽向僧園裏，門外重陽過不知。"]', '["蝶醉风狂半折时，冷煙清露壓離披。","欲傾琥珀盃浮爾，好把茱萸朵配伊。","孔雀毛衣應者是，鳳凰金翠更無之。","何因栽向僧园裏，门外重陽過不知。"]', '诗', 'shi', '', NULL, '對菊 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6e89121a-f091-4712-9f15-c292d9e4e0c0', '憶東林因送二生歸', '憶东林因送二生归', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["好向東林度此生，半天山脚寺門平。","紅霞嶂底潺潺色，清夜房前瑟瑟聲。","偶別十年成瞬息，欲來千里阻刀兵。","可憐二子同歸興，南國煙花路好行。"]', '["好向东林度此生，半天山脚寺门平。","紅霞嶂底潺潺色，清夜房前瑟瑟声。","偶別十年成瞬息，欲来千里阻刀兵。","可怜二子同归兴，南国煙花路好行。"]', '诗', 'shi', '', NULL, '憶東林因送二生歸 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad80fb74-de34-494f-8fc6-528730ec3d78', '渚宮西城池上居', '渚宮西城池上居', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["城東移錫住城西，綠遶春波引杖藜。","翡翠滿身衣有異，鷺鷥通體格非低。","風搖柳眼開煙小，暖逼蘭芽出土齊。","猶有幽深不相似，剡溪乘櫂入耶溪。"]', '["城东移錫住城西，綠遶春波引杖藜。","翡翠满身衣有異，鷺鷥通體格非低。","风搖柳眼开煙小，暖逼蘭芽出土齊。","猶有幽深不相似，剡溪乘櫂入耶溪。"]', '诗', 'shi', '', NULL, '渚宮西城池上居 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8b37f4d-3a71-4d1e-af69-28eda4ca7444', '中秋夕愴懷寄荆幕孫郎中', '中秋夕愴懷寄荆幕孫郎中', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["白蓮香散沼痕乾，綠篠陰濃蘚地寒。","年老寄居思隱切，夜涼留客話時難。","行僧盡去雲山遠，賓鴈同來澤國寬。","時謝孔璋操檄外，每將空病問衰殘。"]', '["白蓮香散沼痕乾，綠篠陰濃蘚地寒。","年老寄居思隐切，夜涼留客話时难。","行僧尽去云山远，賓鴈同来澤国寬。","时謝孔璋操檄外，每將空病问衰殘。"]', '诗', 'shi', '', NULL, '中秋夕愴懷寄荆幕孫郎中 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('53ac9da3-60ea-43d0-8a20-778ff5cbba47', '酬湘幕徐員外見寄', '酬湘幕徐員外见寄', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["東海儒宗事業全，冰稜孤峭類神仙。","詩同李賀精通鬼，文擬劉軻妙入禪。","珠履早曾從相府，玳簪今又別官筵。","篇章幾謝傳西楚，空想雄風度十年。"]', '["东海儒宗事業全，冰稜孤峭類神仙。","诗同李賀精通鬼，文擬劉軻妙入禪。","珠履早曾從相府，玳簪今又別官筵。","篇章幾謝傳西楚，空想雄风度十年。"]', '诗', 'shi', '', NULL, '酬湘幕徐員外見寄 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e683122a-1bb3-4dc7-b970-27ccd3fd4ac8', '寄蜀國廣濟大師', '寄蜀国廣濟大師', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["冰壓霜壇律格清，三千傳授盡門生。","禪心盡入空無跡，詩句閑搜寂有聲。","滿國繁華徒自樂，兩朝更變未曾驚。","終思相約岷峨去，不得攜筇一路行。"]', '["冰壓霜壇律格清，三千傳授尽门生。","禪心尽入空無跡，诗句闲搜寂有声。","满国繁华徒自乐，兩朝更变未曾驚。","終思相約岷峨去，不得携筇一路行。"]', '诗', 'shi', '', NULL, '寄蜀國廣濟大師 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ad60c34-cf5c-448e-a26b-791055a44955', '答獻上人卷', '答獻上人卷', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["衲衣禪客袖篇章，江上相尋共感傷。","秦甸亂來栖白沒，杼山空後皎然亡。","清留島月秋凝露，苦寄巴猨夜叫霜。","珍重南宗好才子，灰心冥目外無妨。"]', '["衲衣禪客袖篇章，江上相尋共感傷。","秦甸亂来栖白沒，杼山空後皎然亡。","清留島月秋凝露，苦寄巴猨夜叫霜。","珍重南宗好才子，灰心冥目外無妨。"]', '诗', 'shi', '', NULL, '答獻上人卷 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b7294b4-d7b7-4c23-8e0d-154edac67012', '寄武陵貫微上人二首 一', '寄武陵貫微上人二首 一', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["知泛滄浪櫂未還，西峰房鎖夜潺潺。","春陪相府遊仙洞，雪共賓寮對玉山。","詩裏幾添新菡萏，衲痕應換舊斕斑。","莫忘一句曹溪妙，堪塞孫孫騁度關。"]', '["知泛滄浪櫂未還，西峰房鎖夜潺潺。","春陪相府游仙洞，雪共賓寮对玉山。","诗裏幾添新菡萏，衲痕應換旧斕斑。","莫忘一句曹溪妙，堪塞孫孫騁度关。"]', '诗', 'shi', '', NULL, '寄武陵貫微上人二首 一 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b1af4005-e439-4ef6-b382-0f288b246726', '寄武陵貫微上人二首 二', '寄武陵貫微上人二首 二', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["吳頭東面楚西邊，雲接蒼梧水浸天。","兩地別離身已老，一言相合道休傳。","風騷妙欲凌春草，蹤跡閑思遶嶽蓮。","不是傲他名利世，吾師本在雪山巔。"]', '["吳头东面楚西邊，云接蒼梧水浸天。","兩地別離身已老，一言相合道休傳。","风騷妙欲凌春草，蹤跡闲思遶嶽蓮。","不是傲他名利世，吾師本在雪山巔。"]', '诗', 'shi', '', NULL, '寄武陵貫微上人二首 二 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('157a8f0c-1cd1-4369-98e5-98be0e3d2acf', '懷體休上人', '懷體休上人', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["仲宣樓上望重湖，君到瀟湘得健無。","病遇何人分藥餌，詩逢誰子論功夫。","杉蘿寺裏尋秋早，橘柚洲邊度日晡。","許送自身歸華嶽，待來朝暮拂缾盂。"]', '["仲宣楼上望重湖，君到瀟湘得健無。","病遇何人分藥餌，诗逢誰子論功夫。","杉蘿寺裏尋秋早，橘柚洲邊度日晡。","許送自身归华嶽，待来朝暮拂缾盂。"]', '诗', 'shi', '', NULL, '懷體休上人 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4199e133-c2a3-425b-9468-f5abd4859a49', '招湖上兄弟', '招湖上兄弟', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["去歲得君消息在，兩憑人信過重湖。","忍貪風月當年少，不寄音書慰老夫。","藥鼎近聞傳祕訣，詩門曾說擁寒爐。","漢江江路西來便，好傍扁舟訪我無。"]', '["去歲得君消息在，兩憑人信過重湖。","忍貪风月當年少，不寄音书慰老夫。","藥鼎近闻傳祕訣，诗门曾说擁寒爐。","漢江江路西来便，好傍扁舟訪我無。"]', '诗', 'shi', '', NULL, '招湖上兄弟 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e422a9e-8d20-4034-a808-4f85119c2dc3', '江居寄關中知己', '江居寄关中知己', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["多病多慵漢水邊，流年不覺已皤然。","舊栽花地添黃竹，新陷盆池換白蓮。","雪月未忘招遠客，雲山終待去安禪。","八行書札君休問，不似風騷寄一篇。"]', '["多病多慵漢水邊，流年不覺已皤然。","旧栽花地添黄竹，新陷盆池換白蓮。","雪月未忘招远客，云山終待去安禪。","八行书札君休问，不似风騷寄一篇。"]', '诗', 'shi', '', NULL, '江居寄關中知己 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e50ac36-6057-4ee5-8fc7-13466a37f699', '中秋十五夜寄人', '中秋十五夜寄人', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["高河瑟瑟轉金盤，歕露吹光逆凭欄。","四海魚龍精魄冷，五山鸞鶴骨毛寒。","今宵盡向圓時望，後夜誰當缺處看。","何事清光與蟾兔，却教才小少留難。"]', '["高河瑟瑟轉金盤，歕露吹光逆凭欄。","四海鱼龙精魄冷，五山鸾鹤骨毛寒。","今宵尽向圓时望，後夜誰當缺处看。","何事清光與蟾兔，却教才小少留难。"]', '诗', 'shi', '', NULL, '中秋十五夜寄人 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c7daab8b-5fca-43cc-a286-294b8e5cae76', '謝人自鍾陵寄紙筆', '謝人自鍾陵寄紙笔', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["故人猶憶苦吟勞，所惠何殊金錯刀。","霜雪剪栽新剡硾，鋒鋩管束本宣毫。","知君倒篋情何厚，借我臨池價斗高。","詞客分張看欲盡，不堪來處隔秋濤。"]', '["故人猶憶苦吟勞，所惠何殊金錯刀。","霜雪剪栽新剡硾，鋒鋩管束本宣毫。","知君倒篋情何厚，借我臨池價斗高。","词客分張看欲尽，不堪来处隔秋濤。"]', '诗', 'shi', '', NULL, '謝人自鍾陵寄紙筆 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81166747-5b87-45bb-8f44-000830cedaf5', '移居西湖作二首 一', '移居西湖作二首 一', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["火雲陽焰欲燒空，小檻幽窗想舊峰。","白汗此時流枕簟，清風何處動杉松。","殘更正好眠涼月，遠寺俄聞報曉鐘。","只待秋聲滌心地，衲衣新洗健形容。"]', '["火云陽焰欲燒空，小檻幽窗想旧峰。","白汗此时流枕簟，清风何处动杉松。","殘更正好眠涼月，远寺俄闻報晓鐘。","只待秋声滌心地，衲衣新洗健形容。"]', '诗', 'shi', '', NULL, '移居西湖作二首 一 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dbb47aa0-8c50-4f35-b263-351ac055223d', '移居西湖作二首 二', '移居西湖作二首 二', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["官園樹影晝陰陰，咫尺清涼莫浣心。","桃李別教人主掌，煙花不稱我追尋。","蜩[螗]晚噪風枝穩，翡翠閑眠宿處深。","爭似出塵地行止，東林苔徑入西林。"]', '["官园樹影晝陰陰，咫尺清涼莫浣心。","桃李別教人主掌，煙花不稱我追尋。","蜩[螗]晚噪风枝穩，翡翠闲眠宿处深。","爭似出塵地行止，东林苔徑入西林。"]', '诗', 'shi', '', NULL, '移居西湖作二首 二 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf037bf6-0846-4e07-a15a-5c782c6b56d8', '題玉泉寺', '題玉泉寺', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["高韻雙懸張曲江，聯題兼是孟襄陽。","後人才地誰稱短，前輩經天盡負長。","勝景飽於閑采拾，靈蹤銷得正思量。","時移兩板成塵跡，猶挂吾師舊影堂。"]', '["高韻雙懸張曲江，聯題兼是孟襄陽。","後人才地誰稱短，前輩經天尽負长。","勝景飽於闲采拾，靈蹤銷得正思量。","时移兩板成塵跡，猶挂吾師旧影堂。"]', '诗', 'shi', '', NULL, '題玉泉寺 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c40a925a-4ee8-4fc4-b54f-500aa315d040', '看金陵圖', '看金陵圖', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["六朝圖畫戰爭多，最是陳宮計數訛。","若愛蒼生似歌舞，隋皇自合恥干戈。"]', '["六朝圖畫戰爭多，最是陳宮計數訛。","若愛蒼生似歌舞，隋皇自合恥干戈。"]', '诗', 'shi', '', NULL, '看金陵圖 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ba2e903-92f4-4598-8669-ed0cf7482833', '寄南嶽泰禪師', '寄南嶽泰禪師', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["江頭默想坐禪峰，白石山前萬丈空。","山下獵人應不到，雪深花鹿在庵中。"]', '["江头默想坐禪峰，白石山前万丈空。","山下獵人應不到，雪深花鹿在庵中。"]', '诗', 'shi', '', NULL, '寄南嶽泰禪師 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c115628-e252-4131-9985-53ab7a102c15', '片雲', '片云', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["水底分明天上雲，可憐形影似吾身。","何妨舒作從龍勢，一雨吹銷萬里塵。"]', '["水底分明天上云，可怜形影似吾身。","何妨舒作從龙勢，一雨吹銷万里塵。"]', '诗', 'shi', '', NULL, '片雲 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d924414-65f1-4f6e-a7f3-42b4a8b2d07b', '寄清溪道者', '寄清溪道者', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["萬重千疊紅霞嶂，夜燭朝香白石龕。","常寄溪窗凭危檻，看經影落古龍潭。"]', '["万重千叠紅霞嶂，夜燭朝香白石龕。","常寄溪窗凭危檻，看經影落古龙潭。"]', '诗', 'shi', '', NULL, '寄清溪道者 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b632b049-5f19-4a75-b8d3-837e524a6002', '病中勉送小師往清涼山禮大聖', '病中勉送小師往清涼山禮大聖', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["豐衣足食處莫住，聖跡靈蹤好遍尋。","忽遇文殊開慧眼，他年應記老師心。"]', '["豐衣足食处莫住，聖跡靈蹤好遍尋。","忽遇文殊开慧眼，他年應記老師心。"]', '诗', 'shi', '', NULL, '病中勉送小師往清涼山禮大聖 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e089ac7-84f5-4b10-8a6f-6a56496568c2', '謝人惠拄杖', '謝人惠拄杖', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["何處雲根採得來，黑龍狂欲作風雷。","知師念我形骸老，教把經行拄綠苔。"]', '["何处云根採得来，黑龙狂欲作风雷。","知師念我形骸老，教把經行拄綠苔。"]', '诗', 'shi', '', NULL, '謝人惠拄杖 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e1aa2da2-4928-4d8b-9f20-13eca752111f', '送楚雲上人往南岳刺血寫法華經', '送楚云上人往南岳刺血寫法华經', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["剝皮刺血誠何苦，欲寫靈山九會文。","十指瀝乾終七軸，後來求法更無君。"]', '["剝皮刺血誠何苦，欲寫靈山九會文。","十指瀝乾終七軸，後来求法更無君。"]', '诗', 'shi', '', NULL, '送楚雲上人往南岳刺血寫法華經 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b9affc58-da60-4902-9b01-d89a0584d273', '送胎髮筆寄仁公', '送胎髮笔寄仁公', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["內唯胎髮外秋毫，綠玉新栽管束牢。","老病手疼無那爾，却資年少寫風騷。"]', '["內唯胎髮外秋毫，綠玉新栽管束牢。","老病手疼無那爾，却資年少寫风騷。"]', '诗', 'shi', '', NULL, '送胎髮筆寄仁公 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4167fad1-1a9c-4da2-8d6a-05a333ee7ed3', '謝西川曇域大師玉筯篆書', '謝西川曇域大師玉筯篆书', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["玉筯真文久不興，李斯傳到李陽冰。","正悲千載無來者，果見僧中有箇僧。"]', '["玉筯真文久不兴，李斯傳到李陽冰。","正悲千載無来者，果见僧中有箇僧。"]', '诗', 'shi', '', NULL, '謝西川曇域大師玉筯篆書 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('657ae538-3c71-46e3-a303-9a7861a0176e', '偶作寄王祕書', '偶作寄王祕书', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["七絲湘水秋深夜，五字河橋日暮時。","借問祕書郎此意，靜彈高詠有誰知。"]', '["七絲湘水秋深夜，五字河橋日暮时。","借问祕书郎此意，静彈高詠有誰知。"]', '诗', 'shi', '', NULL, '偶作寄王祕書 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd91b638-fb2e-468a-93b0-522080d2dab5', '謝人惠紙', '謝人惠紙', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["烘焙幾工成曉雪，輕明百幅疊春冰。","何消才子題詩外，分與能書貝葉僧。"]', '["烘焙幾工成晓雪，轻明百幅叠春冰。","何消才子題诗外，分與能书貝葉僧。"]', '诗', 'shi', '', NULL, '謝人惠紙 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e51ce086-48d7-4caa-a4f4-733da4811206', '答文勝大師清柱書', '答文勝大師清柱书', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["纔把文章干聖主，便承恩澤換禪衣。","應嫌六祖傳空衲，只向曹溪求息機。"]', '["纔把文章干聖主，便承恩澤換禪衣。","應嫌六祖傳空衲，只向曹溪求息機。"]', '诗', 'shi', '', NULL, '答文勝大師清柱書 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8052aa34-cb8e-448c-a7b2-5967d1efcf37', '寄懷曾口寺文英大師', '寄懷曾口寺文英大師', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["著紫袈裟名已貴，吟紅菡萏價兼高。","秋風曾憶西遊處，門對平湖滿白濤。"]', '["著紫袈裟名已貴，吟紅菡萏價兼高。","秋风曾憶西游处，门对平湖满白濤。"]', '诗', 'shi', '', NULL, '寄懷曾口寺文英大師 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('899be99c-22c0-46a2-94ca-e30774069dba', '懷道林寺道友', '懷道林寺道友', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["四絕堂前萬木秋，碧參差影壓湘流。","閑思宋杜題詩板，一日憑欄到夜休。"]', '["四絕堂前万木秋，碧參差影壓湘流。","闲思宋杜題诗板，一日憑欄到夜休。"]', '诗', 'shi', '', NULL, '懷道林寺道友 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('27b7211e-66eb-4f26-a999-fdac806700ec', '辭主人絕句四首 放鶴', '辞主人絕句四首 放鹤', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["華亭來復去芝田，丹頂霜毛性可憐。","縱與乘軒終誤主，不如還放却遼天。"]', '["华亭来复去芝田，丹頂霜毛性可怜。","縱與乘軒終誤主，不如還放却遼天。"]', '诗', 'shi', '', NULL, '辭主人絕句四首 放鶴 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('89928dc2-f766-4102-a53a-5c93de7584d4', '辭主人絕句四首 放猨', '辞主人絕句四首 放猨', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["堪憶春雲十二峰，野桃山杏摘香紅。","王孫可念愁金鎖，從放斷腸明月中。"]', '["堪憶春云十二峰，野桃山杏摘香紅。","王孫可念愁金鎖，從放斷腸明月中。"]', '诗', 'shi', '', NULL, '辭主人絕句四首 放猨 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d77f06d4-c6e4-4e51-96e0-1f64f22d9950', '辭主人絕句四首 放鷺鷥', '辞主人絕句四首 放鷺鷥', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["白萍紅蓼碧江涯，日暖雙雙立睡時。","顧揭金籠放歸去，却隨沙鶴鬬輕絲。"]', '["白萍紅蓼碧江涯，日暖雙雙立睡时。","顧揭金籠放归去，却隨沙鹤鬬轻絲。"]', '诗', 'shi', '', NULL, '辭主人絕句四首 放鷺鷥 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07aa13ab-2292-4707-a173-d3b143e1d357', '辭主人絕句四首 放鸚鵡', '辞主人絕句四首 放鸚鵡', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["隴西蒼巘結巢高，本爲無人識翠毛。","今日籠中強言語，乞歸天外啄含桃。"]', '["隴西蒼巘結巢高，本爲無人識翠毛。","今日籠中強言語，乞归天外啄含桃。"]', '诗', 'shi', '', NULL, '辭主人絕句四首 放鸚鵡 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed16a365-15b7-4513-912b-44f907cb6050', '猛虎行', '猛虎行', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["磨爾牙，錯爾爪，狐莫威，兔莫狡，饑來吞噬[取]腸飽。","橫行不怕日月明，皇天產爾爲生獰。","前村半夜聞吼聲，何人按劒燈熒熒。"]', '["磨爾牙，錯爾爪，狐莫威，兔莫狡，饑来吞噬[取]腸飽。","橫行不怕日月明，皇天產爾爲生獰。","前村半夜闻吼声，何人按劒灯熒熒。"]', '诗', 'shi', '', NULL, '猛虎行 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7465ad2-368c-4eb1-9acc-d3e13f23b293', '西山叟', '西山叟', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["西山中，多狼虎，去歲傷兒復傷婦。","官家不問孤老身，還在前山山下住。"]', '["西山中，多狼虎，去歲傷兒复傷婦。","官家不问孤老身，還在前山山下住。"]', '诗', 'shi', '', NULL, '西山叟 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aa76c5d9-f753-4dab-8bad-fd5fb5a1abf4', '君子行', '君子行', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["聖人不生，麟龍何瑞？梧桐不高，鳳凰何止？吾聞古之有君子，行藏以時，進退求己。","榮必爲天下榮，恥必爲天下恥。","苟進不如此，退不如此。","亦何必用虛僞之文章，取榮名而自美。"]', '["聖人不生，麟龙何瑞？梧桐不高，鳳凰何止？吾闻古之有君子，行藏以时，進退求己。","榮必爲天下榮，恥必爲天下恥。","苟進不如此，退不如此。","亦何必用虛僞之文章，取榮名而自美。"]', '诗', 'shi', '', NULL, '君子行 齊己 shi');
